INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '000-00'), 'GER', '{"alarmas": "Se debe referir a segundo nivel pacientes con asma no controlada o persistente moderada o grave, y a tercer nivel si el control es difícil o con comorbilidad atópica. Se hospitalizan pacientes con exacerbaciones graves o casi fatales, antecedentes o factores de riesgo para asma grave, PEF <60% pese a tratamiento, signos graves en reposo, saturación de oxígeno <92%, necesidad de oxígeno suplementario, hipoxemia, alteraciones del estado de conciencia, pulso paradójico o fatiga muscular respiratoria. Crisis asmáticas graves y fallo respiratorio inminente requieren atención en unidad de cuidados intensivos e intubación si es necesario.", "prevencion": "Aconsejar lactancia materna para disminuir riesgo de asma y sibilancias en lactantes. Evitar exposición prenatal y ambiental al humo de tabaco; ofrecer ayuda para abandono del hábito a padres fumadores. Implementar control ambiental multifactorial (evitar ácaros, mascotas, tabaco, humedad y hongos). En caso de asma ocupacional evitar exposición al alergeno causante; considerar tamizaje en trabajadores con síntomas que mejoran fuera del trabajo. Recomendar vacunación antigripal en pacientes asmáticos con factores de riesgo, aunque evidencia no es concluyente para vacunación universal. Durante embarazo mantener control estricto y tratamiento adecuado con esteroides inhalados (preferir budesonida) y beta-agonistas, ajustando el manejo periódicamente para prevenir complicaciones.", "diagnostico": "Se diagnostica asma en mayores de 18 años con síntomas variables (tos, sibilancias, disnea, opresión torácica, especialmente nocturnos) y evidencia de obstrucción bronquial reversible mediante espirometría con prueba broncodilatadora positiva o prueba terapéutica con corticoides si la espirometría es negativa. En pacientes con espirometría normal pero con sospecha clínica se utiliza variabilidad del flujo espiratorio máximo (>20%) o prueba de reto bronquial con metacolina. Se recomienda cuestionarios como el EBS para diagnóstico inicial en niños mayores. Se indican pruebas cutáneas para identificar atopia asociada.", "seguimiento": "Evaluar el control del asma clínicamente cada 3 a 6 meses mediante cuestionarios como ACQ y pruebas de función pulmonar. Antes de ajustar dosis verificar cumplimiento y técnica inhalatoria correcta. Al alcanzar control con dosis medias de esteroides inhalados se puede reducir la dosis al 50% en intervalos no menores a 3 meses. Si se controla con dosis bajas se puede usar una dosis al día. Reducir primero la dosis del esteroide antes que la del beta-agonista de larga duración. Contrarreferir a primer nivel una vez estabilizado. En pacientes que usan esteroides orales o inhalados en dosis altas valorar riesgo de osteoporosis, realizar seguimiento clínico óseo anual o bianual y aplicar medidas preventivas y farmacológicas adecuadas.", "tratamiento": "El tratamiento inicial para asma intermitente es beta-agonistas inhalados de corta duración a demanda. Para asma persistente leve se inicia con esteroides inhalados en dosis bajas (budesonida 200-800 mcg/día, fluticasona 100-500 mcg/día, beclometasona 200-1000 mcg/día) una o dos veces al día por al menos 3 meses. En asma persistente moderada se combina esteroides inhalados con beta-agonistas de larga duración o modificadores de leucotrienos, siempre evitando el uso de beta-agonistas solos. Para asma grave se usan dosis medias o altas de esteroides inhalados más beta-agonistas de larga duración, opcionalmente adicionando teofilina de liberación lenta o antileucotrienos. Esteroides orales se emplean solo en asma persistente grave con limitación diaria y exacerbaciones frecuentes, usualmente prednisona 1 mg/kg/día por 5-7 días en exacerbaciones. En crisis asmáticas se usan broncodilatadores inhalados de acción rápida (salbutamol inhalado cada 10-20 min hasta mejoría), corticosteroides sistémicos (hidrocortisona 300-400 mg/día dividida o metilprednisolona 60-80 mg) y oxígeno para mantener SaO2 >92%. Se recomienda uso de inhalador con espaciador para reducir efectos adversos orofaríngeos. Omalizumab está indicado en asma alérgica difícil de controlar con altas dosis de esteroides."}'::jsonb, false, 37654, '2026-11-26 05:23:06.796+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '000-00'), 'GRR', E'{"alarmas": "Cianosis, dificultad para hablar, somnolencia, taquicardia >120/min, uso de músculos accesorios, PEF <60% predicho, saturación O2 <90%, alteración conciencia o confusión, gasometría con hipoxemia o hipercapnia. Crisis no respondedoras a tratamiento inicial o con antecedente de asma casi fatal requieren referencia inmediata a segundo nivel o cuidados intensivos.", "prevencion": "Evitar exposición a humo de tabaco, alérgenos domésticos y ambientales (ácaros, pólenes, mohos), contaminación y factores irritantes. Educación sobre manejo y medicación, identificación y evitación de desencadenantes. Uso preventivo de β2-agonistas antes de ejercicio si asma inducida. Promover abandono de tabaquismo y ambientes libres de humo.", "diagnostico": "Historia clínica con síntomas típicos de tos, sibilancias, disnea y opresión torácica, especialmente nocturnos o tras ejercicio. Espirometría con obstrucción reversible post-broncodilatador y estudio de variabilidad del flujo espiratorio máximo si espirometría normal.", "seguimiento": "Control periódico clínico y con espirometría para valorar gravedad y ajustar tratamiento. Evaluar adherencia, técnica inhalatoria, control ambiental y educación. Revaluar si síntomas diurnos frecuentes, despertares nocturnos o uso de β2-agonista >3 veces/semana. Ajustar tratamiento según nivel de control, disminuir dosis si control mantenido por meses.", "tratamiento": "Asma leve intermitente: β2-agonistas inhalados de corta acción a demanda (p. ej., salbutamol inhalado 100 mcg, 1–2 inhalaciones cada 4-6 h según síntomas). Asma persistente: iniciar esteroide inhalado (p. ej., budesonida 200-400 mcg/día en 2 dosis). En crisis: oxígeno para saturación ≥90%, β2-agonista inhalado continuo 1 hora, glucocorticoides sistémicos si no hay respuesta o exacerbación grave (prednisona oral 40-50 mg/día por 5-7 días). Antileucotrienos y teofilina como opciones adyuvantes en pasos avanzados.", "texto_completo": "<Título de la GPC> \\n1 \\nGUÍA DE PRÁCTICA CLÍNICAGPC\\nDiágnostico y Tratamiento\\nDel Asma\\nEn Mayores de 18 Años\\n2009 \\nGuía de Referencia Rápida\\n\\n \\n2 \\n \\n \\nGuía de Referencia Rápida \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nDEFINICIÓN \\n \\nEl asma se define como una enfermedad inflamatoria crónica de las vías aéreas en la que \\nparticipan   diversas   células   y   mediadores   químicos;   se   acompaña   de   una   mayor   \\nreactividad traqueobronquial (hiperreactividad de las vías aéreas), que provoca en forma \\nrecurrente tos, sibilancias, disnea y aumento del trabajo respiratorio, principalmente en la \\nnoche  o  en  la  madrugada.  Estos  episodios  se  asocian  generalmente  a  una  obstrucción  \\nextensa  y  variable  del  flujo  aéreo  que  a  menudo  es  reversible  de  forma  espontánea  o  \\ncomo respuesta al tratamiento (GINA 2006). \\nFACTORES DE RIESGO \\n \\nEntre los factores ambientales que favorecen el desarrollo del asma se han identificado: \\nel  humo  de  tabaco  (niños  cuyas  madres  fumaron  durante  el  embarazo  o  niños  con  \\ntabaquismo   pasivo,   la   contaminación   aérea   automotriz,las   infecciones   respiratorias   \\nvirales,  la  exposición  a  concentraciones  elevadas  de  alérgenos  y  el  uso  de  antibióticos  \\ndurante la infancia. Con respecto a los alérgenos, se ha sugerido que la exposición cada \\nvez  mayor  a  alérgenos  intramuros  es  una  causa  asociada  a  una  alta  prevalencia  de  \\nenfermedades  respiratorias  alérgicas.  En  México  los  alérgenos  varían  según  la  región  \\ngeográfica,  y  la  tendencia  actual  del  desplazamiento  poblacional  a  zonas  urbanas  ha  \\nmodificado en las últimas décadas la respuesta en las pruebas cutáneas con alérgenos. \\nEn  la  Tabla  2  se  enlistan  los  principales  alérgenos  intra  y  extramuros  en  México.  Los  \\nalérgenos  presentes  en  las  recámaras  son  principalmente  ácaros,  epitelios  de  animales  \\ndomésticos, insectos y hongos. Los ácaros del polvo casero son la primera causa alérgica \\ndel  asma.  Entre  los  alérgenos  de  exteriores  los  más  importantes  son  los  pólenes  y  \\nhongos.Se ha asociado la exposición a tabaco ambiental con aumento de la gravedad de \\nasma,  (frecuencia  e  intensidad  de  crisis,  número  de  visitas  a  urgencias  al  año,  uso  de  \\nmedicación de asma, y frecuencia de crisis de asma que requieren intubación).\\n \\nJ45 Asma, J46 Estado Asmático  \\nGPC \\nDiagnóstico y Tratamiento del Asma en Mayores de 18 Años de Atención \\nISBN en trámite  \\n\\n \\n3 \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nEDUCACIÓN PARA LA SALUD \\n \\nLos  programas  educativos  cuyo  objetivo  \\nes  el  control  global  del  aire  del  interior,  \\nincluyendo     evitación     de     alérgenos     \\nsensibilizados   y   tabaco,   han   mostrado   \\nreducir los días con síntomas en niños. \\nLos   programas   educativos   dirigidos   a   \\ndisminuir   la   exposición   al   tabaco,   con   \\nestrategias          para     el     cambio     de     \\ncomportamiento   y   con   información   de   \\nfeedback   han   mostrado   disminuir   las   \\nvisitas al médico por crisis de asma. \\n \\nDIAGNÓSTICO TEMPRANO \\n \\n \\nEl  diagnóstico  clínico  del  asma  se  basa  \\nen    los    siguientes    síntomas:    disnea,    \\nsibilancias,  tos  y  sensación  de  opresión  \\ntorácica. \\nUna         prueba         terapéutica         con         \\nbroncodilatadores  o  con  corticosteroides  \\nsugiere el diagnóstico de asma \\n \\n \\nINTERROGATORIO \\n \\nLos  síntomas  aparecen  o  empeoran  en  la  noche,  sobretodo  en  la  madrugada  o  se  pueden  \\npresentar después del ejercicio físico. \\nLa  espirometría  obstructiva  con  test  broncodilatador  positivo  es  útil  en  el  diagnóstico  del  \\nasma. \\n Los síntomas aparecen tras una infección respiratoria viral. \\n \\nLos antecedentes familiares de asma o antecedentes personales atópicos sugieren el \\ndiagnóstico de asma. \\n \\nEXPLORACIÓN \\n \\nCuando el paciente asmático está mal controlado o en una crisis asmática, el examen físico \\nrevelará sibilancias espiratorias a la auscultación, que en algunos casos sólo se detectan con \\nla espiración forzada. En las exacerbaciones graves del asma la obstrucción bronquial es tan \\nintensa que las sibilancias pueden estar ausentes. Sin embargo, los pacientes graves suelen \\ntener  otros  signos  físicos  que  reflejan  su  condición,  como  cianosis,  somnolencia,  dificultad  \\npara hablar, taquicardia, tórax distendido, uso de músculos accesorios y tiraje intercostal. En \\npacientes bien controlados el examen físico del aparato respiratorio puede ser normal. \\n \\n\\n \\n4 \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nTRATAMIENTO \\n \\n•   Los  medicamentos  para  tratar  el  asma  se  clasifican  en:  controladores  y  de  \\nrescate \\n•    Se prefiere la terapia inhalada de los medicamentos debido a que así se deposita \\nmayor  concentración  directamente  en  las  vías  respiratorias    y  con  menor  riesgo  \\nde efectos adversos \\n•    El  asma  leve  intermitente  puede  ser  adecuadamente  controlada  sólo  con  beta-\\nadrenérgicos de acción corta a demanda. \\n•    Los  beta-adrenérgicos  de  corta  duración  son  los  fármacos  de  elección  como  \\nmedicación de rescate. \\n•    Prescribir    beta-agonista    de    acción  rápida  inhalados  a  todos  los  pacientes  con  \\nsíntomas de asma intermitente. \\n•    Cuando  los  síntomas  son  frecuentes  o  se  agravan  periódicamente,  se  requiere  \\nun tratamiento regular con un controlador \\n•    En  caso  de  asma  inducida  por  ejercicio  se  recomienda  utilizar  beta-agonista  de  \\nacción corta 15  minutos antes de empezar la actividad \\n•    Se debe iniciar esteroide inhalado en paciente que presente cualquiera de lo \\nsiguiente: \\n     Exacerbaciones de asma en los últimos 2 años \\nUso de beta-agonistas de acción corta más de 3 veces al día durante una \\nsemana o más Síntomas diurnos más de 3 veces en una semana o  despertar \\nnocturno una vez por semana \\n \\n\\n \\n5 \\n \\nVALORACIÓN CLÍNICA DE LA EXACERBACIÓN ASMÁTICA** \\n \\nDatos clínicos Leve Moderada Grave \\nParo respiratorio \\ninminente \\nDisnea o aumento del \\ntrabajo respiratorio \\nCaminando Hablando \\nLactantes - llanto \\nmás débil \\nDificultad para comer\\nEn reposo \\nEl niño deja de comer \\n \\nPuede acostarse Prefiere sentarse Se inclina hacia \\nadelante \\n \\nPuede hablar Oraciones Frases Palabras  \\nEstado de conciencia Puede estar agitado Generalmente \\nagitado \\nGeneralmente \\nagitado \\nMareado o confuso \\nFrecuencia respiratoria Aumentada Aumentada Habitualmente  \\n> 30/min. \\n \\n Frecuencia respiratoria normal en un niño despierto:  \\n \\n      Edad           Frecuencia normal \\n \\n < 2 meses< 60/min.  \\n 2-12meses  < 50/min.  \\n 1-5 años           < 40/min.  \\n 6-8 años              < 30/min.  \\nMúsculos accesorios y  \\nretracción supraesternal \\nNo Si Si Movimiento \\nparadójico \\ntoracoabdominal \\nSibilancias Moderadas, a \\nmenudo solo al final \\nde la espiración \\nFuertes Muy fuertes Ausentes \\nFrecuencia \\ncardiaca/min. \\n<100 100-120 >120 Bradicardia \\n Frecuencia cardiaca normal en niños:  \\n Lactantes   2-12 meses< 160/min.  \\n Preescolares 1-2 años< 120/min.  \\n Escolares 2-8 años< 110/min.  \\nPulso  paradójico Ausente  < 10 \\nmmHg \\nPuede estar presente  Presente Su ausencia sugiere \\nfatiga muscular \\nPEF después del \\nbroncodilatador inicial  \\n(% del predicho o  \\n% del mejor personal) \\nMayor de 80% 60-80%  aprox. < 60%   \\nPaO2 (al aire)† \\n \\ny/o \\n \\nPaCO2 † \\nNormal \\n.Generalmente  no  es  \\nnecesario   hacer   la   \\nprueba \\n \\nNormal \\n> 60mmHg \\n \\n \\n \\n<45mmHg \\n< 60mmHg \\nPosible ciañosis \\n \\n \\n>45 mmHg; \\ninsuficiencia \\nrespiratoria \\n \\nSaO2  > 95% 91-95% < 90%  \\n Se  desarrolla  hipercapnia  (hipoventilación)  más  rápidamente  en  \\nniños menores que en adultos y adolescentes \\n \\n*Nota: la presencia de varios parámetros, pero no necesariamente todos, indica la clasificación general de la exacerbación \\n† Nota: se usan tambien kilopascales; la conversión debe hacerse a este respecto.  \\n  ** The Global strategy for asthma management and prevention  Global Initiative for Asthma (GINA). 2006.\\n\\n \\n6 \\n \\n \\n \\n \\nCLASIFICACIÓN DEL ASMA POR SU GRAVEDAD, SEGÚN GINA \\n \\nAdaptado de:The Global strategy for asthma management and prevention  Global Initiative for Asthma \\n(GINA). 2006\\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nAsma intermitente \\n• Síntomas <1 vez por semana \\n• Exacerbaciones de corta duración \\n• Síntomas nocturnos no más de dos veces al mes \\n• FEV\\n1 \\no PEF > 80% del valor predicho \\n• Variabilidad en el PEF o FEV\\n1 \\n<20% \\nAsma persistente leve \\n• Síntomas >1 vez por semana, pero menos de 1 vez al día \\n• Exacerbaciones pueden afectar la actividad y el sueño \\n• Síntomas nocturnos más de dos veces por mes \\n• FEV\\n1 \\no PEF > 80% del valor predicho \\n• Variabilidad en el PEF o FEV\\n1 \\n<20 – 30% \\nAsma persistente moderada \\n• Síntomas diarios \\n• Exacerbaciones afectan la actividad y el sueño \\n• Síntomas nocturnos >1 vez a la semana \\n• Uso diario de β2 agonistas de acción corta inhalados \\n• FEV\\n1 \\no PEF 60-80% del valor predicho \\n• Variabilidad en el PEF o FEV\\n1\\n> 30% \\nAsma persistente grave \\n• Síntomas diarios \\n• Exacerbaciones frecuentes \\n• Síntomas diarios de asma nocturna \\n• Limitación para actividades físicas \\n• FEV\\n1\\n o PEF <60% del valor predicho \\n• Variabilidad en el PEF o FEV\\n1\\n> 30% \\n.\\nEXÁMENES DE LABORATORIO Y GABINETE \\n \\nLa realización de la espirometría con test broncodilatador ayuda a confirmar el diagnóstico de \\nasma  en  pacientes  con  síntomas  sugestivos  y  aporta  información  sobre  su  gravedad.  La  \\nnormalidad de la espirometría en un paciente con sospecha clínica no excluye el diagnóstico \\ny obliga a proseguir el estudio del paciente. \\nEn  los  pacientes  con  sospecha  clínica  de  asma  y  espirometría  normal,  se  debe  realizar  el  \\nestudio de variabilidad del FEM \\n\\n \\n7 \\n \\nAlgoritmos \\nFIGURA  1.  ALGORITMO  DE  TRATAMIENTO  HOSPITALARIO  DEL  ASMA  AGUDA  EN  HOSPITALES  \\nGENERALES REGIONALES Y DE TERCER NIVEL  \\n \\nRespuesta incompleta en 1-2 horas: \\n•   Factores de riesgo para asma casi \\nfatal \\n•  Exploración física: signos leves a \\nmoderados \\n•   PEF   <   60%      \\n•  Saturación  de  O\\n2\\n no mejora \\nPobre respuesta en 1-2 horas: \\n•   Factores de riesgo para asma casi \\nfatal \\n•   Exploración   física:   signos   graves,   \\nmareo, confusión \\n•  PEF      < 30% \\n•   PCO\\n2\\n   > 45 mmHg \\n•   PO\\n2\\n     < 60 mmHg \\nHospitalizar  \\n•  Oxígeno  \\n• β\\n2\\n agonista inhalado + \\nanticolinérgico \\n•  Glucoc ortic oide  sistémic o  \\n•  Magnesio  intravenoso  \\n•  Vigilancia del PEF, saturación de \\nO\\n2\\n, frecuencia cardiaca \\nAdmitir en cuidados intensivos \\n•   Oxígeno   \\n•  β\\n2\\n agonista inhalado +  anticolinérgico \\n•   Glucocorticoide   intravenoso   \\n•  Considerar  β\\n2\\n agonista o teofilina \\nintravenosos   \\n•  Posible intubación y ventilación \\nmecánica \\nValoración \\n•  Interrogatorio, exploración física y auxiliares diagnósticos (PEF o FEV\\n1\\n, saturación de oxígeno, \\ngasometría arterial si la exacerbación es grave, radiografía de tórax si se sospecha complicación \\nTratamiento inicial \\n•  Oxígeno para alcanzar una saturación de O\\n2\\n ≥ 90% (95% en niños)  \\n•  Inhalación  de  un  β\\n2\\n agonista de acción rápida de forma continua por una hora  \\n•   Glucocorticoides sistémicos si no hay respuesta inmediata, o si el paciente tomó recientemente \\nglucocorticoides orales, o si el evento es grave  \\n•  Está contraindicada la sedación en el tratamiento de una exacerbación \\nNueva evaluación en una hora \\nExploración física, PEF, saturación de O\\n2\\n y otros exámenes según se requieran \\nCriterios para episodios graves: \\n•  Antecedente o factores de riesgo para asma casi fatal  \\n•  PEF < 60% del predicho/mejor personal \\n•   Exploración física: signos graves en reposo \\n•   Sin   mejoría   después   del   tratamiento   inicial   \\nTratamiento: \\n•  Oxígeno \\n• β\\n2\\n agonista inhalado y anticolinérgico \\n•   Gluc oc ortic oides    sistémicos   \\n•   Magnesio   intravenoso   \\nRespuesta incompleta en 6-12 horas  \\n(ver arriba) \\n•  Considerar admisión a sala de \\ncuidados intensivos si no hay mejoría \\nen 6-12 horas\\n3er. Nivel \\nMejoría \\nS\\ní\\nN\\n\\n \\n8 \\n \\n \\nFIGURA 2. ALGORITMO PASOS EN EL TRATAMIENTO PARA EL CONTROL DEL ASMA PARA NIÑOS \\nMAYORES DE 5 AÑOS, ADOLESCENTES Y ADULTOS   \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nNivel de Control Acción de Tratamiento \\nControlada \\nParcialmente controlada\\nIncontrolada \\nGrave \\nMantener el control en el paso  \\nmás bajo\\nAvanzar pasos hasta lograr el control \\nAvanzar pasos hasta lograr el control\\nTratar como grave \\nDisminuir \\nIncrementar \\nDisminuye \\nIncrement\\na\\nPasos del tratamiento \\nSeleccionar uno Seleccionar unoAgregar uno o mas Agregar uno o \\nDosis bajas de \\nesteroides inhalados \\nGCI *** \\nDosis baja de GCI \\nmás agonista β\\n2-\\n de \\nlar\\nga duración\\nDosis media o alta de \\nGCI más β\\n2-\\nagonista de \\nlar\\nga duración \\nEsteroides orales \\n(dosis baja) \\nAntileucotrienos** \\nDosis alta o media \\nde GCI \\nAntileucotrienos \\nAnticuerpo anti-IgE\\nDosis baja de GCI \\nmás antileucotrieno\\n \\nTeofilina de \\nliberación  \\nsostenida  \\nDosis baja de GCI \\nmás teofilina de \\nliberación sostenida\\nOpciones  de \\ncontroladores*** \\nSi es necesario \\nβ2-agonistas de \\nacción corta \\nSi es necesario agonistas β2-adrenérgicos de acción corta \\n \\nEducación del asma  /  Control ambiental \\nPaso  1Paso  2Paso  4Paso  3Paso  5\\n  * GCI= Glucocorticoides inhalados  \\n **  Antagonista de Leucotrienos \\n*** Las opciones controladoras\\n  \\npreferidas se muestran en cuadros sombreados \\n \\nLos  tratamientos    alternativos  de  rescate  incluyen  anticolinergicos  inhalados,  β\\n2\\n-agonistas  orales  de  accion  corta,    \\nalgunos β\\n2\\n-agonistas  de  accion  prolongada,  y  teofilina  de  accion  corta. El  uso  regular  de  β\\n2\\n-agonistas  de  corta  y  \\nlarga acción no es aconsejable a menos que vaya acompañado por el uso regular de un esteroide inhalado. \\n \\nAdaptado de The Global strategy for asthma management and prevention  Global Initiative for Asthma (GINA). \\n2006. \\n\\n \\n9 \\n \\n \\nFIGURA 3. ALGORITMO CRITERIOS DE REFERENCIA Y CONTRARREFERENCIA DE PACIENTES \\nCON ASMA \\n \\n \\n \\n \\n \\n \\n \\nPaciente con Asma\\nEvalúa diagnóstico diferencial\\nProporcionar tratamiento supervisado:\\n* Educación\\n* Control ambiental\\n* Tratamiento Farmacológico\\nControl de \\nAsma\\nNo\\nContinuar \\ntratamiento\\nPrimer Nivel de \\nAtención\\nSegundo Nivel de \\nAtención\\nControl de \\nAsma\\nContinuar \\ntratamiento\\nSí \\nNo\\nTercer Nivel de \\nAtención\\nAsma moderada \\no grave\\nReferir a Neumología, Pediatría, Medicina Interna\\nEvaluar diagnóstico diferencial\\nSolicitar:\\n- Biometría hemática \\n- Espirometría\\n- Flujometría\\nProporcionar tratamiento supervisado:\\n* Educación\\n* Control ambiental\\n* Tratamiento Farmacológico\\n- Tratamiento de comorbilidad\\nReferir a Alergología, Neumología Pediátrica o \\nAdultos\\nEvaluar diagnóstico diferencial\\nAsma \\nintermitente o \\npersistente\\nSí\\nAsma persistente \\nmoderada/grave ó\\nDifícil control\\nPruebas \\ncutáneas\\nPositivas\\n- Educación\\n- Control ambiental\\n- Inmunoterapia por 3 años\\n- Tratamiento farmacológico\\nNegativasAsma controlada\\nContrarreferencia"}'::jsonb, false, 5141, '2026-11-26 05:23:41.458+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '032-08'), 'GER', '{"alarmas": "Referencia inmediata al segundo nivel si niño menor de 3 meses, bronquiolitis moderada o grave, saturación <90%, rechazo o intolerancia a vía oral (<50% ingesta), deshidratación, letargia, apnea o historia de apneas, taquipnea para la edad, dificultad respiratoria marcada, diagnóstico dudoso, comorbilidades (prematurez, cardiopatías congénitas, enfermedad pulmonar crónica, inmunodeficiencia), padres adolescentes, dificultad familiar para cuidado o evaluar gravedad, falta de mejoría clínica, situación socioeconómica desfavorable o dificultades de transporte.", "prevencion": "Fomentar lactancia materna exclusiva al menos 6 meses para proteger contra bronquiolitis. Evitar exposición al humo de tabaco y a ambientes contaminados. Reducir hacinamiento y evitar guarderías durante la infección y mientras persistan síntomas. Mantener higiene nasal con agua hervida o solución salina, fomentar lavado frecuente de manos y uso de geles alcohólicos. Informar a padres sobre signos de alarma y evitar exposición a lugares concurridos.", "diagnostico": "Diagnóstico clínico en niños menores de 2 años con rinorrea, tos, sibilancias o estertores crepitantes finos, dificultad respiratoria y signos de hiperinsuflación. Se utiliza la escala clínica validada para clasificar la gravedad (leve, moderada, grave). No se recomienda radiografía ni estudios sanguíneos de rutina, salvo duda diagnóstica o sospecha de complicaciones. La prueba rápida para Virus Sincitial Respiratorio (VSR) puede utilizarse para confirmar etiología y decisiones en aislamiento.", "seguimiento": "Revaloración clínica a las 24-48 horas tras consulta inicial para evaluar función respiratoria y estado general, especialmente en menores de 12 meses, niños menores de 2 meses, hombres o con antecedentes de hospitalización previa. Seguir de cerca en domicilio con educación a padres sobre signos de alarma; en caso de deterioro o signos de alarma acudir a urgencias.", "tratamiento": "Oxigenoterapia para saturación <90%, manteniendo saturación entre 90-94% con oxígeno por puntas nasales o nebulización. Nebulización de solución salina hipertónica al 3% mejora hidratación y reduce estancia hospitalaria; descartar antecedentes de atopia o asma antes de su uso. En niños con antecedentes de atopia o asma, usar una dosis única de salbutamol inhalado (100-200 mcg cada 4-6 horas). Paracetamol 10-15 mg/kg/dosis por vía oral cada 6-8 horas máximo 3 días para fiebre ≥38°C. No usar corticoesteroides, antibióticos, antiinflamatorios, antihistamínicos, descongestionantes ni inhibidores de leucotrienos. Adrenalina inhalada no rutinaria; considerar en no hospitalizados con precaución."}'::jsonb, false, 25561, '2026-11-26 05:13:37.504+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '032-08'), 'GRR', E'{"alarmas": "Referencia inmediata si edad <3 meses, prematurez, bronquiolitis moderada o grave, saturación <90%, rechazo o intolerancia a vía oral (<50% ingesta), deshidratación, letargia, apneas, taquipnea excesiva, dificultad respiratoria moderada-grave, diagnóstico incierto, comorbilidades, padres adolescentes o limitados para cuidado, antecedentes de muerte pulmonar en hermano menor de 5 años, sin mejoría tras tratamiento o condiciones sociales/ambientales desfavorables.", "prevencion": "Promover lactancia materna exclusiva al menos 6 meses. Evitar hacinamiento, exposición al humo de tabaco y lugares concurridos. Lavado frecuente de manos y uso de alcohol gel. Mantener al niño en casa durante infección y evitar guarderías en convalecencia. Evitar contacto con personas con infecciones respiratorias. Explicar signos de alarma y cuidados para manejo en domicilio.", "diagnostico": "Diagnóstico clínico en niños menores de 2 años con rinorrea, tos, dificultad respiratoria, sibilancias o estertores crepitantes finos; la prueba rápida puede identificar el virus, pero no es obligatoria en primer nivel. No se recomienda realizar radiografía de tórax ni estudios sanguíneos rutinarios salvo duda diagnóstica o sospecha de complicaciones.", "seguimiento": "Revaluar a las 24-48 horas para evaluar función respiratoria y estado general, especialmente en menores de 12 meses, menores de 2 meses, sexo masculino o con antecedentes de hospitalización. Explicar signos de alarma a los padres. Seguimiento domiciliario si buen estado general, gravedad leve (escala <3), saturación >94% y buena tolerancia oral. Acudir urgente ante cualquier deterioro o signos de alarma.", "tratamiento": "No se recomienda uso de corticoesteroides, antihistamínicos, inhibidores de leucotrienos, descongestionantes ni antibióticos. En casos con antecedentes de atopia o asma, se puede administrar una dosis única de salbutamol inhalado (1-2 disparos). Para fiebre ≥38°C, paracetamol oral 10-15 mg/kg por dosis cada 6-8 horas, máximo 60 mg/kg/día por hasta 3 días. En saturación <90%, administrar oxígeno por puntas nasales (3-5-10 l/min) para mantener saturación 90-94% y valorar referencia secundaria; nebulización con solución salina hipertónica 3% solo si se descarta atopia y se canaliza al segundo nivel.", "texto_completo": "Guía de Referencia Rápida \\nCatálogo Maestro de Guías de Práctica Clínica: IMSS-032-08 \\nGUÍA DE PRÁCTICA CLÍNICA\\n \\nGPC\\n \\n \\n \\nDiagnóstico y Tratamiento de\\n \\nB\\nRONQUIOLITIS \\nA\\nGUDA\\n \\nEn niñas/niños y en el Primer \\nNivel de Atención \\n \\nActualización \\n2015 \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nDurango 289- 1A Colonia Roma \\nDelegación Cuauhtémoc, 06700 México, DF. \\nPágina Web: www.imss.gob.mx \\n \\nPublicado por Instituto Mexicano del Seguro Social \\n© Copyright Instituto Mexicano del Seguro Social “Derechos Reservados”. Ley Federal de Derecho de Autor \\n \\nEditor General \\nCoordinación Técnica de Excelencia Clínica \\nCoordinación de Unidades Médicas de Alta Especialidad \\n2015 \\n \\nLa guía  de  referencia  rápida tiene  como  objetivo  proporcionar  al  usuario  las recomendaciones  clave de  la  guía \\nDiagnóstico  y  Tratamiento  de  Bronquiolitis  Aguda  En  niñas/niños  y en  el  Primer  Nivel  de  Atención, \\nseleccionadas con base a su impacto en salud por el grupo desarrollador, las cuales pueden variar en función  de la \\nintervención de que se trate, así como del contexto regional o local en el ámbito de su aplicación. \\n \\nPara mayor información, se sugiere consultar la guía en su versión extensa de “Evidencias y Recomendaciones” en el \\nCatálogo Maestro de Guías de Práctica Clínica, la cual puede ser descargada de Internet en: \\nhttp://www.cenetec.salud.gob.mx/interior/catalogoMaestroGPC.html\\n \\n \\nISBN 978-607-7790-84-6\\n \\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n \\n \\n1. Diagramas de Flujo \\n \\nAlgoritmo 1. Diagnóstico y Tratamiento de la Bronquiolitis Aguda \\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\n \\n2. Prevención primaria \\n \\nPROMOCIÓN A LA SALUD \\n \\nRecomendación Clave \\nGR*\\n \\nLos médicos deben alentar la lactancia materna exclusiva durante al menos 6 meses \\npara  disminuir  la  probabilidad  de  infecciones  de  las  vías  respiratorias  incluida  la \\nbronquiolitis aguda. \\nB  \\nmoderado \\nEvitar el hacinamiento en el domicilio de el/la niño/a. \\nEn  pacientes  con  sospecha  de  bronquiolitis    se  recomienda  permancer  en  casa \\ndurante el evento infeccioso y acudir a guarderías hasta terminar convalescencia \\nC \\n \\n \\nDETECCIÓN \\n \\nRecomendación Clave\\n \\nGR*\\n \\n \\nIdentificar los factores de riesgo relacionados a bronquiolitis grave desde la primera \\nconsulta, como son: \\n El/la  niño/a con  antecedentes  de  prematurez y bajo  peso  al  nacer \\n<2,500gramos. \\n Cardiopatías congénitas. \\n Enfermedad pulmonar crónica del prematuro. \\n El/la niño/a procedentes de familias con recursos bajos; particularmente durante \\nla época de invierno y principios de primavera. \\nC \\nB \\nmoderado \\n \\nEl diagnóstico de la  Bronquiolitis es clínico, la prueba  rápida permite identificar  el \\nagente causal. \\nA fuerte \\nC \\n \\n \\n \\n \\n \\n \\n3. Prevención Secundaria \\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\nDIAGNÓSTICO \\n \\nRecomendación Clave\\n \\nGR*\\n \\nDurante la época invernal, considerar la posibilidad de bronquiolitis en el/la niño/a \\nmenor de dos años con síntomas respiratorios. \\nD \\n \\n \\nSe recomienda sospechar bronquiolitis en el/la niño/a menor de 2 años con: \\n Rinorrea. \\n Tos. \\n Dificultad respiratoria. \\n Sibilancias o estertores crepitantes finos. \\n Hiperinsuflación y dificultad respiratoria. \\n \\nA fuerte \\n \\nLa  fiebre  no  es  síntoma  cardinal  de  la  bronquiolitis,  su  presencia  o  ausencia  no \\ndescarta la posibilidad de infección. \\nC \\n \\nCuando  la  temperatura  es  mayor  a 39º  C  (axilar),  se  recomienda  buscar \\ncomplicaciones u otras posibles enfermedades como diagnósticos diferenciales. \\nC \\n \\n \\nRealizar  una  valoración  clínica  completa  en  todo  paciente  con  diagnóstico  de \\nbronquiolitis, utilizando la escala validada para determinar la gravedad de la \\nenfermedad y definir la modalidad de tratamiento a otorgarse, en el primer nivel de \\natención (Cuadro 1). \\nC \\n \\n \\nEn pacientes con bronquiolitis que cursan con temperatura axilar mayor de 39° C se \\ndebe investigar  complicaciones  como  otitis media,  neumonía  bacteriana  o  buscar \\notro foco infeccioso como infección de vías urinarias. \\n \\nPunto de \\nBuena \\nPráctica \\nSe recomienda no realizar, de manera rutinaria, radiografía de tórax para establecer \\nel diagnóstico de bronquiolitis aguda. \\nA \\n \\nSe recomienda establecer el diagnóstico de bronquiolitis aguda en el/la niño/a menor \\nde 2 años con base en la historia clínica y los datos clínicos recuperados durante la \\nexploración física \\n \\nA \\nD \\n \\nSe sugiere no realizar ningún estudio para confirmar el diagnóstico de bronquiolitis en \\npacientes ambulatorios. \\nA \\nD \\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\nEl diagnóstico de la bronquiolitis es clínico,  se basa en la historia clínica y el examen \\nfísico, se recomienda no realizar estudios radiológicos ni sanguíneos, a menos que el \\ndiagnóstico no sea claro o se sospeche otro proceso infeccioso de vías aéreas bajas u \\notras entidades nosológicas. \\n \\nA \\nC \\nD \\n \\n \\nTRATAMIENTO FARMACOLÓGICO \\n \\nRecomendación Clave\\n \\nGR*\\n \\n \\nAntes de indicar nebulizacion de solución salina hipertónica al 3% debe descartarse \\nhistoria de atopia / asma.  \\n \\nA \\nEn caso de considerar aplicación de nebulización de solución salina hipertónica al 3% \\nenviar a siguiente nivel de atención. \\nA \\nEn pacientes con antecedentes de atopia, asma o alergia, se recomienda aplicar una \\nsola dosis de salbutamol en aerosol (por medio de el [1-2 disparos], si se cuenta con \\nel recurso) o por nebulizaciones. \\nA \\n \\nDespués de la aplicación de salbutamol, se recomienda examinar la respuesta clínica \\ncon base en la disminución de las sibilancias y cambios en la calificación de la escala \\nde gravedad, para determinar si el/la niño/a con bronquiolitis puede continuar con el \\ntratamiento en su domicilio. \\n \\nB \\nSe  recomienda  no  utilizar corticoesteroides, inhibidores  de  leucotrienos \\n(Montelukast)  antihistamínicos  o  descongestionantes  (sistémicos,  orales  o \\ninhalados),  vasoconstrictores  nasales  ni antibióticos  en  el  tratamiento de el/la \\nniño/a con bronquiolitis. \\nA \\nB, C, D \\n \\n \\nPuede prescribir  paracetamol  para  el  control  de  la  fiebre  cuando  la  temperatura \\n(axilar) sea igual o mayor a 38° C en el/la niño/a con bronquiolitis; a razón de 10 a \\n15 miligramos por kilogramos de peso por dosis (sin exceder 60 mg por kg al día) \\ncada 6 a 8 horas en un tiempo no mayor de 3 días. \\n. \\n \\nPunto de \\nBuena \\nPráctica. \\nLa Ribavirina no está recomendada para el tratamiento de la bronquiolitis aguda en \\nel/la niño/a. \\nB \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\nEn saturaciones de oxigeno menor de 90%  administrar oxígeno por medio puntas \\nnasales (3 a 5-10 l/min) o nebulizador ( FiO\\n2\\n >30%) para mantener saturación entre  \\n90 y 94%, estabilizar al paciente y evaluar envío al siguiente nivel de atención, \\nadministrando una dosis de adrenalina inhalada o salbutamol inhalado. \\n \\nA \\nC \\n \\n \\nTRATAMIENTO NO FARMACOLÓGICO \\n \\nRecomendación Clave\\n \\nGR\\n \\n \\nSe recomienda indicar a los padres (o tutores) las siguientes medidas para el manejo \\nambulatorio de el/la niño/a con bronquiolitis leve: \\n Suministrar líquidos en tomas pequeñas y frecuentes. \\n Ofrecer alimentos de manera habitual. \\n Aseo  nasal  con  agua  hervida  (tibia) o  solución  salina para  evitar  la \\nobstrucción.  \\n Colocar \\nel/la niño/a\\n en posición semisentado. \\n Evitar la exposición al humo del tabaco. \\n Evitar lugares concurridos. \\n Mantener \\nel/la  niño/a\\n en  un  ambiente  tranquilo;  evitando  el  arropamiento \\nexcesivo. \\n Tomar la temperatura varias veces al día. \\n \\nS, E \\nC \\nSe  recomienda  instruir  a  los  padres  (o  tutores)  sobre  los  signos  de  alarma  (ver \\nrecomendaciones de bronquiolitis para padres y cuidadores). \\nPunto de \\nBuena \\nPráctica \\n \\nCRITERIOS DE REFERENCIA \\n \\nRecomendación Clave\\n \\nGR*\\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\nConsiderar criterios de referencia al segundo nivel (o urgencias, de acuerdo  a las \\ncondiciones del caso) para atención integral y admisión hospitalaria: \\n Prematurez,  \\n Edad (<3 meses) \\n Gravedad de la enfermedad (Apartado 5.3) \\n Bronquiolitis moderada o grave (Cuadro 1 apartado 5.3) \\n Saturación <90% \\n Rechazo de alimento o intolerancia de la vía oral (ingesta aproximada inferior \\nal 50% de lo habitual) \\n Deshidratación \\n Letargia \\n Historia o presencia de apneas \\n Taquipnea para su edad \\n Dificultad respiratoria moderada o grave  \\n Diagnóstico dudoso. \\n Comorbilidad asociada \\n Padres adolescentes  \\n Dificultad de la familia para cuidar a el/la niño/a \\n Antecedente de un hermano muerto por enfermedad pulmonar (<5 años) \\n Sin mejoría clínica posterior al inicio del tratamiento \\n Situación  socioeconómica del  entorno,  factores  geográficos  y  dificultad  de \\ntransporte \\n Capacidad limitada de los padres o cuidadores para evaluar la gravedad de \\nel/la niño/a. \\n \\nC \\nD \\n \\nVIGILANCIA Y SEGUIMIENTO \\n \\nRecomendación Clave \\nGR\\n \\n \\nSe  recomienda  realizar  una  revaloración  a las  24  o  48  horas  para  determinar  la \\nfunción respiratoria y las condiciones generales de el/la niño/a. Particularmente, en \\nniñas/niños menores de 12 meses de edad que presentaron síntomas de infección en \\nlas vías respiratorias altas durante la época epidémica de la bronquiolitis. \\n \\nD \\n \\n \\nSe recomienda realizar seguimiento de el/la niño/a con bronquiolitis a las 24 o 48 \\nhoras  de  la  consulta  inicial,  teniendo  en  cuenta  especialmente  a  aquellos  con \\npredictores de empeoramiento en su evolución como son: \\n Menores de 2 meses \\n Sexo masculino y \\n Antecedentes de hospitalización \\nSe  sugiere  llevar  seguimiento  estrecho  en el/la  niño/a con  bronquiolitis  a las  48 \\nhoras y al final del padecimiento, sobre todo en el grupo de menores de 12 meses de \\nC \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\nedad. \\n \\n \\nSi durante el seguimiento en casa, hay deterioro del estado general o signos de \\nalarma (dificultad respiratoria, cianosis, apnea, rechazo al alimento o vómito), se \\nrecomienda acudir de inmediato al servicio de urgencias. \\n \\nC \\nD \\n \\nSe sugiere llevar  a  cabo  seguimiento  en  su  domicilio,  explicando  a los  padres  la \\nenfermedad  y  los  signos  de  alarma,  en  aquellos pacientes  que  cumplan  con  los \\nsiguientes criterios: \\n Buen estado general \\n Clasificación de gravedad<3 (ver cuadro 1) \\n Saturación de O\\n2\\n >94% \\n Tolerancia adecuada a la vía oral  \\n \\nPunto de \\nBuena \\nPráctica \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\n4. CUADROS O FIGURAS \\n \\nCUADRO I. ESCALA PARA VALORAR GRAVEDAD DE LA BRONQUIOLITIS \\n \\nPuntos 0 1 2 3 4 \\nFC: \\n \\n7 días-2 m 125-152  153-180 > 180   \\n(Edad) \\n2-12 m 120-140 140-160 > 160 \\n \\n12-24 m <110 110-160 > 160 \\nFR: \\n<2 m < 57  57-66  > 66 \\n(Edad) \\n2-6 m < 53  53-62 > 62 \\n \\n6-12 m < 47  47-55  > 55 \\n \\n12-24 m <30 30-40 >40 \\nRelación I/E \\nNormal Simétrica Invertida \\n(espiración \\nProlongada) \\nEsfuerzo \\nRespiratorio \\nNinguno Tiraje \\nSubcostal o \\nIntercostal \\nInferior  \\n+ tiraje \\nsupraesternal \\no aleteo nasal \\n+ tiraje \\nsupraesternal \\ny aleteo nasal \\n(tiraje \\nuniversal) \\nSibilancias \\nNo Al final de la \\nespiración \\nEn toda la \\nespiración  \\nInspiratorias y \\nespiratorias \\nTórax  \\nSilente \\n \\nEstertores \\nNo Crepitantes \\nen 1 campo \\nCrepitantes en \\n2 campos \\nCrepitantes en \\n3 campos \\nCrepitantes en \\n4 campos \\n \\n     \\nFC: Frecuencia Cardiaca/min; FR: Frecuencia respiratoria/min; I/E: Relación Inspiración-Espiración  \\nm: meses \\nBronquiolitis (estime la gravedad con base en la suma de los puntos encontrados en la valoración clínica): \\n leve 1 – 3  \\n moderada 4 – 7 y  \\n grave 8 – 14 puntos \\nFuente: Ramos Fernández JM, et al. Validación de una escala clínica de severidad de la bronquiolitisaguda.  \\nAnPediatr (Barc). 2013. \\nHartman ME and Cheifetz IM. PediatricEmergencies and resuscitation. In kliegman RM et al. Eds. Nelson \\nText \\nfile:///C|/Users/SONY/Desktop/GPC%20Bronquiolitis%20Actualizacion%202014/dx.doi.org/10.1016/\\nj.anpedi.2013.06.020 \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nRECOMENDACIONES DE BRONQUIOLITIS PARA PADRES Y CUIDADORES \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nLuz bronquiolar \\nnormal \\nBronquio \\nPulmones \\n¿Qué es la bronquiolitis? \\nLa bronquiolitis es resultado de la disminución del paso \\nde  aire  en  los  pulmones  de el/la  niño/a por \\ninflamación bronquial. Esto puede hacer que sea difícil \\npara el/la niño/a respirar.  \\n \\nLa bronquiolitis puede ser  causada por varios virus, \\npero el mayor número de casos es producida por el \\nVirus  Syncytial respiratorio (RSV). \\n \\nLa  mayor  parte  de niñas/niños que  sufre  esta \\ninfección se encuentran en los primeros dos años de \\nvida.  Es  más  frecuente  en  los  meses  de  invierno  y \\nusualmente solo causa síntomas de un leve resfriado. \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n \\n¿Se puede prevenir la bronquiolitis? \\nLos virus que producen los cuadros de bronquiolitis, son los responsables de los cuadros de gripa / \\nresfriado de niñas/niños mayores y adultos, por lo tanto se sugieren las siguientes medidas:  \\n Lavado  de  manos  con  agua  y  jabón  o  aplicación  de  alcohol  gel  : antes  y  después  de  la \\npreparación de alimentos y de tocar a el/la niño/a. \\n Lactancia materna: Uso de lactancia materna exclusiva los primeros 6 meses de edad y si es \\nposible continuar hasta el primer año de vida. \\n Evitar  lugares  concurridos:  plazas,  cines, centros  comerciales  o  lugares  de  esparcimiento \\ndonde incremente la probabilidad de contacto con enfermos. \\n Evitar el contacto con enfermos de infección de vías aéreas superiores: evitar el contacto de \\npersonas ya con síntomas de la enfermedad (hermanos menores de 5 años y  adultos). \\n Evitar exposición al humo de tabaco: en cigarro o ropa impregnada con el olor.  \\n \\n¿Cuáles son los síntomas de bronquiolitis? \\n La bronquiolitis inicia como un resfriado común. El/la niño/a puede tener congestión o salida \\nde moco nasal y algunas veces temperatura y tos. \\n Después de algunos días con el cuadro , la tos puede empeorar. \\n La respiración de el/la niño/a es más rápida de lo normal y puede ser ruidosa,  lo cual puede \\nproducir un mayor esfuerzo para respirar.  \\n Algunas veces en niñas/niños muy pequeños, bronquiolitis puede producir pausas en su \\nrespiración. \\n Cuando la respiración incrementa y causa dificultad para respirar, el niño puede no ser capaz \\nde tomar la cantidad usual de seno materno o formula láctea, con disminución del número de \\npañales con orina. \\n El/la niño/a puede estar decaído después de alimentarse y volverse irritable o llorón.  \\n \\n¿Cómo puedo ayudar a mi bebe? \\n Si es difícil llevar a cabo la alimentación, trata de ofrecerle cantidades pequeñas de leche más \\nseguido. \\n Si el/la niño/a presenta fiebre, puedes utilizar fomentos de agua para disminuirla, o bañarlo en \\ntina con agua tibia. \\n La  bronquiolitis  es  causada  por  virus,  por  lo  cual  los  antibióticos    NO  PROVEEN  ningún \\nbeneficio.  \\n \\n¿Cuántos días dura la bronquiolitis? \\n La mayoría de niñas/niños  con bronquiolitis, logran la recuperación después de dos semanas, \\naunque la mayoría puede continuar con tos por algunas semanas más. \\n El/la niño/a puede  regresar a cuidados de guardería tan pronto como su alimentación sea \\nnormal y no presente dificultad en la respiración. \\n\\nDiagnóstico y Tratamiento de Bronquiolitis Aguda En niñas/niños y en el Primer Nivel de Atención \\n \\n*Grado de Recomendación \\n \\n \\n Si hay una adecuada recuperación , no es necesario nueva valoración medica.  \\n \\n¿Cuándo debo acudir al medico? \\n Cuando el/la niño/a tenga dificultad para respirar (respiración rápida jadeante, hundimiento \\nde costillas,  hundimiento del pecho, al respirar apertura las alas de la nariz, o respiración muy \\nsuperficial que impide que se expanda el pecho).  \\n Cuando disminuya la alimentación a la mitad de lo que usualmente ingiere el/la niño/a.  \\n Deje de orinar en 4 horas. \\n Fiebre mayor a 38°C. \\n Irritabilidad, llanto difícil de controlar o que se encuentre somnoliento. \\n Durante la respiración presente pausas para respirar.  \\n Saliva espesa con ausencia de lagrimas durante el llanto.  \\n Cambio de coloración de piel o labios"}'::jsonb, false, 5558, '2026-11-26 05:14:15.797+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '041-08'), 'GER', '{"alarmas": "Presencia de síntomas severos o persistentes a pesar de tratamiento adecuado, complicaciones como otitis media o sinusitis recurrente, intolerancia grave a medicamentos, necesidad de esteroides sistémicos para control, rinitis asociada a asma no controlada, sospecha de patologías no alérgicas (epistaxis, rinorrea o taponamiento unilateral, cefalea severa, anosmia), o hallazgos de masas o pólipos nasales. Estos requieren referencia a segundo nivel para evaluación especializada, diagnóstico diferencial, inmunoterapia o cirugía.", "prevencion": "Recomendar evitar exposición a alérgenos identificados, especialmente ácaros de polvo mediante uso de acaricidas, cubrecamas y filtros HEPA. No se recomienda evitar mascotas para prevención primaria. Mantener ambiente con control adecuado de humedad y temperatura para reducir alérgenos. Informar al paciente sobre naturaleza crónica de la rinitis alérgica y la importancia de la adherencia al tratamiento y medidas ambientales para control de síntomas.", "diagnostico": "Diagnóstico clínico basado en historia y exploración física típicas con congestión nasal, rinorrea, prurito nasal, estornudos, palidez mucosa nasal, lagrimeo y eritema conjuntival. Se confirma con pruebas específicas de IgE (cutáneas de punción o serológicas) en pacientes que no responden al tratamiento empírico, con sospecha clínica incierta, o para identificar alérgenos específicos. No se recomiendan rutinariamente estudios de imagen, rinometría acústica, pruebas olfatorias, óxido nítrico nasal, pruebas alimentarias ni provocación nasal con alérgenos. La tomografía y resonancia se reservan para descartar otras patologías como pólipos o tumores.", "seguimiento": "Evaluar respuesta clínica periódica mediante historia y escala TNSS. Continuar o ajustar tratamiento farmacológico según mejoría. Orientar sobre técnicas correctas de aplicación de sprays nasales para minimizar efectos adversos. Vigilar aparición de efectos secundarios (epistaxis, irritación). En pacientes con diagnóstico inicial incierto o respuesta insuficiente, realizar pruebas de IgE específicas. Referir oportunamente a alergología si persisten síntomas o complicaciones. Promover control ambiental sostenido y educación al paciente.", "tratamiento": "Primera línea: esteroides nasales (ej. fluticasona 110 mcg/día inicialmente, luego 55 mcg/día) administrados vía intranasal de forma continua para control de síntomas; antihistamínicos orales de segunda generación (ej. levocetirizina 5 mg cada 24 horas) para síntomas predomínate de prurito y estornudos. Antihistamínicos intranasales (ej. azelastina spray) pueden considerarse como opción en rinitis estacional, perenne o episódica. Antagonistas de leucotrienos (montelukast) no recomendados como primera línea, pueden considerarse en pacientes con rinitis y asma refractarios. Tratamiento combinado (ej. esteroide nasal más antihistamínico) puede usarse si falla monoterapia. En pacientes refractarios, referir para inmunoterapia subcutánea o sublingual. En casos de hipertrofia de cornetes con obstrucción persistente y falla al tratamiento farmacológico, considerar cirugía para reducción de cornetes inferiores."}'::jsonb, false, 38775, '2026-11-26 05:20:45.79+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '041-08'), 'GRR', E'{"alarmas": "Referir a segundo nivel si hay síntomas nasales obstructivos persistentes con hipertrofia de cornetes que no mejoran con tratamiento farmacológico, asma severa, inestable o no controlada, o si la rinitis no responde a tratamiento combinado y/o inmunoterapia. Sospecha de diagnóstico alternativo o complicaciones como infección respiratoria, y presencia de signos sistémicos o deterioro significativo en la calidad de vida.", "prevencion": "Recomendar evitar exposición a alérgenos identificados como causantes (pólenes, ácaros, animales domésticos). Mantener limpieza ambiental, uso de filtros para polvo, evitar irritantes como humo o contaminantes. Educación al paciente sobre manejo ambiental y cumplimiento de tratamiento para evitar exacerbaciones. Informar sobre evitar medicamentos que puedan agravar síntomas y promover consulta temprana ante empeoramiento.", "diagnostico": "El diagnóstico de rinitis alérgica se basa en historia clínica y exploración física que incluyan congestión nasal, rinorrea clara, prurito nasal, estornudos, palidez de mucosa nasal, lagrimeo y eritema conjuntival. Se confirma con pruebas de IgE específicas (cutánea o sérica) en pacientes que no mejoran con tratamiento empírico. Criterios clave incluyen antecedentes familiares de atopía, dermatitis atópica, alergia alimentaria o asma, y signos físicos como ojeras alérgicas o pliegue nasal. Puntaje SFAR >7 apoya el diagnóstico.", "seguimiento": "Reevaluar al paciente entre 2 a 4 semanas tras iniciar tratamiento para valorar respuesta. Si hay mejoría, continuar y reducir gradualmente dosis, manteniendo por un mes. Vigilar recurrencia de síntomas y adaptar tratamiento según severidad e intermitencia. Controlar adherencia y exposición a alérgenos. Monitorizar aparición de nuevos síntomas o complicaciones para referencia o ajuste terapéutico.", "tratamiento": "Para rinitis alérgica leve a moderada/severa, iniciar antihistamínicos orales de segunda generación: dosis según medicamento disponible, vía oral, duración según mejoría. Descongestivos nasales sólo de 3 a 5 días si necesario. En caso de persistencia o falta de respuesta, agregar esteroide nasal tópico (ejemplo: mometasona 200 mcg/día intranasal) por 2 a 4 semanas. Terapia combinada (antihistamínico intranasal + esteroide nasal) si falla monoterapia. No usar antagonistas de leucotrienos de primera línea. Referir a alergología para inmunoterapia sublingual o subcutánea si refractario, excepto en asma severa, inestable o no controlada.", "texto_completo": "GUÍA DE PRÁCTICA CLÍNICA GPC\\n \\n \\n \\n \\n                                                                                                                   \\n \\n \\nDiagnóstico y tratamiento de \\nRINITIS ALÉRGICA\\n \\nGuía de Referencia Rápida\\nCatálogo Maestro de Guías de Práctica Clínica: IMSS-041-08\\nActualización \\n2017 \\n\\nDiagnóstico y Tratamiento de Rinitis Alérgica \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nDurango 289- 1A Colonia Roma \\nDelegación Cuauhtémoc, 06700 México, DF. \\nPágina Web: www.imss.gob.mx \\n \\nPublicado por Instituto Mexicano del Seguro Social \\n© Copyright Instituto Mexicano del Seguro Social “Derechos Reservados”. Ley Federal de Derecho de Autor \\n \\nEditor General \\nCoordinación Técnica de Excelencia Clínica \\nCoordinación de Unidades Médicas de Alta Especialidad \\n \\nLa  guía  de  referencia  rápida  tiene  como  objetivo  proporcionar  al  usuario  las  recomendaciones  clave  de  la  guía  \\nDiagnóstico  y  tratamiento  de  rinitis  alérgica,  seleccionadas  con  base  a  su  impacto  en  salud  por  el  grupo  \\ndesarrollador,  las  cuales  pueden  variar  en  función  de  la  intervención  de  que  se  trate,  así  como  del  contexto  regional  o  \\nlocal en el ámbito de su aplicación. \\n \\nPara mayor información, se sugiere consultar la guía en su versión extensa de “Evidencias y Recomendaciones” en el \\nCatálogo Maestro de Guías de Práctica Clínica, la cual puede ser descargada de Internet en:  \\n \\nhttp://www.imss.gob.mx/profesionales-salud/gpc\\n \\nhttp://www.cenetec.salud.gob.mx/contenidos/gpc/catalogoMaestroGPC.html# \\n \\n \\nDebe  ser  citado  como:  Diagnóstico  y  tratamiento  de  rinitis  alérgica.  Guía  de  Rerencia  Rápida:  Guía  de  Práctica  \\nClínica. México, CENETEC;  \\nDisponible en: http://www.imss.gob.mx/profesionales-salud/gpc\\n \\nhttp://www.cenetec.salud.gob.mx/contenidos/gpc/catalogoMaestroGPC.html# \\n \\nISBN en trámite \\n\\nDiagnóstico y tratamiento de rinitis alérgica \\n \\n \\n \\n1. Diagramas de Flujo \\nAlgoritmo 1. Evaluación y Tratamiento de Rinitis Alérgica. \\n \\n \\n\\nDiagnóstico y tratamiento de rinitis alérgica \\n \\n \\n \\nAlgoritmo 2. Diagnóstico \\nSíntomas de Rinitis\\nPrurito\\nEstornudos\\nRinorrea hialina\\nObstrucción nasal\\nOtros: Hiposmia, descarga \\nposterior, carraspera,lagrimeo\\n¿Es de etiología \\ninfecciosa?\\nSI\\nDatos \\nsospechosos de \\nRinitis Alérgica\\nAntecedentes heredofamiliares: atopia\\nAntecedentes patológicos personales: \\ndermatitis atópica, alergia alimenticia, asma\\nTiempo de presentación\\nExploración física: ojeras alérgicas, saludo \\nalérgico, pliegue nasal, hipertrofia y/o \\npalidez de cornetes\\n¿Cumple con el \\ncuadro clínico?\\nDiagnostico \\npresuntivo de \\nRinitis Alérgica\\nNO\\nIniciar tratamiento \\nempirico\\nCategorizar al \\npaciente\\nCronicidad\\nEpisódica\\nIntermitente\\nPersistente\\nTemporalidad\\nEstacional\\nPerenne\\nSeveridad\\nLeve\\nModerada/\\nSevera\\n¿Responde al \\ntratamiento?\\nSI\\nDerivar para \\nrealización de IgE \\nespecifica: \\nCutánea o sérica\\nNO\\nDiagnostico \\nDefinitivo\\nNO\\nDar tratamiento de \\nacuerdo a etiología\\nConsiderar \\ndiagnósticos \\ndiferenciales\\nSI\\nContinuar manejo \\ny vigilancia\\n \\n\\nDiagnóstico y tratamiento de rinitis alérgica \\n \\n \\n \\nAlgoritmo 3. Tratamiento \\nC\\nO\\nM\\nB\\nI\\nN\\nA\\nD\\nA\\nM\\nO\\nN\\nO\\nT\\nE\\nR\\nA\\nP\\nI\\nA\\nTratamiento de acuerdo a \\nCategorización del paciente\\nSíntomas \\nIntermitentes\\nEvitar la exposición al alergeno\\nSíntomas \\nPersistentes\\nSíntomas \\nepisódicos\\nAntihistamínico oral \\no nasal.\\nDescongestivo nasal \\n(en caso necesario) de \\n3 a 5 días.\\nLeveModerada/severaLeveModerada/severa\\nAntihistamínico oral\\nAntihistamínico nasal \\nAntihistamínico oral\\nAntihistamínico nasal\\n¿Hay mejoría?VigilanciaSI\\nNO\\nEsteroide Nasal\\nRevaloración en 2 \\na 4 semanas\\n¿Hay mejoría?\\nEsteroide nasal + Antihistamínico intranasal\\nEsteroide Nasal + Descongestivo nasal (3-5 \\ndías)\\nSI\\nNO\\n¿Hay mejoría?\\nAntihistaminico oral + Descongestivo oral\\nAntihistaminico nasal + Esteroide nasal\\nVigilancia\\nConsiderar:\\nInmunoterapia específica\\nManejo quirúrgico\\nSINO\\nReducir gradualmente \\ndosis \\nContinuar por 1 mes\\n\\nDiagnóstico y tratamiento de rinitis alérgica \\n \\n \\n \\n2. Diagnóstico y Tratamiento \\nDIAGNÓSTICO \\n \\nRecomendación Clave \\nGR* \\nSe debe hacer diagnóstico de Rinitis Alérgica cuando los pacientes cuenten con historia \\nclínica y exploración física consistentes con una causa alérgica y uno o más de los \\nsiguientes signos y síntomas: \\n Congestión nasal \\n Rinorrea \\n Prurito nasal \\n Estornudos \\n Palidez de mucosa nasal \\nLagrimeo y eritema conjuntival \\nRecomendación \\nAAP \\nGuía American \\nAcademy of \\nOtolaryngology \\n2015 \\nSe  debe  realizar  e  interpretar  la  prueba  especifica  de  IgE  (cutánea  o  serica)  en  \\npacientes  con  diagnóstico  clínico  de  rinitis  alergica  que  no  respondan  al  tratamiento  \\nempírico. \\nRecomendación\\nAAP \\nGuía American \\nAcademy of \\nOtolaryngology \\n2015 \\n \\nTRATAMIENTO \\n \\nRecomendación Clave \\nGR* \\nSe debe recomendar el uso de esteroides nasales en pacientes con diagnóstico clínico \\nde Rinitis Alérgica cuyos síntomas afecten su calidad de vida. \\nRecomendación \\nfuerte \\nAAP \\nGuía American \\nAcademy of \\nOtolaryngology \\n2015 \\nSe deben recomendar antihistamínicos orales de segunda generación en pacientes con \\nRinitis Alérgica en que predominen síntomas como estornudos y prurito. \\nRecomendación \\nfuerte \\nAAP \\nGuía American \\nAcademy of \\nOtolaryngology \\n2015 \\nLos  médicos  pueden  ofrecer  antihistamínicos  intranasales  en  pacientes  con  rinitis  \\nalérgica estacional, perenne o episódica. \\nOpcional\\nAAP \\nGuía American \\nAcademy of \\nOtolaryngology \\n2015 \\n\\nDiagnóstico y tratamiento de rinitis alérgica \\n \\n \\n \\nNo se deben recomendar antagonistas del receptor de leucotrieno como primera línea \\nen el tratamiento de pacientes con Rinitis Alérgica. \\nRecomendación\\nAAP \\nGuía American \\nAcademy of \\nOtolaryngology \\n2015 \\nLos  médicos  pueden  recomendar  terapia  farmacológica  combinada  en  pacientes  con  \\nrinitis alérgica que presentaron falla a la monoterapia. \\nOpcional\\nAAP \\nGuía American \\nAcademy of \\nOtolaryngology \\n2015 \\nLos médicos deben referir a los pacientes con un alergólogo para iniciar inmunoterapia \\n(sublingual  o  subcutánea)  a  aquellos  pacientes  que  no  respondan  adecuadamente  al  \\ntratamiento farmacológico con o sin control ambiental. \\nRecomendación \\nfuerte \\nAAP \\nGuía American \\nAcademy of \\nOtolaryngology \\n2015 \\nNo  se  debe  iniciar  inmunoterapia  en  pacientes  con  asma  severa,  inestable  o  no  \\ncontrolada. \\nRecomendación \\nfuerte \\nAAP \\nGuía American \\nAcademy of \\nOtolaryngology \\n2015 \\nSe deben referir a cirugía para una reducción de cornetes inferiores a los pacientes con \\nrinitis  alérgica  con  síntomas  nasales  persistentes  (obstructivos)  e  hipertrofia  de  \\ncornetes que hayan presentado falla al tratamiento farmacológico. \\nOpcional\\nAAP \\nGuía American \\nAcademy of \\nOtolaryngology \\n2015 \\n \\n*Grado de Recomendación \\n \\n \\n\\nDiagnóstico y Tratamiento de Rinitis Alérgica \\n \\n \\n \\n3. CUADROS O FIGURAS \\n \\nCuadro 1. Historia y Exploración física de Rinitis Alérgica \\nSíntomas presentes Hallazgos en la Historia ClínicaHallazgos en la exploración \\nfísica \\nCongestión nasal Naturaleza de los síntomas estacional \\nvs perenne \\nRinorrea clara \\nEstornudos   Síntomas   al   exponerse   a   diversos   \\nagentes   (animales,   particularmente   \\nplantas) \\nInflamación  y  coloración  azulada  \\no palidez de mucosa nasal \\nRinorrea  Medicamentos utilizadosHallazgos     oculares     (lagrimeo, \\ninflamación conjuntival, inyección \\nde la esclerótica)  \\nPrurito    en    nariz,    ojos,    paladar     Historia    familiar    de    atopia    o    de    \\nenfermedades alérgicas \\nAclaramiento        de        garganta        \\nfrecuente \\nDescarga   retronasal   Síntomas   al   exponerse   a   irritantes   \\n(hace       origen       alérgico       menos       \\nprobable) \\nOjeras alérgicas \\nPliegues  infraorbitarios  de  Denny  \\nMorgan \\nAclaramiento de la garganta Síntomas   de   infección   respiratoria \\nsuperior  (hace  origen  alérgico  menos  \\nprobable) \\nArrugas o líneas nasales\\nTos    Ausencia    de    cuerpo    extraño,    \\ntumor,   purulencia   que   sugiera   \\ninfección \\nMalestar general \\nFatiga \\nFuente:  Seidman  M,  Gurgel  R,  Lin  S,  Schwartz  S,  Baroody  F,  Bonner  J.  Clinical  Practice  Guideline:  Allergic  \\nRhinitis. American Academy of Otolaryngology—Head and Neck Surgery, 2015, Vol. 152(1S) S1–S43 \\n \\nCuadro 2. Total Nasal Symptom Score \\nPor favor responda las siguientes preguntas: \\n1.- Califique por favor cómo ha sido la congestión nasal en el pasado: \\n 12 horasUltimas 2 semanas\\nNada                                                                                                                 00                                                                                                                 \\nLeve (síntomas presentes pero se toleran fácilmente)11 \\nModerada (síntomas molestos pero tolerables)22 \\nSevera    (síntomas    difíciles    de    tolerar,    interfieren    con    sus    \\nactividades) \\n33 \\n \\n2.- Califique por favor cómo ha sido el escurrimiento nasal en el pasado: \\n 12 horasUltimas 2 semanas\\nNada                                                                                                                 00                                                                                                                 \\nLeve (síntomas presentes pero se toleran fácilmente)11 \\nModerada (síntomas molestos pero tolerables)22 \\nSevera    (síntomas    difíciles    de    tolerar,    interfieren    con    sus    \\nactividades) \\n33 \\n \\n \\n \\n\\nDiagnóstico y tratamiento de rinitis alérgica \\n \\n \\n \\n3.- Califique por favor cómo ha sido el prurito nasal en el pasado: \\n 12 horasUltimas 2 semanas\\nNada                                                                                                                 00                                                                                                                 \\nLeve (síntomas presentes pero se toleran fácilmente)11 \\nModerada (síntomas molestos pero tolerables)22 \\nSevera    (síntomas    difíciles    de    tolerar,    interfieren    con    sus    \\nactividades) \\n33 \\n \\n \\n4.- Califique por favor cómo han sido los estornudos en el pasado: \\n 12 horasUltimas 2 semanas\\nNada                                                                                                                 00                                                                                                                 \\nLeve (síntomas presentes pero se toleran fácilmente)11 \\nModerada (síntomas molestos pero tolerables)22 \\nSevera    (síntomas    difíciles    de    tolerar,    interfieren    con    sus    \\nactividades) \\n33 \\n \\n \\n5.- Califique por favor sus dificultades para dormir con los síntomas nasales: \\n 12 horasUltimas 2 semanas\\nNada                                                                                                                 00                                                                                                                 \\nLeve (síntomas presentes pero se toleran fácilmente)11 \\nModerada (síntomas molestos pero tolerables)22 \\nSevera    (síntomas    difíciles    de    tolerar,    interfieren    con    sus    \\nactividades) \\n33 \\nCalificación Total:\\n00\\nAdaptado de:  http://www.nwentallergy.com/docs/Total_Nasal_Symptom_Score.pdf                                                       \\n \\nCuadro 3. Total Ocular Symptom Score \\n \\nCasi nunca Casi siempre\\n1           Quemazón/picazón           123           4           56\\n2           Lagrimeo           123           4           56\\n3           Sequedad           123           4           56\\n4           Prurito           123           4           56\\n5           Pesadez/Cansancio           123           4           56\\n6           Visión           borrosa           123           4           56\\n7 Sensación de presencia en los ojos 123 4 56\\n8 Dificultad para ver de día, requiere lentes para sol123 4 56\\n9 Dificultad para ver en lugares oscuros123 4 56\\n10 Halos de luz 123 4 56\\nAdaptado  de:  Lee  BL,  Gutierrez  P,  Gordon  M,  Wilson  MR,  Cioffi  GA,  Ritch  R,  Sherwood  M,  Mangione  CM  \\nThe  Glaucoma  Symptom  Scale.  A  brief  index  of  glaucoma-specific  symptoms.  Arch  Ophthalmol.  1998  \\nJul;116(7):861-6 \\n \\n \\n \\n \\n\\nDiagnóstico y tratamiento de rinitis alérgica \\n \\n \\n \\n \\nCuadro 4. Score for Allergic Rhinitis (SFAR) \\nParámetro (síntomas y meses)Hallazgo Puntaje\\nCongestión nasal en el último año Ausente 0\\n Presente           1\\nRinorrea en el último año Ausente 0\\n Presente           1\\nEstornudos en el último año Ausente 0\\n Presente           1\\nSíntomas perennes Ausente 0\\n Presente           1\\nSíntomas durante la temporada de polenAusente 0\\n Presente           1\\nCombinación de uno o más síntomas nasales más prurito ocularAusente 0\\n Presente           2\\n \\nParámetros persistentesHallazgoPuntaje\\nAntígenos disparadores Polen, ácaros de polvo caseros, polvo2\\n Animales (perros y gatos) 1\\n                                                                                                     Otros0\\nPercepción de status alérgico Presente2\\n                                                                                                     Ausente0\\nPruebas de alergia positivas previas Presente2\\n                                                                                                     Ausente0\\nDiagnóstico médico de alergia previo Presente1\\n                                                                                                     Ausente0\\nHistoria familiar de alergia Presente2\\n                                                                                                     Ausente0\\nSFAR=suma (puntaje de todos los parámetros) \\nInterpretación: Puntaje mínimo:0 Puntaje máximo:16 \\nEntre más alto puntaje, más probabilidades de rinitis alérgica \\nUn puntaje > 7 se utiliza para diagnóstico de rinitis alérgica, basado en la curva ROC y en el índice Youden. \\nAdoptado  de:  Annesi-Maesano  I,  Didier  A,  et  al.  The  score  of  allergic  rhinitis  (SFAR):  a  simple  and  valid  \\nassessment method in population studies. Allergy. 2002; 57: 107-114. (Appendix, page 114)."}'::jsonb, false, 4510, '2026-11-26 05:21:22.109+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '042-08'), 'GER', '{"alarmas": "Datos de alarma que requieren referencia a segundo nivel: sangrado rectal, dolor abdominal nocturno o progresivo, pérdida de peso inexplicable, anemia no justificada, fiebre inexplicable, aparición de síntomas después de los 50 años, antecedentes familiares de cáncer colorrectal, enfermedad inflamatoria intestinal o enfermedad celiaca, presencia de masa abdominal, síntomas persistentes de ansiedad o depresión no controlados con antidepresivos, uso reciente de antibióticos sin mejoría.", "prevencion": "Se recomienda identificar y evitar desencadenantes alimentarios mediante registro diario: retiro progresivo de alimentos ricos en FODMAPs (fermentables oligo-, di-, monosacáridos y polioles), café, alcohol, grasas, condimentos picantes y alimentos con sorbitol. Promover comidas regulares sin ayunos prolongados y consumo adecuado de líquidos lugar de ingesta de líquidos sólo al final de comida. Incrementar fibra soluble (psyllium) lentamente para mejorar tránsito intestinal. Considerar terapia psicológica (terapia cognitivo-conductual, hipnoterapia) para pacientes con comorbilidades psicosomáticas. Educar al paciente sobre naturaleza crónica pero no mortal del SII y autocontrol de síntomas.", "diagnostico": "El diagnóstico se basa en criterios de Roma III: dolor o molestia abdominal recurrente al menos 3 días al mes en los últimos 3 meses, con inicio de síntomas al menos 6 meses antes y al menos dos de estos: mejora con la defecación, cambio en la frecuencia o forma de las deposiciones. Se clasifica en SII con predominio de constipación, diarrea o mixto. Se recomienda historia clínica detallada y evaluación de síntomas gastrointestinales y extraintestinales. No se indican estudios rutinarios sin datos de alarma. En presencia de datos de alarma (sangrado rectal, pérdida de peso, anemia, síntomas nocturnos, fiebre inexplicable, aparición en mayores de 50 años, antecedentes familiares de cáncer colorrectal, enfermedad inflamatoria intestinal o celiaca) se debe referir a segundo nivel para estudios como colonoscopia y marcadores inflamatorios fecales (lactoferrina, calprotectina). Ante sospecha de intolerancia a lactosa, se puede usar prueba de aliento. No se recomienda colonoscopia de rutina sin datos de alarma.", "seguimiento": "Se recomienda usar el Cuestionario de Gravedad del Síndrome de Intestino Irritable (IBS-SSS) para evaluar la respuesta al tratamiento y clasificar la severidad (sin enfermedad/remisión <75, leve 75-175, moderada 175-300, grave >300). Reevaluar la eficacia del tratamiento farmacológico y no farmacológico a las 4-6 semanas. Continuar o modificar tratamiento según respuesta. Pacientes estabilizados pueden ser manejados en primer nivel con seguimiento periódico. Referir a psiquiatría si síntomas psiquiátricos persisten y no responden al manejo.", "tratamiento": "Tratamiento inicial con antiespasmódicos: bromuro de pinaverio 100 mg cada 8-12 horas, butilhioscina 10 mg cada 6-8 horas según necesidad. En SII con diarrea se puede agregar loperamida 4 mg inicial + 2 mg después de cada evacuación (máximo 16 mg/día) para disminuir frecuencia, no el dolor. En SII con constipación se recomienda psyllium plantago con dosis iniciando bajas y aumento gradual. Laxantes osmóticos como polietilenglicol 20 g al día en 200 ml de agua pueden ser considerados si no hay respuesta. Antidepresivos tricíclicos (amitriptilina 10-25 mg/día) para SII con predominio de diarrea y en dosis bajas para alivio visceral; inhibidores selectivos de recaptura de serotonina (paroxetina 10-50 mg/día o citalopram 20-40 mg/día) para SII con constipación o mixto. Se inicia con dosis baja y se ajusta según tolerancia y respuesta, con reevaluación a 3-4 semanas. En casos con síntomas persistentes, antibióticos no absorbibles como rifaximina 400 mg cada 8 horas por 10-14 días o neomicina 1 g/día por 10-14 días pueden ser usados. Tratamiento farmacológico será complementado o puede ser acompañado por tratamiento no farmacológico."}'::jsonb, false, 33762, '2026-11-26 05:32:14.156+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '042-08'), 'GRR', E'{"alarmas": "Sangrado rectal, dolor abdominal nocturno o progresivo, pérdida de peso inexplicada, fiebre sin causa, anemia inexplicada, elevación de marcadores inflamatorios, aparición de síntomas después de 50 años, antecedentes familiares de cáncer colorrectal, enfermedad inflamatoria intestinal, o enfermedad celíaca, persistencia de síntomas después de 3 meses de tratamiento farmacológico, síntomas psiquiátricos persistentes sin respuesta a antidepresivos.", "prevencion": "Recomendar dieta baja en FODMAPs, evitar alimentos irritantes como café, alcohol, grasas, condimentos picantes y alimentos con sorbitol; ingerir comidas regulares sin ayunos prolongados; beber líquidos al final de las comidas; disminuir consumo de bebidas gaseosas y cafeinadas; incrementar ingesta gradual de fibra soluble; informar sobre relación entre estrés, ansiedad y síntomas para promover manejo del estrés y apoyo psicológico cuando sea necesario.", "diagnostico": "Criterios de Roma III: Inicio de síntomas al menos 6 meses antes; dolor o molestia abdominal recurrente más de 3 días por mes en últimos 3 meses; al menos dos de: mejora con defecación, alteración en frecuencia o forma de las heces. Evaluar datos de alarma (sangrado rectal, dolor nocturno, pérdida de peso, fiebre, anemia, alteraciones inflamatorias, síntomas nuevos tras 50 años, antecedentes familiares). Estudios recomendados solo en presencia de datos de alarma, incluyendo colonoscopía para descartar enfermedad orgánica.", "seguimiento": "Evaluar respuesta al tratamiento en 4-6 semanas; usar Cuestionario de Gravedad del SII para clasificar la severidad y ajustar tratamiento según resultados. Seguimiento para controlar recaídas y síntomas persistentes, referir a segundo nivel si no hay mejoría tras tratamiento farmacológico combinado o ante datos de alarma. Reevaluar trastornos mentales con escala de ansiedad de Hamilton y derivar a psiquiatría si no hay respuesta a tratamiento.", "tratamiento": "Tratamiento no farmacológico: Dieta baja en FODMAPs, evitar café, alcohol, grasas, picantes y alimentos con sorbitol; incremento gradual de fibra psyllium plantago iniciando con dosis baja hasta tolerancia. Tratamiento farmacológico inicial: bromuro de pinaverio 100 mg cada 8 a 12 horas o bromuro de butilhioscina 10 mg cada 8 horas, plus dimeticona si hay distensión. Para SII-D: loperamida según necesidad; para SII-C: psyllium plantago. Si no responde en 4-6 semanas, añadir antidepresivos: ISRS para SII-C o mixto, tricíclicos para SII-D, iniciar con dosis bajas y ajustar en 3-4 semanas. Si persiste sin control, usar antibióticos no absorbibles como rifaximina o neomicina por 10-14 días en SII-D o mixto. En SII-C considerar uso de laxantes como polietilenglicol.", "texto_completo": "GUÍA DE PRÁCTICA CLÍNICA GPC\\n  \\nDiagnóstico y tratamiento del \\nINTESTINO IRRITABLE\\nen el Adulto\\nGuía de Referencia Rápida\\nCatálogo Maestro de Guías de Práctica Clínica: IMSS-042-08\\nActualización \\n2015 \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n2 \\n \\nÍndice \\n \\n \\n1. Clasificación ............................................................................................................................ 3 \\n2. Definición y Contexto ............................................................................................................ 4 \\n3. Historia Natural del Intestino Irritable ............................................................................... 5 \\n4. Escalas de Clasificación Clínica ............................................................................................. 9 \\n5. Diagramas de Flujo .............................................................................................................. 14 \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n3 \\n \\n1. Clasificación \\n \\nCIE- 10: K58 SÍNDROME DE COLON IRRITABLE  \\nGPC: DIAGNÓSTICO Y TRATAMIENTO DEL INTESTINO \\nIRRITABLE EN EL ADULTO \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n4 \\n \\n2. Definición y Contexto \\n \\nEl  síndrome  del  intestino  irritable  (SII)  se  define  como  una  afectación  crónica  de  dolor  o  molestia  \\nabdominal asociado a alteraciones en el hábito intestinal, durante al menos 3 días por mes en los \\núltimos 3 meses, sin causa orgánica que lo justifique. Se desconoce su etiología y se cree que es de \\ncausa multifactorial en la que pueden coexistir distintos factores. Se identifican distintos subtipos, \\nya sea predominantemente diarrea (SII-D), constipación (SII-C) o mixto (SII-M), afecta seriamente \\nla calidad de vida de quien lo padece. Se estima una prevalencia en población general que va de 10 \\na 20%. \\n \\nEs  el  trastorno  funcional  gastrointestinal  más  común, se presenta en todos los grupos de edad \\nincluyendo  niños  y  ancianos,  aunque  se  presenta  frecuentemente  a  la  edad  de  30  a  50  años.  \\nAfecta  tanto  a  hombres  como  a  mujeres,  no  obstante,  aproximadamente  el  60-75%  de  los  \\nafectados  son  mujeres  y  se  presenta  con  mayor  frecuencia  en  un  nivel  socioeconómico  bajo.  Se  \\nasocia  a  depresión,  ansiedad,  trastorno  somatomorfo  e  ideación  suicida,  además  a  un  menor  \\ndesempeño  laboral,  teniendo  un  impacto  económico  negativo  en  el  individuo,  la  sociedad  y  el  \\nSistema de Salud.  \\n \\n  \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n5 \\n \\n3. Historia Natural del Intestino Irritable \\n \\nCLASIFICACIÓN \\n \\nDe acuerdo al patrón en los hábitos defecatorios, el síndrome de intestino irritable (SII) se clasifica \\nen tres subtipos:  \\n-  SII  con  constipación.  Heces  duras  más  del  25%  de  las  veces  y  deposiciones  disminuidas  de  \\nconsistencia menos de 25% de las veces). \\n-  SII  con  diarrea.  Deposiciones  disminuidas  de  consistencia  más  del    25%  de  las  veces  y  heces  \\nduras menos del 25% de las veces. \\n- SII mixto. Heces duras más del 25% de las veces y deposiciones disminuidas de consistencia más \\ndel 25% de las veces). \\n \\nCUADRO CLÍNICO \\n \\nLos síntomas clínicos de forma individual son imprecisos para establecer el diagnóstico de SII, por \\nlo que esta patología debe ser considerada como un conjunto sindromático. La asociación de dolor \\nabdominal  crónico  y  los  hábitos  intestinales  alterados  son  las  características  principales  no  \\nespecíficas  del  SII,  aunque  existe  una  amplia  variedad  de  síntomas  incluyendo  manifestaciones  \\ngastrointestinales y extraintestinales. \\n \\nLos síntomas  gastrointestinales  son: dolor  abdominal  crónico,  hábitos  intestinales  alterados  \\n(diarrea   o   constipación   o   alternancia   de   estos),   reflujo   gastroesofágico,   disfagia,   saciedad   \\ntemprana,  dispepsia  intermitente,  nauseas,  dolor  precordial  de  origen    no  cardiaco,  flatulencia  y  \\neructos. \\nLos síntomas   extraintestinales   son: depresión   mayor,   ansiedad,   desorden   somatomorfo,   \\ninsomnio,  disfunción    sexual  y  dispareunia,  dismenorrea,  incremento  en  la  frecuencia  urinaria,  \\nurgencia urinaria, síntomas de asma y cefalea primaria. \\n \\nPara  el  diagnóstico  de  SII  debe  basarse  en  la  identificación  de  los  síntomas  positivos  compatibles  \\ncon esta condición y que se resumen en los Criterios de Roma II: \\n Inicio de los síntomas por lo menos 6 meses antes del diagnóstico.  \\n Dolor o molestia abdominal recurrente más de 3 días por mes en los últimos 3 meses.  \\n Por lo menos dos de los siguientes:  \\no Mejora con la defecación. \\no Se acompaña de alteraciones de la frecuencia de las deposiciones.  \\no Se acompaña de variación de la forma de las deposiciones. \\n \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n6 \\n \\nSe debe de evaluar los “datos de alarma”  o “síntomas atípicos”  que no sean compatibles con \\nSII,  debido  a  que  pueden  representar  afectación  orgánica,  estos  incluyen:  sangrado  rectal,  dolor  \\nabdominal  nocturno  o  progresivo,  pérdida  de  peso,  anormalidades  bioquímicas  como  anemia,  \\nelevación  en  marcadores  de  inflamación  o  alteraciones  electrolíticas,  fiebre  sin  causa  explicable,  \\naparición  de  síntomas  después  de  los  50  años,  tumor  abdominal  o  rectal  y  en  aquellos  con  \\nantecedentes  familiares  de  cáncer  de  colon,  enfermedad  celiaca  o  enfermedad  inflamatoria  \\nintestinal. \\n \\nDIAGNÓSTICO DIFERENCIAL \\n \\nLos diagnósticos diferenciales del síndrome de intestino irritable incluyen: enfermedad inflamatoria \\nintestinal,   cáncer   colorectal,   infecciones   intestinales   (parasitosis,   bacterias,   tuberculosis),   \\nalteraciones  hormonales  sistémicas,  intolerancia  a  alimentos,  enfermedad  celiaca,  enfermedad  \\ntiroidea,  sobrecrecimiento  bacteriano  intestinal,  malabsorción  de  ácidos  biliares,  neuropatía  o  \\nmiopatía entérica, efectos secundarios de medicamentos, entre otros. \\n \\nNo se recomienda realizar exámenes de rutina en pacientes con síntomas típicos de SII sin datos \\nde  alarma,  ya  que  está  demostrado  que  no  se  logran  identificar  otras  causas  orgánicas  en  \\ncomparación con la población general. Sin embargo, en presencia de datos de alarma se justifica la \\nrealización de estudios paraclínicos para descartar otras patologías, incluyendo colonoscopia.  \\n \\nTRATAMIENTO NO FARMACOLÓGICO \\n \\nEn el tratamiento no farmacológico la dieta es igual de importante que los fármacos en el manejo \\nde este síndrome. Los alimentos ricos en hidratos de carbono, altos en grasa, café, alcohol, ricos en \\nhistamina, picantes y condimentos son reportados frecuentemente como causantes de síntomas.  \\n \\nEn el tratamiento nutricional de SII incluye diversas estrategias que han mostrado su utilidad, tales \\ncomo:  Alimentos  bajos  en  hidratos  de  carbono  de  cadena  corta  (FODMAPs: Fermentable, \\nOligosacaridos, Disacaridos, Monosacaridos, And Polioles),  Fibra,  restricción  de  alimentos  (café,  \\nalcohol y grasa) y probióticos. \\n \\nLos FODMAPs son  un  grupo  de  hidratos  de  carbono  de  cadena  corta  que  tiene  3  características  \\nen común: Baja absorción  en el intestino delgado, son rápidamente fermentados por las bacterias \\ncolónicas e incrementan el paso deliberado de agua dentro del intestino, debido a su alta actividad \\nosmótica.  (Ver cuadro  1).  La  dieta  baja  en  hidratos  de  carbono  de  cadena  corta  (FODMAPs)  \\nmejora  los  síntomas  del  SII,  incluyendo  distensión,  flatulencia,  alteración  en  la  motilidad  y  dolor  \\nabdominal    en  comparación  con  la  dieta  estándar.  (Ver  cuadro 2).  En  cambio,  la  dieta  con  alto  \\ncontenido de FODMAP empeora los síntomas y se recomienda evitarlos (Ver Cuadro 3). \\n \\nSe recomienda el uso de fibra psyllium plantago, debido a que proporciona  alivio de los síntomas \\nen SII, en especial en la distensión y dolor abdominal. Se debe comenzar con una dosis baja que se  \\nirá incrementando lentamente, hasta la tolerancia (exceso de gases) y regularización del tránsito \\nintestinal. \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n7 \\n \\n \\nSe recomienda proporcionar las siguientes medidas de dietoterapia en pacientes con SII: hacer las \\ncomidas  regulares,  evitando  tiempos  largos  de  ayuno,  ingerir  agua  solo  al  final  de  los  alimentos,  \\nrealizar  la  ingesta  lentamente,  evitar  bebidas  que  contengan  cafeína  (refrescos  de  cola,  café,  té  \\nnegro,  etc.),  evitar  la  ingesta  de  alcohol  y  bebidas  gaseosas,  reducir  la  ingesta  de \\"almidón \\nresistente\\" que  a  menudo se  encuentra en  los  alimentos  procesados, revisar  las  etiquetas  \\nnutrimentales y evitar los alimentos que contengan sorbitol (goma de mascar y algunos productos \\nbajos en calorías), ya que pueden incrementar la diarrea, por aumento en la osmolaridad intestinal. \\n \\nTRATAMIENTO \\n \\nLos  grupos  farmacológicos  más  utilizados  en  el  control  del  síndrome  de  intestino  irritable  son:  \\nAntiespasmódicos,      antidiarreicos,      laxantes,      antidepresivos,      antibióticos      y      agentes      \\nserotoninérgicos. \\n \\nLos  medicamentos  antiespasmódicos  pueden  ser  utilizados  como  tratamiento  inicial  en  el  \\ncontrol de los  síntomas en SII, además pueden ser acompañado de loperamida o psyllium plantago \\ndependiendo de los síntomas predominantes (diarrea o constipación). Se recomienda el uso de los \\nsiguientes  antiespasmódicos  para  el  control  del  dolor  en  pacientes  con  SII  por  periodos  cortos.  \\nBromuro de pinaverio 100 mg cada 8 o 12 horas o bromuro de butilhioscina 10mg cada 8 horas. \\nSe pueden combinar con dimeticona para disminuir gas y mejorar la distensión abdominal. \\n \\nUno  de  cada  dos  pacientes  con  SII  reportan  trastornos  psicosomáticos  o  mentales  tales  como  \\ndepresión,  ansiedad,  insomnio,  ataques  de  pánico,  desórdenes  temporo-mandibulares,  fatiga  \\ncrónica entro otros, por lo que recomienda evaluar estas patologías y utilizar antidepresivos como \\nsegunda  opción  de  tratamiento  en  el  SII  una  vez  que  los  antiespasmódicos  en  conjunto  con  \\nantidiarreico y/o psyllium no han controlado los síntomas. \\n \\nLos antidepresivos  (tricíclico  e  inhibidores  selectivos  de  recaptura  de  serotonina)  son  efectivos  \\nen  mejorar  los  síntomas  globales  y  reducir  el  dolor  en  SII,  aunque  limitados  a  la  tolerancia  del  \\npaciente  por  sus    efectos  secundarios.  Se  deben  iniciar  con  dosis  menores  a  las  usadas  en  \\ndepresión  y  ajustarse  en  3  o  4  semanas  según  la  respuesta.  En  caso  de  SII  con  predominio  de  \\nconstipación o mixto, se recomienda utilizar un antidepresivo inhibidores selectivo de recaptura de \\nserotonina, en caso de predominio de diarrea se prefiere los tricíclicos. \\n \\nDebido  a  la  frecuencia  tan  alta  de  la  asociación  de  trastornos  psicosomáticos  y  mentales  con  \\nsíntomas  de  SII  se  deben  investigar  estos  problemas  desde  la  primera  consulta  y  para  ellos  se  \\nsugiere aplicar la escala de valoración de ansiedad de Hamilton (Ver Cuadro 4). \\n \\nEl uso de antibióticos ha demostrado mejoría de los síntomas en pacientes con SII y pueden ser \\nutilizados  en  aquellos  pacientes  que  persisten  con  síntomas  principalmente  diarrea  y  no  tengan  \\ncontrol  adecuado  con  antiespasmódicos,  antidiarreicos  y  antidepresivos.  Se  recomienda  el  uso  \\nantibióticos  no  absorbibles  debido  a  que  los  efectos  secundarios  son  menores  que  los  sistémicos  \\npor ejemplo rifaximina o neomicina por 10 a 14 dias. \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n8 \\n \\nSEGUIMIENTO Y PRONÓSTICO \\n \\nSe recomienda utilizar el Cuestionario de Gravedad de Síndrome de Intestino Irritable es útil para \\nclasificar  a  los  pacientes  con  SII  en  función  de  su  gravedad  y  para  valorar  su  respuesta  al  \\ntratamiento y determinar la continuidad o modificación del mismo. (Ver Cuadro 5). \\n \\nEn una revisión sistemática de 14 estudios, en pacientes con SII,  reportó que: \\n De  2-5%  fueron  diagnosticados  con  patología  gastrointestinal  orgánica  como  causa  de  los  \\nsíntomas (seguimiento: 6 meses-6 años).  \\n Todos  los  estudios  reportaron  persistencia  de  síntomas  al  final  del  seguimiento  (seguimiento:  \\n6 meses-15 años).  \\n En 5 estudios se reportó ausencia de síntomas solo en 12-38% (seguimiento: 2 años). \\n En  4  estudios  se  reportó  que  permanecen  sin  cambios  de  síntomas  un  30  a  50%  de  los  \\npacientes y hay empeoramiento de los mismos en 2-18%. (seguimiento 12 meses-7 años). \\n Ningún estudio concluyó con detalle acerca de la frecuencia y duración de las recaídas.      \\n \\n \\nCIRTERIOS DE REFERENCIA Y CONTRARREFERENCIA \\n \\nSe  deberá  referir  a  segundo  nivel  de  atención  a  aquellos  pacientes  que  no  obtengan  respuesta  \\nfavorable   al   tratamiento   inicial   (antiespasmódico   y   sintomático)   asociado   al   tratamiento   \\nantidepresivo  posterior  a  3  meses  de  manejo  y  a  aquellos  que  presenten  dolor  abdominal,  \\ndistensión   y   alguno   de   los   siguientes   datos   de   alarma   para   complementación   diagnóstico   \\nterapéutica: \\n Anemia sin causa aparente. \\n Sangrado de tubo digestivo bajo. \\n Síntomas nocturnos o progresivos. \\n Pérdida de peso inexplicable. \\n Uso reciente de antibióticos. \\n Aparición de síntomas en mayores de 50 años.  \\n Enfermedad inflamatoria del intestino. \\n Enfermedad celiaca. \\n Antecedentes familiares de cáncer colorrectal u ovario. \\n \\nSe   deberá   referir   al   servicio   de   psiquiatría   a   aquellos   pacientes   que   presenten   síntomas   \\npersistentes de ansiedad o depresión y no respondan al manejo establecido con antidepresivos. \\n \\nSe  deberá  contrarreferir  a  primer  nivel  de  atención  a  aquellos  pacientes  con  diagnóstico  y  \\ntratamiento de síndrome de intestino irritable establecido para llevar seguimiento en este nivel. \\n \\n  \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n9 \\n \\n4. Escalas de Clasificación Clínica \\n \\nCUADRO 1. BASE FISIOPATOLÓGICA PARA  LA PRESENTACIÓN DE SÍNTOMAS DEL \\nSÍNDROME DE INTESTINO IRRITABLE POR FODMAP   (OLIGOSACÁRIDOS, DISACÁRIDOS, \\nMONOSACÁRIDOS Y  POLIOLES FERMENTABLES). \\n      *GOS: Galacto-oligo-sacaridos \\n \\nLa  comida  es  un  desencadenante  común  para  los  síntomas  de  intestino  irritable  por  múltiples  vías  que  se  \\nrelacionan con los mecanismos inmunológicos y no inmunológicos. \\n    \\nLos alimentos que son FODMAPs tienen tres propiedades comunes que pueden ser  provocadoras:   \\n1) Son pobremente absorbidos en el intestino delgado.  \\n2)  Contienen  moléculas  pequeñas  y  osmóticamente  activas  que  rápidamente  atraen  líquidos  a  la  luz  \\nintestinal. \\n3)  Son  fermentados  rápidamente  por  las  bacterias    a  una  gran  cantidad  de  gases  que  causan  distensión  \\nabdominal.  \\nEl  resultado  final    de  la  intolerancia  a  alimentos  ricos  en  FODMAP  es  el  exceso  de  gases,  dolor  abdominal,  \\ndistensión y diarrea. \\n \\n \\nTomado  de:  Mullin  GE,  Shepherd  SJ,  Chander  Roland  B,  Ireton-Jones  C,  Matarese  LE.  Irritable  bowel  \\nsyndrome:   contemporary   nutrition   management   strategies.   JPEN   J   Parenter   Enteral   Nutr.   2014   \\nSep;38(7):781-99. \\n \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n10 \\n \\nCUADRO 2. EJEMPLOS DE ALIMENTOS RECOMENDADOS \\nEN EL SÍNDROME DE INTESTINO IRRITABLE CON \\nBAJO Y MODERADO CONTENIDO  EN FODMAPS*, ORGANIZADOS POR GRUPOS DE ALIMENTOS \\n \\nEJEMPLOS DE ALIMENTOS DE BAJO \\nY MODERADO CONTENIDO EN FODMAPs \\n \\nFrutas \\nVegetales \\nLeche y productos \\nderivados \\nGranos y cereales \\nFrutos secos,  \\ny semillas \\nOtros \\nArándanos \\nAceitunas \\nCrema \\nArroz\\nAlmendras\\nAceite de oliva\\nCarambola \\nAlfalfa \\nHelados sin lactosa\\nAvena\\nAvellanas\\nCaramelo\\nCerezas \\nAguacate \\nMantequilla\\nCereales y pan sin gluten \\nLinaza\\nConcentrado de ajo\\nFrambuesa \\nApio \\nMargarina \\nGalletas\\nSemillas de girasol \\nJarabe de maple\\nFresa \\nBerenjena \\nLeche de arroz\\nMaíz\\nSemillas de calabaza\\nJengibre\\nKiwi \\nBrócoli \\nLeche de avena\\nMijo\\nSemillas de chía\\nAlbahacar\\nGranada \\nBulbo de hinojo \\nYogurt y yogurt sin lactosa\\n*Todos los productos deben estar hechos a base de granos y harina sin gluten.\\n \\nSemillas de sésamo\\nTomillo \\nMelón dulce \\nCalabaza \\nQueso frescos: panela\\n \\nOrégano \\nLimón \\nCalabacita \\nQuesos blandos ejemplo: cottage, requesón, queso crema \\nEpazote \\nLima \\nCebollita \\n*Es obligatorio identificar el gluten libre en los productos.\\n \\nHierba buena\\nLichi \\nCol de brucelas \\nQuesos maduros ejemplo: Brie, cheddar, colby, gouda la vena azul, Edam, feta, mozzarella, parmesano \\nHierba stevia\\nMandarina \\nEjotes \\nEdulcorantes artificiales Sucralosa, Aspartame\\n \\nMaracuyá \\nEspinacas \\n \\nNaranja \\nGermen de soya \\nPapaya \\nLechuga \\n \\n \\nPlátano \\nPapa \\nPiña \\nPimienta \\nUvas \\nPepino \\n \\nTomate Nabo Nopal Remolacha Rábano Zanahoria \\n*FODMAPs,  = Fermentables:  oligo-, \\ndi-, y monosacaridos y  polioles.\\n \\n Modificado de: Mullin GE, Shepherd\\n SJ, Chander Roland B, Ireton-Jones C, Matare\\nse LE. Irritable bowel \\nsyndrome: contemporary \\nnutrition management strategies. JPEN J Pa\\nrenter Enteral Nutr. 2014 Sep;38(7):781-9\\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n11 \\n \\nCUADRO 3. EJEMPLOS DE ALIMENTOS POCO RECOMENDA\\nDOS EN EL SÍNDROME DE INTESTINO IRRITABLE \\nCON ALTO CONTENIDO  EN FODMAPS*, ORGANIZADOS POR GRUPOS DE ALIMENTOS \\n \\nEJEMPLOS DE ALIMENTOS DE ALTO CONTENIDO EN FODMAPs \\n \\nFrutas \\nVegetales \\nLeche y productos \\nderivados \\nGranos y \\ncereales \\nFrutos secos,  \\ny semillas \\nOtros \\nGuanabana y chirimoya \\nAjo \\nHelado\\nCebada\\nGarbanzos\\nAgave\\nDuraznos y nectarinas\\n \\nAlcachofa\\n \\nLeche de cabra, oveja y vaca\\nCereal\\nLeguminosas\\nFructosa\\nManzana\\n \\nCebolla \\nLeche de oveja \\nCroissants\\nFrijoles, cualquier clase\\nFructo-oligosacáridos\\nMelón y melón blanco\\n \\nChayote\\n \\nLeche de vaca\\nGalletas\\nFrijoles de soya\\nConcentrados de jugos de frutas\\nMango \\nChícharo \\nLeche condensada\\nFideo\\nLentejas \\nJarabe de maíz de alta fructosa\\nMoras\\n \\nColiflor\\n \\nLeche evaporada\\nPan\\nPistaches\\nInulina\\nPasas\\n \\nEspárragos\\n \\nLeche de polvo\\nPastas\\n \\nMaltosa \\nPeras \\nHongos\\n \\nNatillas\\nMuffins\\nManitol \\nSandía \\nSetas\\n \\nPostres hechos con leche\\n \\nMiel \\nTamarindo \\n \\n \\n \\nTejocotes *FODMAPs,  = Fermentables: oligo-, \\ndi-, y monosacaridos y  polioles.\\n \\n Modificado  de:  Mullin  GE,  Shepherd  SJ,  Chande\\nr  Roland  B,  Ireton-Jones  C,  Matarese  LE\\n.  Irritable  bowel  syndrome:  contemporary  nu\\ntrition \\nmanagement strategies. JPEN J Parenter Enteral Nutr. 2014 Sep;38(7):781-99. \\n \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n12 \\n \\nCUADRO 4. ESCALA DE VALORACIÓN DE ANSIEDAD DE HAMILTON  \\n \\nEl entrevistador puntúa de 0 a 4 puntos cada reactivo, evaluando tanto la intensidad como la frecuencia del \\nmismo. Se pueden obtener, además, dos puntuaciones que corresponden a ansiedad psíquica (ítems 1, 2, \\n3,  4,  5,  6  y  14)  y  a  ansiedad  somática  (ítems  7,  8,  9,  10,  11,  12  y  13).  Es  aconsejable  distinguir  entre  \\nambos a la hora de valorar los resultados de la misma. No existen puntos de corte. Una mayor puntuación \\nindica  una  mayor  intensidad  de  la  ansiedad.  Es  sensible  a  las  variaciones  a  través  del  tiempo  o  tras  recibir  \\ntratamiento   \\n \\nIndique  la  intensidad  con  que  se  cumplieron  o  no,  durante  el  último  mes,  los  síntomas  que  se  describen  en  \\ncada uno de los 14 ítems: \\n0. Ausente 1. Intensidad ligera. 2. Intensidad media. 3. Intensidad elevada. 4. Intensidad máxima \\n(invalidante). \\n \\n \\nESCALA DE ANSIEDAD DE HAMILTON\\n01234\\n1 Estado de ánimo ansioso: Preocupaciones, anticipación a lo peor, aprensión, irritabilidad. \\n2 Tensión:  Sensación  de  tensión,  Fatigabilidad,  imposibilidad  de  relajarse,  reacciones  de  sobresalto,  \\nllanto fácil, temblores, sensación de inquietud. \\n3 Temores:  A  la  oscuridad,  a  los  desconocidos,  a  quedarse  solo,  a  los  animales,  al  tráfico,  a  las  \\nmultitudes. \\n4 Insomnio: Dificultad para conciliar el sueño, sueño interrumpido, sueño insatisfactorio y cansancio al \\ndespertar. Terrores nocturnos. \\n5 Funciones Intelectuales (Cognitivas): Dificultad para concentración, mala memoria. \\n6 Estado  de  ánimo  depresivo:  Pérdida  de  interés,  insatisfacción  de  las  diversiones,  depresión.  \\nDespertar prematuro, cambios del estado de ánimo durante el día. \\n7 Síntomas    somáticos    musculares:    Dolores    y    molestias    musculares,    rigidez    muscular,    \\ncontracciones musculares, sacudidas clónicas, rechinar de dientes, voz temblorosa. \\n8 Síntomas  somáticos  sensoriales:  Zumbido  de  oídos,  visión  borrosa,  sofocos  y  escalosfríos,  \\nsensación de debilidad, sensaciones parestésicas (hormigueo). \\n9 Síntomas cardiovasculares: Taquicardia, palpitaciones, dolor torácico, sensación pulsátil vascular, \\nsensaciones de \\"baja presión\\" o desmayo. Extrasístoles. \\n10 Síntomas  respiratorios:  Opresión  o  constricción  en  el  pecho,  sensación  de  ahogo  o  falta  de  aire,  \\nsuspiros y disnea \\n11 Síntomas gastrointestinales: Dificultades para tragar, gases, dispepsia: dolor antes o después de \\ncomer,  sensación  de  ardor,  distensión  abdominal,  nauseas,  vómitos,  sensación  de  estómago  vacío,  \\ndigestión lenta, borborigmos, (ruido intestinal), diarrea, pérdida de peso, estreñimiento. \\n12 Síntomas  genitourinarios:  Micción  frecuente,  micción  urgente,  amenorrea,  menorragia,  aparición  \\nde frigidez, eyaculación precoz, impotencia, ausencia de erección. \\n13 Síntomas del sistema nervioso autónomo: Boca seca, rubor, palidez, tendencia a sudar, vértigos, \\ncefalea tensional, piloerección. \\n14 Comportamiento  en  la  entrevista  (general):  Tenso,  no  relajado,  agitación  nerviosa:  manos  y  \\ndedos cogidos, apretados, tics, enrollar un pañuelo. Inquietud: pasearse de un lado a otro, temblor de \\nmanos,  ceño  fruncido,  rostro  preocupado,  aumento  del  tono  muscular,  suspiros,  palidez  facial.  \\nComportamiento fisiológico: tragar saliva, eructar, taquicardia de reposo (palpitaciones), frecuencia \\nrespiratoria  mayor  de  20  por  minuto,  sacudidas  enérgicas  de  tendones,  temblor,  pupilas  dilatadas,  \\nsudor, tics en párpados. \\n PUNTUACIÓN TOTAL\\n__________\\n Si su puntaje es igual o mayor a 18 es aconsejable que se realice una evaluación más profunda ya \\nque puede estar padeciendo Trastorno de Ansiedad. \\n \\nAdaptado de: Lobo A, Camorro L, Luque A, Dal-Ré R, Badia X, Baró E. Validación de las versiones en español de la \\nMontgomery-Asberg Depression Rating Scale y la Hamilton Anxiety Rating Scale para la evaluación de la depresión y de \\nla ansiedad. Med Clin (Barc) 2002;118:493-99\\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n13 \\n \\nCUADRO 5. CUESTIONARIO DE GRAVEDAD DEL SÍNDROME DE INTESTINO IRRITABLE. \\n \\ninterpretación \\nCada una de las 5 preguntas se puntúa de 0 a 100 (según el valor en la escala visual marcado 25 puntos o el \\nnúmero de días multiplicado por 10, según corresponda a la pregunta) conformándose una puntuación total \\ncon la suma de ellas, que va desde un mínimo de 0 hasta un máximo de 500.\\nDe acuerdo a la puntuación total se clasifican:\\n < 75 indica sujetos sin enfermedad o en remisión.\\n 75-175 enfermedad leve. \\n 175-300 enfermedad moderada. \\n Más de 300 enfermedad grave. \\n \\nTomado de: Almansa C, García-Sánchez R, Barceló M, Díaz-Rubio M, Rey E. Traducción, adaptación cultural y validación \\nal español del cuestionario de gravedad del síndrome de intestino irritable (Irritable Bowel Syndrome Severity Score). Rev \\nEsp Enferm Dig 2011;103: 612-618.  \\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n14 \\n \\n5. Diagramas de Flujo \\nPersona con síntomas sospechosos \\nde síndrome de intestino irritable\\nEnviar a Segundo Nivel \\npara complementación \\ndiagnóstica y descartar \\nenfermedad orgánica \\n¿Presenta datos \\nde Alarma?**\\nNO\\nSI\\n*Criterios de ROMA III\\nIniciar tratamiento de \\nacuerdo al diagnóstico que se \\nestablezca\\nValorar colonoscopia\\nSINTOMAS EXTRAINTESTINALES\\n‐ Ansiedad, tristeza o depr esión.\\n‐ Insomnio o angustia.\\n‐ Somatizaciones.\\n‐ Disfu nción sexual, dispareun ia.\\n‐ Dismen orrea.\\n‐ Urgencia y frecuencia urinaria.\\n‐ Cansancio o agotamiento físico.\\n‐ Síntomas de as m a.\\n‐Cefalea primaria.\\nSINTOMAS INTESTINALES\\n‐ Do lo r ab dom i na l crónico.\\n‐ Distensión abdominal.\\n‐ Háb ito s intestinales al tera do s \\n(diarrea o constipación).\\n‐ Reflujo gastroesofágico.\\n‐ Disfagia o nauseas.\\n‐ Saciedad tempr ana.\\n‐ Dispepsia intermitente.\\n‐ Flatulencia y eructos.\\nALGORITMO 1. DIAGNÓSTICO DEL SINDROME DE INTESTINO IRRITABLE\\n**Datos de Alarma\\n‐ Sangrado rectal (melena o hematoquezia)\\n‐ Dolor abdominal nocturno o progresivo.\\n‐ Pérdida de peso inexplicable.\\n‐ Fiebre si n causa apa re nte.\\n‐ Anemia, elevación en VSG, PCR o      \\naltera cione s el e ct rol ít i cas. \\n‐ Aparición en mayores de 50 años . \\n‐ Antecedentes familiares de cáncer de \\ncolon, ovario o enfermedad celiaca.\\n*Criterios de Roma III:\\nInicio de sí ntomas  6 meses \\nantes. \\nDolor o molestia abdominal más \\nde 3 días po r mes en los últimos \\n3 meses. \\nPor lo me no s dos de los \\nsi gui entes: \\n‐ Mejora co n la defecación.\\n‐ Se acompaña de alteraciones de la \\nfrecue ncia de las deposiciones. \\n‐ Se acompaña de var i aci on es de la \\nforma de la s deposiciones.\\nInterrogar sobre \\nsíntomas intestinales y \\nextraintestinales\\nIniciar tratamiento:\\nNo farmacológico y \\nfarmacológico\\nPasa a Algoritmo 2\\nEstablecer el subtipo \\nde Intestino irritable\\nIntestino irritable con \\npredominio de diarrea\\nIntestino irritable con \\npatrón alternante o mixto\\nIntestino irritable con \\npredominio de constipación\\nEvaluar posibilidad de \\nparasitosis, intolerancia a la \\nlactosa, enfermedad celiaca y \\notras causas de diarrea crónica\\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n15 \\n \\nINICIAR TRATAMIENTO \\nNO\\nFARMACOLÓGICO \\nALGORITMO 2. TRATAMIENTO DEL SINDROME DE INTESTINO IRRITABLE\\nNO FARMACOLÓGICO \\nAlgoritmo \\n1\\nTerapia \\nnutricional\\nTerapia \\ncognitiva \\nconductual\\n‐Retirar alimentos altos en FODMAPs* \\n‐Retirar café, alcohol, irritantes.\\n‐Incremento en la ingesta de líqudos.\\n‐Incrementar fibra\\n*FODMAPs: Alimentos fermentables, oligosacarios, disacaridos, monosacaridos y polioles\\nPRN: Por razón necesaria\\nIntestino irritable \\ncon predominio de \\ndiarrea (\\nSII‐D)\\nIntestino irritable \\ncon patrón mixto o \\nalternante (\\nSII‐M)\\nIntestino irritable \\ncon predominio de \\nconstipación (\\nSII‐C)\\nSI\\nTRATAMIENTO INICIAL\\n‐ Bromuro de Pinaverio\\n‐ Butilhioscina PRN\\n‐ Loperamida PRN\\nTRATAMIENTO INICIAL\\n‐ Bromuro de Pinaverio\\n‐ Butilhioscina PRN\\n‐ Loperamida o psyllium \\nsegún síntomas.\\nAgregar antidepresivos \\n– IRSS para SII‐C o SII‐M\\n ‐Tricíclicos para SII‐D.\\n¿Respuesta\\n favorable en 4 a 6 \\nsemanas?\\nTRATAMIENTO INICIAL\\n‐ Bromuro de Pinaverio\\n‐ Psyllium plantago\\n‐ Butilhioscina PRN\\nContinuar sólo \\ncon tratamiento no \\nfarmacológico \\n¿Respuesta\\n favorable en 4 a 6 \\nsemanas?\\nSI\\nNO\\n‐ Agregar Neomicina (SII‐ M o SII‐D)\\n‐ Considerar polietilenglicol (SII‐C).\\n‐ Considerar cambio de antidepresivo\\nDERIVAR A SEGUNDO \\nNIVEL PARA \\nCOMPLEMENTACIÓN \\nDIAGNÓSTICA \\nVALORAR PRUEBAS \\nDIAGNÓSTICAS PARA \\nENERMEDAD ORGÁNICA\\nContinuar con \\ntratamiento  \\nfarmacológico \\n¿Respuesta\\n favorable de 4 a 6 \\nsemanas?\\nNO\\nSI\\nContinuar  \\ncon tratamiento no \\nfarmacológico mientras \\npersista SII\\n\\nDiagnóstico y Tratamiento del Intestino Irritable en el Adulto \\n \\n16 \\n \\n \\nDurango 289- 1A Colonia Roma \\nDelegación Cuauhtémoc, 06700 México, DF. \\nPágina Web: www.imss.gob.mx \\n \\nPublicado por Instituto Mexicano del Seguro Social \\n© Copyright Instituto Mexicano del Seguro Social “Derechos Reservados”. Ley Federal de Derecho \\nde Autor \\n \\nEditor General \\nCoordinación Técnica de Excelencia Clínica \\nCoordinación de Unidades Médicas de Alta Especialidad"}'::jsonb, false, 9703, '2026-11-26 05:32:50.662+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '046-18'), 'GER', '{"alarmas": "Referir a segundo nivel pacientes con IMC >40 kg/m2 o IMC 35-39.9 kg/m2 con comorbilidad severa no controlada tras tratamiento convencional, signos de complicaciones cardiovasculares graves, hiperglucemia sin control, síntomas de apnea grave, o falta de respuesta al tratamiento farmacológico. Sospecha o diagnóstico de obesidad secundaria a causas endocrinas o neurológicas. Signos de descompensación psicosocial que requieran evaluación especializada.", "prevencion": "Promover alimentación saludable basada en patrones como dieta mediterránea o dieta DASH, evitando dietas muy altas en grasas saturadas o trans. Fomentar actividad física regular, combinando ejercicios aeróbicos y de resistencia, al menos 30 minutos diarios, 5-7 días por semana. Educación y apoyo psicosocial para mejorar adherencia a cambios conductuales. Prevenir ganancia de peso mediante consejo nutricional y vigilancia del peso corporal anual en adultos. Evitar uso de suplementos o terapias no respaldadas científicamente para pérdida de peso.", "diagnostico": "Calcular Índice de Masa Corporal (IMC): sobrepeso IMC 25-29.9 kg/m2, obesidad IMC ≥30 kg/m2. Medir circunferencia de cintura en pacientes con IMC 25-35 kg/m2 (riesgo si >80 cm en mujeres y >90 cm en hombres). No usar IMC en embarazadas ni lactantes. Evaluar comorbilidades y factores de riesgo cardiovascular mediante historia clínica, presión arterial, glucosa, perfil lipídico, apnea del sueño y actividad física habitual.", "seguimiento": "Control clínico y medición de peso, IMC y circunferencia de cintura cada 3-6 meses. Reevaluar adherencia a cambios en el estilo de vida y ajustar intervención si no hay pérdida mínima del 5% de peso corporal a los 3-6 meses. Vigilar y manejar eventos adversos de farmacoterapia. Mantener seguimiento para prevención de comorbilidades y control de factores de riesgo cardiovascular. Reforzar educación y motivación para mantenimiento del peso alcanzado.", "tratamiento": "Intervención inicial basada en cambios en estilo de vida: dieta hipocalórica <1200 kcal/día, aumento de actividad física (30 min/día, 5-7 días/semana), y terapia conductual. Farmacoterapia indicada en IMC ≥30 o IMC 27-29.9 con comorbilidades y pérdida <5% peso a 3-6 meses de intervención inicial. Orlistat 120 mg VO tres veces al día, vigilancia de efectos gastrointestinales. Liraglutide SC desde 0.6 mg/día incrementando semanalmente hasta 3 mg/día, con asesoría sobre náuseas. Lorcaserina 10 mg VO dos veces al día, evaluar respuesta a las 12 semanas. Fentermina/topiramato inicia 3.75 mg/23 mg por 14 días, luego 7.5/46 mg diarios, incrementando hasta 15 mg/92 mg si no hay pérdida ≥3% a las 12 semanas; evitar en enfermedad cardiovascular. No se recomienda naltrexona-bupropión por eventos adversos ni suplementos de calcio para pérdida de peso."}'::jsonb, false, 38814, '2026-11-26 05:27:40.847+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '046-18'), 'GRR', E'{"alarmas": "IMC >40 o IMC 35-39.9 con comorbilidad severa, fracaso a tratamiento médico, pérdida de peso <5% y empeoramiento de comorbilidades, presencia de apnea del sueño no controlada, síntomas graves o trastornos mentales asociados. Requieren referencia a segundo nivel para evaluación y posible cirugía bariátrica o manejo especializado.", "prevencion": "Consejería para mantener peso corporal normal. Promover patrón dietético saludable (dieta mediterránea o DASH). Recomendación de actividad física regular. Evitar medicamentos que causen aumento de peso si es posible. Educación sobre hábitos alimentarios y estilo de vida saludable. Evitar dietas hipocalóricas extremas sin supervisión.", "diagnostico": "Medir peso, talla y calcular IMC para clasificar estado nutricional. Medir circunferencia de cintura en IMC entre 25 y 35 kg/m2. Evaluar comorbilidades asociadas (hipertensión, diabetes, apnea del sueño) y factores etiológicos. No usar IMC en embarazo o lactancia. Estudios recomendados: glucosa sérica, lípidos, triglicéridos, presión arterial y tamizajes de apnea del sueño y trastornos psicológicos si aplica.", "seguimiento": "Medir peso y calcular IMC anualmente en todos los pacientes. Revaluar metas de pérdida de peso periódicamente. En pacientes en tratamiento farmacológico o con comorbilidades, seguimiento cercano para evaluar eficacia y efectos adversos. Reevaluar factores médicos si no hay pérdida de peso significativa y considerar tratamiento combinado o referencia.", "tratamiento": "Cambios en estilo de vida intensivos para IMC >30 o IMC 27-30 con comorbilidad. Orlistat 120 mg vía oral tres veces al día durante al menos 12 semanas; informar sobre efectos gastrointestinales. Liraglutida subcutánea iniciando a 0.6 mg/día, incrementando semanalmente hasta 3 mg/día en obesos con diabetes tipo 2. Lorcaserina 10 mg vía oral dos veces al día, evaluar respuesta a las 12 semanas. Fentermina 3.75 mg/topiramato 23 mg diaria por 14 días, luego 7.5/46 mg; aumentar dosis si no hay pérdida >3% a las 12 semanas. No usar naltrexona/bupropión ni suplementos de calcio para pérdida de peso.", "texto_completo": "GUÍA DE PRÁCTICA CLÍNICA GPC \\n \\n \\n \\n \\n                                                                                                                   \\n \\n \\nDiagnóstico y Tratamiento \\nDEL SOBREPESO Y LA OBESIDAD \\nEXÓGENA \\n \\nGuía de Referencia Rápida \\nCatálogo Maestro de Guías de Práctica Clínica: GPC-IMSS-046-18 \\nActualización \\n2018 \\n\\nDiagnóstico y tratamiento del sobrepeso y obesidad exógena \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nDurango 289- 1A Colonia Roma \\nDelegación Cuauhtémoc, 06700 México, DF. \\nPágina Web: \\nwww.imss.gob.mx \\n \\nPublicado por Instituto Mexicano del Seguro Social \\n© Copyright Instituto Mexicano del Seguro Social “Derechos Reservados”. Ley Federal de Derecho de Autor \\n \\nEditor General \\nCoordinación Técnica de Excelencia Clínica \\nCoordinación de Unidades Médicas de Alta Especialidad \\n \\nLa  guía  de  referencia  rápida  tiene  como  objetivo  proporcionar  al  usuario  las  recomendaciones  clave  de  la  guía  \\nDiagnóstico y Tratamiento del Sobrepeso y Obesidad Exógena, seleccionadas con base a su impacto en salud por \\nel  grupo  desarrollador,  las  cuales  pueden  variar  en  función  de  la  intervención  de  que  se  trate,  así  como  del  contexto \\nregional o local en el ámbito de su aplicación. \\n \\nPara mayor información, se sugiere consultar la guía en su versión extensa de “Evidencias y Recomendaciones” en el \\nCatálogo      Maestro      de      Guías      de      Práctica      Clínica,      la      cual      puede      ser      descargada      de      Internet \\nen: \\nhttp://imss.gob.mx/profesionales-salud/gpc \\n \\nDebe ser citado como: Diagnóstico y Tratamiento del Sobrepeso y Obesidad Exógena. Guía de Referencia Rápida: \\nGuía de Práctica Clínica. México, CENETEC; 2018 [fecha de consulta]. Disponible en: \\nhttp://imss.gob.mx/profesionales-\\nsalud/gpc \\n \\nISBN en trámite \\n \\n\\nDiagnóstico y tratamiento del sobrepeso y obesidad exógena \\n \\n \\n1. Diagramas de Flujo \\nAlgoritmo 1. Clasificación y evaluación inicial del paciente adulto con sobrepeso y obesidad \\n \\n \\n \\n \\n \\nEvaluación inicial y diagnóstico del paciente adulto con sobrepeso y obesidad\\nMedir peso, talla y calcular IMC\\nConsejería para no \\nganar peso, evaluar \\ny tratar otros \\nfactores de riesgo\\nMedir peso y calcular IMC \\nde forma anual\\nEvaluar y tratar \\ncomorbilidades \\nasociadas con la \\nobesidad\\nEvaluar peso y \\nestilo de vida\\nNO\\nSI\\nDeterminar metas de tratamiento, de pérdida de peso y \\nestrategias de intervención \\nIntervención en el estilo de vida sola o con otros \\ntratamientos (IMC >\\n 30 > 27 con comorbilidad)\\nIMC de 18.5 a < 25 ó \\n>\\n 25 kg/m2?\\n18.5 a < 25\\n> 25\\nIMC > 30 ó 25 a < 30 \\ncon >1 comorb?\\nEvaluar si paciente está \\ndispuesto a hacer cambios en \\nestilo de vida para perder peso\\nSI\\nNO\\nIntervención en estlos de \\nvida de alta intensidad\\nCambios en estilo de vida por \\nmedios alternativos (internet, \\nteléfono)\\nIMC > 30 o IMC > 27 con \\ncomorbilidad\\nAñadir farmacoterapia \\nademás de cambios en estilo \\nde vida\\nIMC >\\n 40 o IMC > 35 con \\ncomorbilidad\\nReferencia a cirugía bariátrica \\npara consulta y evaluación \\nademás de cambios en el estilo \\nde vida\\ncontinúa\\n\\nDiagnóstico y tratamiento del sobrepeso y obesidad exógena \\n \\n \\n \\n \\nAlgoritmo 1. Evaluación inicial del paciente adulto con sobrepeso y obesidad (continuación) \\n \\nEvaluación inicial del paciente adulto con sobrepeso y obesidad\\n¿Pérdida de peso >\\n 5%y \\nmejoría en objetivos de \\nsalud?\\nSeguimiento y mantenimiento de la \\npérdida de peso\\nMedir peso y calcular IMC de forma anual\\nSI\\nTratamiento conductual intenso, \\nreevaluar factores médicos, \\nconsidere añadir farmacoterapia, y \\nreferencia a cirugía bariátrica\\nNO\\n¿Pérdida de peso >\\n 5%y \\nmejoría en objetivos de \\nsalud?\\nSI\\nContinuar manejo médico intensivo de \\nlas comorbilidades relacionadas, \\nrevisar opciones para manejo de peso\\nNO\\n...Continua\\nción\\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y tratamiento del sobrepeso y obesidad exógena \\n \\n \\n \\nAlgoritmo 2. Tratamiento de pacientes adultos con obesidad \\n \\nTratamiento de pacientes adultos con Obesidad\\n¿IMC >\\n 25?\\nRefuerzo breve/\\norientación sobre \\ncontrol de peso\\nRecomendaciones \\npara conservar el \\npeso\\nNOSI\\nRevisión periódica \\nIMC > 25 o perímetro \\nabdominal > 88 cm (mujer) \\n> 102 cm hombre\\nNO\\nValorar factores \\nde riesgo\\nSI\\nIMC > 30 o 26 a 29.9 o \\nperímetro abdominal > 88 cm \\nmujer o > 102 hombres y >\\n 2 \\nfactores de riesgo \\n¿El paciente \\ndesea \\naldelgazar?\\nEl médico y el paciente \\nestablecen metas para la \\npérdida de peso y control \\nde factores de riesgo\\n¿Ha progresado y \\nalcanzado metas?\\nValorar por que el \\npaciente no logra \\nbajar de peso\\nSI\\nNO\\nAsesoría en mantener:\\nTratamiento dietético\\nTerapia conductual\\nTratamiento físico\\nSI\\nNO\\nSI\\nNO\\n \\n  \\n\\nDiagnóstico y tratamiento del sobrepeso y obesidad exógena \\n \\n \\n \\n2. Sobrepeso y Obesidad \\n \\nDIAGNÓSTICO \\n \\nRecomendación Clave \\nGR* \\nSe  recomienda  utilizar  el  cálculo  del  Índice  de  Masa  corporal  como  una  estimación  \\npráctica para clasificar a los adultos con bajo peso, sobrepeso u obesidad. \\nD \\nSe  recomienda  medir  además  la  circunferencia  de  cintura  en  aquellos  pacientes  con  \\nun IMC entre 25 y 35 kg/m2 porque la adiposidad abdominal y sus riesgos asociados \\npodrían no ser capturados en este rango de IMC. La medición de la circunferencia de \\ncintura es innecesaria en pacientes con un IMC > 35 kg/m2. \\nD \\nNo se recomienda utilizar el IMC en mujeres embarazadas y en periodo de lactancia. \\nD \\n \\nTRATAMIENTO FARMACOLÓGICO \\n \\nRecomendación Clave \\nGR* \\nSe  recomienda el  orlistat como  medicamento  de  primera  elección  por  los  beneficios  \\nreportados  en  cuanto  a  reducción  de  la  presión  arterial,  niveles  de  glucosa  y  de  \\nlípidos,  \\nA \\nSe debe tomar en cuenta la alta prevalencia de efectos adversos gastrointestinales;  \\nse sugiere dar una consejería adecuada a los pacientes antes de su utilización. \\nA \\nLa dosis recomendada de orlistat es 120 mg tres veces al día. \\nA \\nSe  sugiere  utilizar  liraglutide vía  subcutánea  en  el  abdomen,  muslo  o  brazo,  en  \\npacientes adultos con obesidad y DM2, a una sola dosis diaria de 0.6 mg durante una \\nsemana. Se puede incrementar la dosis en intervalos semanales de 1.2, 1.8 o 2.4 mg \\nhasta llegar a la dosis recomendada de 3 mg. \\nA \\nSe recomienda una dosis de 10 mg de lorcaserina en pacientes adultos con obesidad, \\ndos  veces  al  día,  tomada  con  o  sin  alimentos,  sin  necesidad  de  un  periodo  de  \\ntitulación. Se debe evaluar la respuesta al tratamiento a la semana 12. \\nA \\nSe  recomienda  una  dosis  inicial  de  fentermina  3.75  mg/topiramato  23  mg  por  14  \\ndías, en pacientes adultos con obesidad, seguidos de una dosis de 7.5mg/46 mg. Se \\npuede  incrementar  la  dosis  a  11.25/69  mg  por  14  días  y  después  a  15  mg/92  mg  \\nA \\n\\nDiagnóstico y tratamiento del sobrepeso y obesidad exógena \\n \\n \\n \\ndiarios  si  después  de  12  semanas  de  tratamiento  no  se  ha  logrado  alcanzar  una  \\npérdida de peso del 3% del peso corporal basal.   \\nNo  se  recomienda  el  uso  de  la  combinación  naltrexona/bupropión en  pacientes  con  \\nobesidad por su alta incidencia de eventos adversos, el alto porcentaje de suspensión \\ndel tratamiento, y la falta de datos a largo plazo de su utilización. \\nA \\nNo  se  recomienda  la  utilización  de  suplementos  de  calcio  para  bajar  de  peso  en  \\npacientes adultos con obesidad. \\nA \\n \\n \\nTRATAMIENTO NO FARMACOLÓGICO \\n \\nRecomendación Clave \\nGR* \\nSe  sugiere  elegir  un  patrón  dietético  de  alimentos  saludables,  como  la  dieta  DASH  \\n(Dietary  Approaches  to  Stop  Hypertension)  o  la  dieta  mediterránea,  más  que  \\nenfocarse  en  un  nutriente  específico,  para  la  disminución  de  peso  corporal  en  \\npacientes adultos. \\nD \\nSe  recomienda  la  dieta  mediterránea  en  pacientes  adultos  con  factores  de  riesgo  \\ncardiovascular y para la reducción del peso corporal. \\nA \\nSe recomienda utilizar la dieta DASH en aquellos pacientes con sobrepeso y obesidad \\nque padecen de hipertensión arterial. \\nA \\nSe puede implementar una dieta baja en grasas comiendo aproximadamente 33 g de \\ngrasa por cada 1000 calorías en la dieta. \\nA \\nSi  se  elige  una  dieta  baja  en  carbohidratos,  se  sugiere  consumir  grasas  saludables  \\n(grasas  mono  y  polisaturadas)  y  proteína  (pescado,  nuez,  leguminosas,  pollo)  por  la  \\nasociación existente entre la ingesta de grasa y el riesgo de enfermedad coronaria. \\nA \\nSe recomienda la dieta muy baja en calorías en pacientes que requieren bajar de peso \\nrápidamente  (Ej,  cirugía).  Se  requieren  más  estudios  para  evaluar  su  seguridad  a  \\nlargo plazo. \\nA \\nLos candidatos a Cirugía bariátrica deben ser adultos con un IMC > 40 kg/m2, o con \\nun  IMC  de  35  a  39.9  kg/m2  con  al  menos  una  comorbilidad  severa,  que  no  han  \\nalcanzado las metas de pérdida de peso con dieta, ejercicio y farmacoterapia. \\nA \\n  \\n\\nDiagnóstico y tratamiento del sobrepeso y obesidad exógena \\n \\n \\n \\n3. CUADROS O FIGURAS \\nCuadro 1. Clasificación etiológica de la obesidad \\n \\nClasificación etiológica de la obesidad \\nCausas  Iatrogénicas  \\n• Fármacos que causan incremento de peso \\n• Cirugía hipotalámica \\nObesidad por dieta \\n• Hábitos de alimentación en niños \\n• Obesidad progresiva hiperplasia \\n• Frecuencia de la alimentación \\n• Dietas altas en grasa  \\n• Alimentación excesiva \\nObesidad  neuroendócrina \\n• Obesidad  hipotalámica \\n• Hipotiroidismo \\n• Desordenes afectivos estacionales \\n• Síndrome de Cushing \\n• Síndrome de ovario  poliquístico \\n• Hipogonadismo \\n• Deficiencia de hormona de crecimiento \\n• Pseudohipoparatiroidismo \\nFactores de conducta y sociales   \\n• Estatus socioeconómico \\n• Etnia \\n• Factores psicológicos  \\n• Comedores restringidos \\n• Síndrome del comedor  nocturno \\n• Comedores compulsivos \\n• Estilo de vida sedentaria   \\n• Reposo obligado (postoperados) \\n• Envejecimiento \\nObesidad genética  dismórfica \\n• Rasgos  autosómicos recesivos \\n• Rasgos autosómicos dominantes \\n• Rasgos ligados al cromosoma  X \\n• Anormalidades cromosómicas  \\nOtros  \\n \\n \\n \\n \\n\\nDiagnóstico y tratamiento del sobrepeso y obesidad exógena \\n \\n \\n \\nCuadro 2. Evaluación inicial del paciente con sobrepeso y obesidad \\n \\nDatos clínicos y de laboratorio para la evaluación del paciente con  sobrepeso y obesidad \\n• Estatura en centímetros \\n• Peso en kilogramos \\n• Calculo de IMC (kg/m2) \\n• Circunferencia de cintura en  cm \\n• Presión Arterial   mmHg \\n• Triglicéridos séricos mg/dl \\n• Colesterol HDL sérico mg/dl \\n• Glucosa sérica mg/dl \\n• Existen síntomas de apnea del sueño? \\n• Existen antecedentes de fármacos  que  incrementen el peso corporal? \\n• Realiza actividad física regularmente? \\n• Existe posibilidad de otros factores etiológicos? \\n \\nCuadro 3. Clasificación del IMC según la OMS. \\n \\nClasificación de Índice de Masa Corporal  según la OMS \\nIMC < 18.5 Por debajo del peso normal \\nIMC >_18.5 y < 25 Peso normal \\nIMC > 25 y < 30 Sobrepeso \\nIMC > 30 y < 35  Obesidad grado I \\nIMC >35 y <40 Obesidad grado II \\nIMC >40 Obesidad grado III \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y tratamiento del sobrepeso y obesidad exógena \\n \\n \\n \\nCuadro 4. Medición de la circunferencia de cintura. \\n \\n \\n \\nPosición de la cinta métrica para circunferencia de cintura (abdominal) en el adulto.  Para medir la \\ncircunferencia abdominal se tiene que localizar la parte superior del hueso de la cadera y la parte \\nsuperior  de  la  cresta  iliaca  derecha.  Colocar  la  cinta  métrica  en  plano  horizontal  alrededor  del  \\nabdomen al nivel de la cresta iliaca. Antes de leer la cinta métrica, asegúrese que la cinta métrica \\neste ajustada pero no comprimiendo la piel. La medición se hará al final de una espiración normal. \\n \\nFuente: National Heart, Lung, and Blood Institute. The Practical Guide: Identification, Evaluation, \\nand  Treatment  of  Overweight  and  Obesity  in  Adults.  US  Department  of  Health  and  Human  \\nServices,  Public  Health  Service,  National  Institutes  of  Health,  National  Heart  Lung  and  Blood  \\nInstitute, Bethesda, MD, October 2000. \\n \\n \\n \\n \\n \\n\\nDiagnóstico y tratamiento del sobrepeso y obesidad exógena \\n \\n \\n \\nCuadro  5.  Comorbilidades  asociadas  con  una  pobre  respuesta  al  tratamiento  de  obesidad,  y  \\nsugerencia de referencias. \\n \\nComorbilidad Herramienta de Tamizaje \\nbreve \\nReferencia \\nApnea del sueño Cuestionario STOP Especialista   en   Medicina   del   \\nsueño \\nMedicina conductual \\n \\nInsomnio crónico Pittsburgh Sleep Quality Index Medicina conductual \\n \\nDolor crónico  Ortopedia \\nTerapia física \\nMedicina conductual \\nEnfermedad             inflamatoria             \\nintestinal \\n Gastroenterología \\nMedicina conductual \\nNutrición \\nDepresión PHQ-2 Psiquiatría/Psicología \\nTrastorno de alimentación Escala de alimentación binge Medicina conductual \\nPsiquiatría/Psicología \\nTDAH,     Enfermedad     mental     \\nsevera      (trastorno      bipolar,      \\ndesorden   psicótico,   trastorno   \\nde       estrés       postraumático       \\nsevero) \\nEscala para adultos ADHD Psiquiatría/Psicología \\nMedicina                    conductual                    \\npsiquiátrica \\n \\nCuadro 6. Fármacos asociados con la ganancia de peso \\n \\nFármacos asociados  con la ganancia de peso \\n• Glucocorticoides  (prednisona) \\n• Medicamentos para Diabetes (insulina, sulfonilureas, tiazolidinedionas, meglinidas) \\n• Antipsicóticos de segunda generación (risperidona, olanzapina,  clonazepam, quetiapinas) \\n• Agentes estabilizadores neurológicos (cabamazepina, gabapentina, litio,valproato) \\n• Antihistamínicos \\n• Antidepresivos (paroxetina, citalopram, amitriptilina, imipramina, mirtazapina) \\n• Agentes hormonales (especialmente progestinas  como medroxiprogesterona \\n• Beta bloqueadores (propranolol) \\n• Alfa bloqueadores (terazosina ) \\n \\nFuente: Annals of Internal Medicine, Tsai AG, Wadden TA, In the Clinic: Obesity, Vol 159, Pg ITCS-\\n1."}'::jsonb, false, 4665, '2026-11-26 05:28:16.794+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '071-08'), 'GER', '{"alarmas": "Presencia de cualquiera de los siguientes signos requiere referencia inmediata a segundo nivel para endoscopia: inicio de síntomas en mayores de 50 años, pérdida de peso no intencionada >5%, anemia, hemorragia digestiva (hematemesis o melena), vómito persistente, disfagia, masa abdominal, antecedente familiar de cáncer gástrico antes de los 50 años, síntomas asociados a uso de AINE. También se debe referir si hay persistencia de síntomas tras tratamiento empírico y terapias para erradicación de H. pylori, o en caso de dispepsia con uso de AINE que no mejora con omeprazol o cambio de antiinflamatorio.", "prevencion": "Fomentar cambios en el estilo de vida que incluyan dieta adecuada baja en grasas y condimentos, evitar ayunos prolongados, ingesta de alimentos en menor cantidad pero más frecuentes, suspender tabaquismo y reducir o evitar consumo de alcohol, café y bebidas gaseosas. Promover actividad física regular de al menos 30 minutos, cinco días a la semana. Controlar peso corporal evitando sobrepeso y obesidad. Elevar cabecera de la cama 5 a 10 cm para mejorar síntomas. Evitar automedicación y consultar al médico para prescripción adecuada. En caso de trastornos emocionales (estrés, ansiedad, depresión), referir a valoración psicológica.", "diagnostico": "Dispepsia funcional se define por dolor o malestar en la parte central y superior del abdomen presente al menos 25% de los días en las últimas 4 semanas, sin relación con la ingesta y sin causa orgánica ni alteración metabólica demostrada. Debe descartarse causas orgánicas como ERGE, úlcera péptica y cáncer gástrico. En pacientes con síntomas de alarma (mayores de 50 años, pérdida de peso inexplicada, anemia, hemorragia digestiva, disfagia, vómito persistente, masas abdominales, antecedentes familiares, uso de AINE con síntomas o signos de alarma) se debe referir para endoscopia inmediata. En el primer nivel se recomienda realizar biometría hemática, velocidad de sedimentación globular y química sanguínea para descartar anemia y otras patologías. La endoscopia es el estudio de elección en presencia de alarmas o en pacientes mayores de 50 años. La prueba de aliento es preferida para detectar Helicobacter pylori, pero no se recomienda de rutina en población con alta prevalencia. Se deben evaluar factores de riesgo como consumo de tabaco, alcohol, café, grasas, y medicamentos como AINE.", "seguimiento": "Una vez remitidos los síntomas y suspendido el tratamiento, citar al paciente a consulta de control entre 4 a 8 semanas para evaluar evolución clínica. En caso de recurrencia de síntomas tras suspensión del tratamiento y sin signos de alarma, repetir tratamiento empírico. No se recomienda continuar farmacoterapia si hay remisión completa de síntomas tras 4-12 semanas de tratamiento.", "tratamiento": "Tratamiento empírico inicial para dispepsia sin signos de alarma: 1) Metoclopramida 10 mg preprandial oral diariamente durante 4-12 semanas; 2) si no hay mejoría, Ranitidina 150 mg oral cada 12 horas por 4-12 semanas; 3) si persiste, Omeprazol 20 mg oral diario por 4-12 semanas. Si tras 4-12 semanas de tratamiento empírico no hay respuesta, administrar tratamiento de erradicación para H. pylori si no existen síntomas de alarma: terapia triple durante 14 días con IBP (Omeprazol 20 mg c/12 h) más Claritromicina 500 mg c/12 h y Amoxicilina 1000 mg c/12 h, o alternativa con Metronidazol 500 mg c/12 h. En falla o recurrencia, valorar terapia cuádruple incluyendo Bismuto y Metronidazol según esquemas indicados. En pacientes con uso de AINE y dispepsia, suspender AINE si es posible; si no, prescribir Omeprazol 20 mg diario o cambiar a paracetamol o celecoxib. En caso de fracaso tras 4-8 semanas con estas medidas, referir a segundo nivel."}'::jsonb, false, 20737, '2026-11-26 05:29:56.397+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '071-08'), 'GRR', E'{"alarmas": "Inicio de síntomas >50 años, historia familiar de cáncer gástrico, anemia, pérdida de peso no intencionada >5%, disfagia, vómitos persistentes, hemorragia digestiva (hematemesis o melena), tumoraciones abdominales, uso de AINE con signos de alarma, tos nocturna con broncoaspiración. Estos requieren referencia urgente a segundo nivel para endoscopia y valoración especializada.", "prevencion": "Modificación de estilo de vida: evitar tabaco, alcohol, café, bebidas gaseosas y comidas ricas en grasas y condimentos. Comer porciones pequeñas y frecuentes, evitar ayunos prolongados, controlar estrés, ansiedad y depresión con apoyo psicológico si es necesario. Mantener peso adecuado, realizar ejercicio físico regular 30 minutos 5 días a la semana. Elevar cabecera de la cama 5-10 cm. Evitar automedicación y consultar siempre al médico familiar ante síntomas.", "diagnostico": "Dolor o malestar en la parte central y mitad superior del abdomen al menos 25% de los días en las últimas 4 semanas. Ausencia de daño orgánico confirmado por endoscopia. Solicitar BHC, VSG y QS para descartar anemia y otros. Endoscopia para pacientes con signos de alarma: inicio >50 años, historia familiar cáncer gástrico, anemia, pérdida de peso >5%, disfagia, vómitos persistentes, hemorragia digestiva, tumoraciones abdominales. Prueba de aliento para H. pylori si no hay alarma en menores de 50 años.", "seguimiento": "Control clínico 4 a 8 semanas después de finalizar tratamiento y remisión de síntomas. Reevaluar apego terapéutico si hay recurrencia. Repetir tratamiento empírico si hay recurrencia después de 6 meses sin signos de alarma. Vigilar respuesta a erradicación y síntomas persistentes para posible referencia.", "tratamiento": "Tratamiento empírico inicial en orden: metoclopramida 10 mg vía oral preprandial por 4-12 semanas; si no hay respuesta, ranitidina 150 mg vía oral cada 12 horas por 4-12 semanas; si persiste, omeprazol 20 mg oral cada 24 horas por 4-12 semanas. Si no hay mejoría después, erradicación de H. pylori con terapia triple: omeprazol 20 mg c/12h + claritromicina 500 mg c/12h + amoxicilina 1000 mg c/12h por 14 días o alternativas con metronidazol o ranitidina. En fracaso terapéutico, repetir erradicación con terapia cuádruple que incluye bismuto. Para dispepsia con pirosis, tratar como ERGE. En uso de AINE sin posibilidad de suspensión, omeprazol 20 mg diario o cambiar AINE a paracetamol o celecoxib.", "texto_completo": "Guía de Referencia Rápida \\n \\n \\n \\nDiagnóstico y Tratamiento de la \\nDispepsia \\nFuncional \\n \\n \\n\\n \\n2 \\nGuía de Referencia Rápida \\nK30. X Dispepsia \\n \\nGPC  \\nDiagnóstico y Tratamiento de la Dispepsia Funcional  \\n \\nISBN: 978-607-8270-10-1 \\n \\nDEFINICIÓN \\n \\nDispepsia  funcional,  dispepsia  no  ulcerosa:  conjunto  de  síntomas  que  se  caracteriza \\npor  dolor  o  malestar  referido  a  la  parte  central  y mitad  superior  del  abdomen,  que  se \\npresenta por lo menos el 25% durante las últimas cuatro semanas, que no guarda relación \\ncon la ingesta y no hay causa orgánica o alteración metabólica que justifique los síntomas.  \\nEl   dolor   localizado   en   otras   regiones   del   abdomen, el   dolor   irradiado,   pirosis, \\nregurgitaciones ácidas, asociación con trastornos en el hábito intestinal, no son parte de la \\ndispepsia funcional y sirven en el diagnóstico diferencial \\n \\nFACTORES DE RIESGO \\n \\nEl  consumo  de  tabaco,  alcohol,  café,  dietas  ricas  en  grasas,  AINES,  así  como  estrés, \\nansiedad, depresión y neurosis son factores que se han asociado a dispepsia funcional \\n \\nDIAGNÓSTICO \\n \\n• Para establecer el diagnóstico de dispepsia funcional se debe cumplir lo siguiente: \\na)    Que  los  síntomas  (dolor  o  malestar  referido  a  la  parte  central  y  mitad  superior  del \\nabdomen)  se presenten al menos en el 25% de los días en las últimas 4 semanas. \\nb)    Ausencia de daño orgánico demostrado por endoscopia gastrointestinal alta. \\n• El paciente con antecedente de dispepsia que tiene recurrencia de los síntomas \\n      entre 1 y 6 meses después de haber suspendido el tratamiento, debe ser de nuevo \\n      evaluado buscando signos y síntomas de alarma. \\n• Se deben considerar como signos y síntomas  de alarma en dispepsia (*) \\na)    Inicio de los síntomas en pacientes mayores de 50 años \\nb)    Historia familiar de cáncer gástrico, sobre todo en menores de 50 años \\nc)    Alteraciones en la exploración física (tumoraciones abdominales) \\nd)    Presencia de disfagia \\ne)    Anemia \\nf)     Pérdida de peso no intencionada o inexplicable mayor del 5% \\ng)    Hemorragia digestiva manifestada por hematemesis y/o melena \\nh)    Vómito persistente \\ni) Accesos de tos con broncoaspiración nocturna \\nj) El uso de antiinflamatorios no esteroideos (AINE) asociado a otros signos y  \\n     síntomas de alarma se considera de más alto riesgo \\n* Indican la necesidad de envío para realizar endoscopia lo más pronto posible \\n•    Los padecimientos que con más frecuencia se asocian a dispepsia son Enfermedad \\npor Reflujo Gastro Esofágico (ERGE), ulcera péptica y cáncer gástrico \\n\\n \\n3 \\nPRUEBAS DIAGNÓSTICAS \\n \\n•    La  endoscopia  es  el  procedimiento  de  elección  para  el  estudio  de  la  dispepsia  y \\nenfermedades asociadas, se deberá realizar  en  pacientes con dispepsia que tienen \\ncualquier  signo y síntoma  de alarma \\n•    En la primera consulta de los pacientes con dispepsia se debe solicitar BHC, VSG y \\nQS,  para  evaluar  la  presencia  de  anemia  (signo  de  alarma)  y  otras  patologías \\nasociadas. De ser normales no es necesario volver a solicitarlos \\n•    Otros  estudios  como  pruebas  de  función  hepática  (PFH),  radiografías  simples,  o \\nserie esofagogastroduodenal (SEGD) no son útiles para el diagnóstico de dispepsia \\nfuncional. \\n•    La prueba de aliento es la prueba de elección para la detección y para comprobar la \\nerradicación de H. pylori en los pacientes con dispepsia \\n• Es tan efectivo realizar endoscopia como dar prueba terapéutica de erradicación de \\nH. pylori en pacientes con dispepsia, menores de 50 años, sin síntomas y signos de \\nalarma, y que no hayan respondido al tratamiento empírico inicial.\\n \\n \\n \\n \\n \\nTRATAMIENTO FARMACOLÓGICO  \\n \\n•    En   todos   los   pacientes   con   dispepsia   sin   signos   y síntomas   de   alarma   o \\nmanifestaciones de ERGE se debe iniciar tratamiento empírico en el siguiente orden:\\n \\na)  Procinéticos, como metoclopramida \\nb)  Ranitidina \\nc)  Omeprazol \\n•    Si  después  de  4  a  12  semanas  de  tratamiento  empírico  hay  remisión  de  los \\nsíntomas, no existe indicación para continuar el tratamiento farmacológico \\n•    Si  después  de  4  a  12  semanas  de  tratamiento  empírico  no  hay  respuesta,  dar \\ntratamiento de erradicación para H. pylori, siempre y cuando no existan síntomas y \\nsignos de alarma o manifestaciones de ERGE. \\n•    Después del tratamiento de erradicación, si hay recurrencia de los síntomas a las 4 \\nsemanas,   se   recomienda   verificar   el   apego   terapéutico   y   valorar   repetir   el \\ntratamiento  de  erradicación  de H.  pylori,  incorporando  al  esquema  bismuto  (terapia \\ncuádruple) \\n•    Si hay datos de dispepsia y pirosis tratar de primera instancia como ERGE \\n•    En pacientes con dispepsia y uso de AINE que no sea posible suspender, se debe \\nindicar omeprazol o reemplazar el AINE con paracetamol (dolor) o celecoxib  (si es \\nnecesario el antiinflamatorio y no existe contraindicación). \\n•    En pacientes con antecedente de dispepsia y recurrencia de los síntomas  después \\nde 6 meses de suspendido el tratamiento y sin signos/síntomas de alarma, se debe \\nrepetir el tratamiento empírico \\n\\n \\n4 \\n \\n \\n \\nTRATAMIENTO NO FARMACOLÓGICO  \\n \\n•    A  los pacientes  se  les  debe de alentar  a modificar  su estilo de  vida:  seguir  un plan \\nnutricional,   programa   de   ejercicio,   control   del   peso,   suspender   tabaquismo   y \\nmoderar la ingesta de alcohol y grasas, lo cual se puede reforzar si se les otorga por \\nescrito estas recomendaciones \\n•    En  caso  de  que  el  paciente  presente  estrés,  ansiedad,  depresión  o  cualquier  otro \\ntrastorno emocional se recomienda enviar a psicología para valoración. \\n \\n \\n \\nREFERENCIA Y CONTRARREFERENCIA \\n \\nSe deberán enviar al segundo nivel de atención: \\n•    A los pacientes que persisten con síntomas a pesar del tratamiento empírico inicial y \\nde   los   dos   esquemas   de   tratamiento   para   erradicación   de H.   pylori,   previa \\nverificación del apego al tratamiento \\n•    Pacientes con dispepsia y cualquier signo y síntomas de alarma \\n•    Los pacientes con inicio de síntomas después de los 50 años \\n•    Pacientes con dispepsia y uso de AINE  que no mejoran con el uso de omeprazol o \\ncambio de AINE en 4 a 12 semanas \\n \\n \\n \\nVIGILANCIA Y SEGUIMIENTO \\n \\nSe recomienda que una vez remitidos los síntomas y suspendido el tratamiento se cite al \\npaciente en 4 a 8 semanas para control. \\n \\n \\n \\n \\nINCAPACIDAD \\n \\nSe recomienda que una vez remitidos los síntomas y suspendido el tratamiento se cite al \\npaciente en 4 a 8 semanas para control. \\n \\n \\n\\n \\n5 \\n \\nGUIA DE RECOMENDACIONES PARA EL PACIENTE CON DISPEPSIA FUNCIONAL. \\n \\n \\nDISPEPSIA: Se refiere al dolor o malestar localizado en la “boca del estomago” o \\nindigestión, suele acompañarse de nauseas, sensación de llenura, distensión, eructos. Es \\nun mal funcionamiento del estomago. \\nSe puede presentar en situaciones de estrés, ansiedad y depresión.  \\nTambién se puede deber al consumo de algunos medicamentos como naproxen, \\ndiclofenaco, piroxicam, indometacina o aspirina.  \\nComer mal, a deshoras, alimentos grasosos o condimentados, fumar, tomar bebidas \\nalcohólicas, bebidas gaseosas (sodas, refrescos) o café contribuye al empeoramiento de \\nlas molestias.   \\nSi fuiste diagnosticado con dispepsia funcional las medidas generales que te ayudarán a \\ndisminuir las molestias y que debes de seguir son: \\n \\n1.   CAMBIOS EN EL ESTILO DE VIDA:  \\n•    Evitar ayunos prolongados. \\n•    Evitar comidas abundantes, ricas en grasa y condimentos. Es preferible \\ningerir alimentos en poca cantidad y en mayor número de veces. \\n•    Evitar situaciones que provoquen estrés. \\n•    Evitar el consumo de tabaco, café, bebidas gaseosas y alcohólicas. \\n•    Mantener un peso adecuado, evitando el sobrepeso y la obesidad. \\n•    Al dormir elevar la cabecera de la cama de 5 a 10 cm. \\n•    Estos cambios en los hábitos se deben continuar a pesar de tener mejoría, \\npues se trata de un padecimiento crónico. \\n2. ACTIVIDAD FÍSICA: \\n•    Realizar ejercicio por 30 minutos, 5 días de la semana (caminar, trotar, \\nnadar, andar en bicicleta, etc.). \\n3.   AUTOMEDICACIÓN: \\n•    Evitar la automedicación, ante cualquier síntoma acudir al médico familiar \\npara que este determine el medicamento apropiado.  \\n•    Si toma otros medicamentos debe mencionárselo a su médico. \\n4.   DIETA: \\n•    Evitar alimentos ricos en grasas y en condimentos.  \\n•    Ingerir por menos de 4 a 8 vasos de agua al día. \\n•    Evitar la siesta después de las comidas. \\n5. DATOS DE ALARMA: \\n•    Si presentas pérdida de peso sin causa aparente. \\n•    Vómito con sangre o negruzco. \\n•    Evacuaciones negras u oscuras. \\n•    Dolor o dificultad para pasar los alimentos. \\n•    Si notas tumores o abultamientos en tu estómago. \\n•    Si las molestias siguen después de dos meses. \\n \\nANTE LA PRESENCIA DE CUALQUIERA DE ESTOS,  \\nACUDE A CONSULTA CON TU MEDICO FAMILIAR. \\n\\n \\n6 \\n \\nCUADRO I. TRATAMIENTO FARMACOLOGICO UTILIZADO EN LA DISPEPSIA \\n \\n \\n \\nFuente:   New   Zealand   Guidelines   Group   (NZGG).   Summary.   Evidence-based   Best   Practice \\nGuideline. Management of dyspepsia and heartburn. 2004. \\n \\n \\n \\n \\n \\n \\nCUADRO II. TRATAMIENTO DE ERRADICACION DE H. PYLORI \\n \\nTratamiento de erradicacion de h. pylori* \\n \\n \\n \\nTerapia triple  \\nOpción 1 IBP 20mg c/12 hrs 14 dias \\nClaritromicina 500mg c/12 hrs 14 dias \\nAmoxicilina 1000mg c/12 hrs 14 dias \\nOpción 2 IBP 20mg c/12 hrs 14 dias \\nClaritromicina 500mg c/12 hrs 14 dias \\nMetronidazol 500mg c/12 hrs 14 dias \\nOpción 3 Ranitidina 300mg c/12 hrs 14 dias \\nClaritromicina 500mg c/12 hrs 14 dias \\nAmoxicilina 1000mg c/12 hrs 14 dias \\nTerapia cuadruple  Opción 1 IBP 20mg c/12 hrs 14 dias \\n Bismuto 120ml c/6 hrs 14 dias \\nMetronidazol 500mg c/8 hrs  14 dias \\nClaritromicina 500mg c/12 hrs 14 dias \\n*Tetraciclina 500 mg /6 hrs es la opción en caso de cepas resistentes a \\nmetronidazol o amoxicilina. \\n \\nFuente: New Zealand Guidelines Group (NZGG). Summary. Evidence-based Best Practice \\nGuideline. Management of dyspepsia and heartburn. 2004.\\nInhibidores de la bomba de protones \\nPrincipio activo Dosis \\nrecomendada \\ntiempo Presentación \\nOmeprazol 20mg/24hrs 4-12 semanas 20mg tab/14 tab \\nPantoprazol 20mg/24hrs 4-12 semanas 20mg tab/14 tab \\nAntagonistas de receptores H2 \\nRanitidina 150mg /12 hrs 4-12 semanas 150mg tab/20 tab \\nProcineticos \\nMetoclopramida 10mg preprandial 4-12 semanas 10mg tab /20 tab \\n\\n \\n7 \\n ALGORITMOS  Algoritmo 1.Dispepsia funcional. Detección y diagnó\\nstico en el primer nivel de atención \\n \\n\\n \\n8 \\nAlgoritmo 2. Dispepsia funcional. Manejo en el prim\\ner nivel de atención \\n \\n\\n \\n9 \\nAlgoritmo 3. Dispepsia funcional. Manejo en el prim\\ner nivel de atención"}'::jsonb, false, 3947, '2026-11-26 05:30:32.204+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '076-08'), 'GER', '{"alarmas": "Referir inmediatamente a segundo nivel en presencia de crisis hipertensiva (hipertensión grave con o sin daño a órgano blanco), sospecha de hipertensión secundaria (renovascular, endocrina), hipertensión resistente que requiera cuarto fármaco, daño a órgano blanco evidente, complicaciones cardiovasculares o renales, o inadecuado control a pesar de tratamiento. También es indicación de referencia la hipertensión de difícil control, embarazo y situaciones clínicas complejas.", "prevencion": "Promover estilos de vida saludables: dieta DASH baja en sodio (preferible menos de 5 gramos de sal al día, con reducción progresiva) y rica en frutas, verduras y baja en grasas saturadas. Limitar consumo de alcohol a no más de 20-30 gramos/día en hombres y 10-20 gramos/día en mujeres. Fomentar actividad aeróbica moderada 30-60 minutos al día, 5-7 días por semana (caminar, nadar, ciclismo). Promover disminución de peso en sobrepeso/obesidad para alcanzar IMC entre 18.5 y 24.9 kg/m2. Abandonar hábito tabáquico con apoyo. Evitar consumo excesivo de cafeína y sal. Mantener adherencia terapéutica y autocontrol con bitácora de presión arterial.", "diagnostico": "Se diagnostica hipertensión arterial sistémica (HAS) con cifras persistentes de presión arterial ≥140/90 mmHg en al menos dos consultas separadas. Se recomienda medición de presión arterial por personal capacitado, usando técnica estandarizada por auscultación. Evaluar riesgo cardiovascular con modelo SCORE y buscar daño a órgano blanco (microalbuminuria, tasa de filtración glomerular, ECG, fondo de ojo). Estudios iniciales: biometría hemática, química sanguínea, perfil de lípidos, examen general de orina y electrocardiograma 12 derivaciones si están disponibles.", "seguimiento": "Pacientes con buen control y riesgo cardiovascular bajo se evaluarán cada 3 meses; pacientes con riesgo alto o descontrol cada 2 a 4 semanas para valorar respuesta y efectos adversos. Reevaluar integralmente factores de riesgo cada 1-2 años. Controlar función renal y potasio sérico al menos anualmente o cada 4-6 meses si comorbilidades. Valoración geriátrica integral anual en adultos ≥70 años. Refuerzo continuo de modificadores de estilo de vida en cada consulta. Registro domiciliario de presión arterial útil en casos de sospecha. Control estricto en pacientes con condiciones especiales (uso de anticoagulantes, enfermedad vascular, etc.).", "tratamiento": "Iniciar tratamiento farmacológico con diuréticos tiazídicos (clortalidona 12.5-50 mg/día o hidroclorotiazida 12.5-100 mg/día) en monoterapia a dosis bajas, ajustando según respuesta. Si no se alcanza la meta (<140/90 mmHg), adicionar IECA (enalapril 10-60 mg/día o captopril 25-100 mg/día), ARA II (losartán 25-200 mg/día) o calcioantagonistas de acción prolongada (amlodipino 5-10 mg/día) según tolerancia y contraindicaciones. Evitar combinación simultánea de IECA y ARA II. En hipertensión resistente agregar espironolactona 25 mg/día y vigilar función renal. En ancianos iniciar tratamiento si PAS ≥160 mmHg, evitando beta-bloqueadores como primera línea. Duración indefinida. Complementar con manejo integral de comorbilidades (diabetes, enfermedad cardiovascular, insuficiencia renal) con metas ajustadas (ej. PAS <130/80 mmHg en diabetes)."}'::jsonb, false, 42373, '2026-11-26 05:18:23.614+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '076-08'), 'GRR', E'{"alarmas": "Referir a segundo nivel ante sospecha de hipertensión secundaria (renovascular o endocrina), crisis hipertensiva con o sin daño a órgano blanco, hipertensión difícil de controlar que requiere un cuarto fármaco, sospecha o evidencia de daño a órgano blanco, daño cardiovascular, insuficiencia renal con TFG <30 mL/min o nefropatía avanzada, insuficiencia cardiaca con síntomas. También si hay hipokalemia severa, hipercalemia o sospecha de complicaciones graves relacionadas con tratamiento farmacológico.", "prevencion": "Promover estilos de vida saludables: mantener IMC entre 18.5 y 24.9 kg/m2, alimentación baja en sodio (ideal 1,200-1,500 mg/día) y grasas saturadas, alta en frutas, verduras y fibra (plan DASH). Reducir consumo de alcohol y cafeína, suspender tabaquismo con apoyo para abandono. Realizar actividad física aeróbica moderada 30 min diarios, 5-7 días a la semana, evitando ejercicio isométrico. Controlar el estrés con técnicas de relajación. Evitar alimentos procesados con alto contenido en sal y sodio. Participar en programas comunitarios de promoción de salud y seguimiento periódico para detección oportuna.", "diagnostico": "Diagnóstico de hipertensión arterial sistémica (HAS) con presión arterial persistente ≥140/90 mm Hg, confirmada en al menos dos consultas o con bitácora domiciliaria positiva. Realizar historia clínica enfocada en factores de riesgo, signos de hipertensión secundaria y daño a órgano blanco (DOB). Estudios iniciales: citometría hemática, química sanguínea, electrolitos séricos, ácido úrico, perfil lipídico, examen general de orina. ECG basal si es posible, examen de fondo de ojo y exploración neurológica para daño a órgano blanco. Estratificación de riesgo cardiovascular con modelo SCORE, considerando presencia de diabetes, daño renal o enfermedad cardiovascular.", "seguimiento": "Pacientes con riesgo cardiovascular bajo y PA controlada evaluar cada 3 meses. Pacientes con riesgo alto o cifras descontroladas evaluar cada 2-4 semanas tras inicio o ajustes de tratamiento. Solicitar estudios de laboratorio (electrolitos, función renal, perfil lipídico, glucosa) anual en pacientes sin comorbilidades y cada 4-6 meses si las hay. Valorar presencia de efectos adversos y adherencia. Valorar anualmente al adulto mayor mediante valoración geriátrica integral. Fomentar adherencia a cambios en estilo de vida y régimen farmacológico. Seguimiento activo en primer nivel con referencia oportuna según criterio clínico.", "tratamiento": "Iniciar tratamiento farmacológico si PAS ≥140 mm Hg o PAD ≥90 mm Hg después de confirmar diagnóstico y realizar modificaciones en estilo de vida. Fármacos de primera línea: diuréticos tiazídicos (ej. hidroclorotiazida 12.5-25 mg/día), IECA (ej. enalapril 10-60 mg/día), ARA II (ej. losartán 50-200 mg/día), calcio antagonistas (ej. amlodipino 5-10 mg/día) o beta-bloqueadores (ej. metoprolol 50-300 mg/día), iniciando con monoterapia a dosis bajas e incrementando según respuesta. En caso de no alcanzar control, agregar segundo y tercer fármaco combinando diurético + IECA o ARA II + calcio antagonista; no combinar IECA y ARA II. En hipertensión resistente, considerar espironolactona 25 mg cada 24 h con vigilancia renal. En pacientes con diabetes iniciar tratamiento con meta PAS <130 mm Hg y PAD <80 mm Hg, preferiblemente IECA o ARA II más calcio antagonistas. En ancianos iniciar tratamiento con PAS ≥160 mm Hg, con metas adaptadas según edad y tolerancia.", "texto_completo": "Diagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nGUÍA DE PRÁCTICA CLÍNICA\\n \\nGPC\\n \\n \\n \\nDiagnóstico y Tratamiento de la \\nH\\nIPERTENSIÓN ARTERIAL \\n \\nen el Primer Nivel de Atención\\n \\n \\n \\n \\n \\nGuía de Referencia Rápida \\nCatálogo Maestro de Guías de Práctica Clínica:\\n IMSS-076-08 \\n \\nActualización \\n2014 \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n \\n \\n \\n1. CLASIFICACIÓN ......................................................................................................................................... 3\\n \\n2. DEFINICIÓN Y CONTEXTO ........................................................................................................................... 4\\n \\n3. HISTORIA NATURAL DE LA HIPERTENSIÓN ARTERIAL .......................................................................... 5\\n \\n4. ESCALAS DE CLASIFICACIÓN CLÍNICA ..................................................................................................... 11\\n \\n5. DIAGRAMAS DE FLUJO ............................................................................................................................... 21\\n \\nÍndice \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n1. Clasificación \\n \\n \\n \\nCIE-10:I10 HIPERTENSIÓN ARTERIAL ESENCIAL PRIMARIA\\n \\n \\nGPC: \\nDIAGNÓSTICO Y TRATAMIENTO DE LA HIPERTENSIÓN \\nARTERIAL EN EL PRIMER NIVEL DE ATENCIÓN\\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nLa Hipertensión Arterial Sistémica es  un Síndrome de  etiología múltiple caracterizado  por  la  elevación \\npersistente de las cifras de presión arterial a cifras ≥ 140/90 ml/Hg. \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n2. Definición y Contexto \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n \\n \\n \\n \\n \\n \\n3.  \\nPromoción \\n \\n Aconsejar a las personas mantener un índice de masa corporal entre 18.5 y 24.9 kg/m2, para prevenir el \\nriesgo de hipertensión arterial sistémica. \\n Recomendar terapias conductuales acompañadas de técnicas de relajación para el manejo del estrés así \\ncomo  un  plan  de  alimentación  con  consumo  alto  de  frutas  y  vegetales  e  ingesta  baja  de  grasas \\nsaturadas. \\n Aconsejar al paciente la reducción de sal en la dieta diaria familiar y la suspensión del hábito tabáquico y \\nofrecer su integración a grupos de apoyo. \\n Sugerir  al  paciente,  disminuir  el  consumo  excesivo  de  café y  otros  productos  con  alto  contenido  en \\ncafeína. \\n Proponer al paciente, realizar cambios en su estilo de vida, dado que la suma de varias intervenciones \\nreduce la presión sistólica 10 mm Hg o más, aproximadamente. \\n \\nPrevención \\n  \\n Realizar exploración neurológica para identificar probable daño a órgano blanco (cerebro). \\n Realizar examen  de agudeza  visual  (cuadro de  Snellen),  así  como  exploración  de fondo  de ojo  para \\nidentificar retinopatía. \\n Estimar Riesgo Cardiovascular en los pacientes adultos \\n \\nDiagnóstico \\n \\n Es conveniente el escrutinio de la hipertensión arterial a través de la toma periódica de la presión arterial \\nmediante la estrategia oportunista en la consulta médica. \\n Es  preferible  que  las  determinaciones  de  la  presión  arterial  en  las  unidades  de  salud  se  realicen  por \\npersonal de enfermería capacitado. \\n Integrar diagnóstico de HAS desde la primera consulta médica en todo paciente diabético con Daño a \\nÓrgano Blanco (DOB) o datos de insuficiencia renal de moderada a grave (filtración glomerular <60 \\nmL/min/m2), que presente cifras de más de 140/90 mm Hg. \\n Establecer diagnóstico de HAS en la segunda consulta médica (al mes de la primera determinación de la \\npresión  arterial)  cuando  el  paciente manifieste:  Presión  Arterial  >  140/90  mm  Hg,  bitácora  positiva \\n(registro de presión arterial en su domicilio) o ambas situaciones. \\n Estratificar el riesgo cardiovascular utilizando el modelo SCORE en personas con HAS asintomáticas, sin \\nenfermedad cardiovascular, renal o diabetes. \\n Buscar de manera intencionada DOB particularmente en aquellos casos con riesgo moderado o alto, dado \\nque predice la mortalidad independientemente del puntaje de SCORE. \\n3. Historia Natural de la Hipertensión Arterial \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n Realizar una adecuada historia clínica con anamnesis detallada incluyendo historia familiar, factores de \\nriesgo y una exploración física completa, para identificar la presencia de signos y síntomas relacionados a \\nhipertensión secundaria, así como establecer el grado de DOB. \\n Determinar la presión arterial conforme a la técnica previamente descrita.  \\n Tomar el pulso en reposo desde la primera consulta médica. \\n Investigar, a profundidad: Datos clínicos de DOB y datos sugestivos de hipertensión secundaria. \\n El protocolo de estudio del paciente con HAS consiste en:  \\na) Citometría hemática \\nb) Química sanguínea y \\nc) Electrolíticos séricos, \\nd) Ácido úrico \\ne) Perfil del lípidos incluyendo HDL, LDL; colesterol total y triglicéridos y \\nf) Examen general de orina \\n \\n En establecimientos donde se cuenten con los recursos y el personal capacitado para la realización e \\ninterpretación de ECG, se sugiere un estudio basal de 12 derivaciones, con el propósito de investigar \\nhipertrofia ventricular y bloqueo. Así como Holter (MAPA) para las siguientes situaciones: a) discordancia \\nde la presión arterial registrada en casa y el consultorio; b) sospecha de hipertensión nocturna por daño \\nrenal o apnea del sueño, y c) sospecha de hipotensión autonómica. \\n En aquellos lugares, en los que se cuenten con el recurso y personal capacitado, se sugiere la realización \\nde telerradiografía de tórax (posterior-anterior), como parte del protocolo de estudio \\n \\n \\nTratamiento Farmacológico \\n \\nSin condiciones especiales: \\n \\n Recomendar  para  el  inicio  y  mantenimiento  de  los  tratamientos,  tanto  para  monoterapia  como \\ncombinada; Diuréticos tipo tiazidas, IECA, ARA II, calcio-antagonistas o beta-bloqueadores \\n Iniciar el tratamiento como monoterapia, utilizando diuréticos del tipo de tiazidas.  \\n Utilizar fármacos de primera línea con prescripción razonada, a dosis bajas e incrementar gradualmente, \\ndependiendo de la respuesta y control de la presión arterial. \\n Administrar las dosis máximas de los fármacos prescritos antes de agregar un segundo o tercer fármaco \\nen el régimen elegido. \\n En caso de requerir la combinación de 3 fármacos, se recomienda:  \\n1. Tiazidas, más \\n2. IECA o ARA II, más \\n3. Calcio-antagonistas. \\n No combinar IECA y ARA-II en un mismo régimen terapéutico, para el paciente con HAS. \\n Prescribir tratamiento antihipertensivo cuando la PAS ≥ 140 mmHg y/o PAd ≥ 90 mmHg registrada en la \\nbitácora del paciente y/o en la segunda consulta, después de las 2 semanas o simultáneamente, al inicio \\nde los cambios de estilo de vida adoptados por el paciente. \\n Iniciar tratamiento farmacológico en pacientes con PAS ≥160mmHg y PAD ≥100mmHg, sin DOB ni otros \\nfactores de RCV; así como en elevación persistente de PAS y PAD. \\n Considerar para los regímenes, combinaciones de medicamentos de primera línea cuando las cifras de \\npresión arterial continúan por arriba de la meta ≥20 mm Hg para PAS o ≥10 mm Hg para PAD. \\n Para el tratamiento de hipertensión sistólica aislada no controlada, se sugiere la combinación de dos \\nfármacos  de  primera  línea  o  en  presencia  de  eventos  adversos  utilizar  -bloqueadores,  IECA o  calcio \\nantagonista. \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n La iniciación inmediata del tratamiento farmacológico se recomienda en personas con PAS ≥180mmHg y \\nPAD ≥110mmHg, con cualquier nivel de RCV. \\n Para el tratamiento de la hipertensión resistente considerar el uso de espironolactona a dosis de 25 mg \\ncada 24 horas, vigilando su utilización en enfermos con disminución de la Tasa de Filtración Glomerular \\n(TFG). \\n Para el caso de pobre tolerancia o contraindicaciones a espironolactona, o falta de eficacia terapéutica \\nconsiderar la utilización de   o   bloqueadores. \\n En pacientes que presenten un adecuado control de la presión arterial (<140/90 mm Hg) con un régimen \\nque incluya un beta-bloqueador utilizado por largo tiempo; no representa una indicación absoluta para \\nremplazarse. \\n \\nCon condiciones especiales: \\n \\nA) Paciente Anciano \\n Iniciar tratamiento farmacológico con PAS ≥ 160 mm Hg. \\n Cuando  no  se  inicia  con  un  diurético  de  tiazidas  de  primera  elección    adicionar  este  al  régimen  del \\ntratamiento como segunda línea.  \\n Ante la falla terapéutica de 3 fármacos, se recomienda buscar las posibles causas, entre ellas:  \\na. Pobre adherencia al tratamiento \\nb. Sobrecarga de volumen diastólico \\nc. Interacciones farmacológicas (ver cuadro XVI) \\nd. Condiciones asociadas (obesidad, tabaquismo, consumo excesivo de alcohol, resistencia a la insulina, \\npseudoresistencia al tratamiento y pseudohipertensión). \\n \\n En <80 años, se considera meta terapéutica de PAS < 140 mm Hg, y de PAD no menos de 65 mm Hg.  \\n En >80 años con una PAS inicial ≥ 160 mm Hg, se recomienda reducir la PA entre 140 y 150 mm Hg, una \\nvez probada una buena condición física y mental, , así como disminuir la dosis de los fármacos de acuerdo \\na la tolerancia y sintomatología. \\n En un paciente con fragilidad depositar la decisión de terapia antihipertensiva al médico tratante y bajo el \\nmonitoreo de los efectos clínicos del tratamiento. \\n El tratamiento anti hipertensivo bien tolerado en un paciente anciano, que alcanza los 80 años de edad, \\nconsiderar su continuidad. \\n Se recomiendan diuréticos y calcio antagonistas como fármacos de primera línea para la hipertensión \\narterial sistólica aislada. \\n Se sugiere incluir en el esquema terapéutico de un paciente anciano con HAS, fármacos de primera línea \\nque no sean beta-bloqueadores.  \\n \\nB) Presencia de comorbilidades \\n \\n Prescribir terapia antihipertensiva si PAS es 140 a 160 mm Hg en presencia de DOB.  \\n Dar tratamiento farmacológico en pacientes con HAS, con RCV alto por DOB, Diabetes Mellitus (DM), \\nEnfermedad Cardiovascular (ECV) o Enfermedad Renal Crónica (ERC). \\n En pacientes de HAS con DM, iniciar tratamiento cuando la PAS se encuentre ≥ 140 mm Hg. \\n En el paciente con DM se recomienda, como orden de preferencia en la elección del fármaco (de primera \\nlínea), los siguientes: \\n1. IECA o ARA II, \\n2. Calcio-antagonistas, y \\n3. Tiazidas a dosis bajas  \\n Realizar la elección del tratamiento farmacológico en el paciente con DM valorando siempre la presencia \\nde ERC, así como la excreción urinaria de albumina y otras comorbilidades. \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n Utilizar terapia combinada con IECA o ARA II especialmente en enfermos con diabetes y proteinuria o \\nmicroalbuminuria más calcio antagonistas de efecto prolongado  \\n En el paciente con DM, la meta recomendada es PAS <130 mm Hg y PAD < 80 mm Hg. \\n \\n Se recomienda en pacientes con síndrome metabólico: \\n1) Medidas generales:  \\na. Bajar de peso  \\nb. Realizar un programa de ejercicios aeróbicos.  \\n \\n2) Utilizar para la terapia combinada: \\na. IECA o ARA II, especialmente en enfermos con proteinuria o microalbuminuria \\nb. Calcio-antagonistas de efecto prolongado \\nc. Diuréticos ahorradores de potasio. \\n \\n En paciente con cardiopatía isquémica se recomienda mantener cifras de <130/80 mm Hg. \\n Preferir el uso de los beta-bloqueadores o calcio antagonistas como terapia inicial en los pacientes con \\nangina estable \\n Recomendar beta-bloqueadores en pacientes con infarto reciente \\n Recomendar  la combinación de un IECA y un calcio-antagonista en enfermos con alto RCV \\n No se recomienda prescribir calcio-antagonistas en presencia de insuficiencia cardíaca con congestión \\npulmonar o evidencia radiológica de la misma. \\n En insuficiencia cardiaca y disfunción sistólica, los IECA y los beta-bloqueadores se recomiendan como \\nterapia inicial. \\n En enfermos con insuficiencia cardíaca o disfunción grave del ventrículo izquierdo, se recomienda para el \\nrégimen terapéutico: \\na. Diuréticos, \\nb. beta-bloqueadores, \\nc. IECA o ARA II. \\n Utilizar calcio-antagonistas cuando los beta-bloqueadores están contraindicados o no son efectivos. \\n En enfermedad cardiovascular: \\n1) Alcanzar la meta recomendable: PAS <140 mm Hg \\n2) Utilizar terapia combinada con IECA o ARA II más calcio-antagonista \\n \\n En pacientes con HAS asociada a enfermedad cerebrovascular se recomienda la combinación de IECA y \\ndiuréticos de tiazidas. \\n En pacientes con HAS e insuficiencia renal no asociada a DM y en ausencia de estenosis de la arteria \\nrenal, se recomienda de primera línea: IECA. \\n En Hipertensión arterial y nefropatía diabética o no diabética, se recomienda utilizar terapia combinada \\ncon: \\na. IECA o ARA II \\nb. Calcio antagonistas de efecto prolongado \\nc. Los diuréticos de asa reemplazan a las tiazidas cuando la creatinina sérica es 1.5 mg/dL o la TFG es < \\n30 mL/min/1.73 m. \\n2) Mantener la meta recomendable PAS <130 mm Hg, en presencia de proteinuria. \\n \\nTratamiento No Farmacológico\\n \\n \\n Realizar cambios en el estilo de vida que incluyan una mejora en la alimentación y actividad física diaria. \\n Para pacientes con HAS se recomienda una ingesta de sodio: \\n1. 1,500 mg/día en menores de 50 años \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n2. 1,300 mg/día en 51 a 70 años \\n3. 1,200 mg/ día en mayores de 70 años \\n Recomendar en la dieta, una ingesta de sal de 5 a 6 g por día y reducir a 3 g por día por sus posibles \\nefectos benéficos a largo plazo. \\n Implementar  políticas  de  salud  que  incluyan  la  participación  y  responsabilidad  social  de  la  industria \\nalimentaria, para lograr la disminución en el consumo de sal en la dieta de la población ya que el 80% del \\nconsumo total de sal por día se encuentra en los productos industrializados. \\n En pacientes hipertensos se recomienda reducción de peso corporal para lograr un IMC de 25 Kg/m2. \\n Proporcionar al paciente los siguientes consejos para disminuir el consumo de sal y sodio: \\n Escoger comidas y condimentos con poca cantidad de sal. \\n Comprar vegetales frescos, congelados o enlatados sin sal añadida. \\n Consumir aves frescas, pescados y cortes de carne delgado sin grasa en vez de los tipos enlatados, \\nahumados o procesados. \\n Escoger para el desayuno cereales con bajo contenido de sodio \\n Evitar el consumo de alimentos curados (jamón, tocino, etc.), alimentos enlatados en agua salada y \\ncondimentos.  \\n Limitar el consumo de salsa de soya, salsa teriyaki, inglesa, cátsup y mostaza.  \\n Cocinar con hierbas, especias, limón, lima, vinagre o mezclas de condimentos sin sal.  \\n Comenzar por reducir la cantidad de sal que habitualmente se usa a la mitad. \\n Disminuir el consumo de arroz instantáneo y comidas precocinadas. \\n Escoger frutas y verduras frescas en lugar de aperitivos o botanas saladas. \\n Las frutas frescas son recomendadas, aunque con precaución; debido a su alto contenido de hidratos de \\ncarbono pueden promover ganancia de peso.  \\n Recomendar 4 a 5 frutas por día (por ejemplo: naranja, plátano, toronja o melón, entre otros). \\n Aumentar el consumo de vegetales, fibra soluble, granos enteros y proteínas de origen vegetal, así como \\nreducir el consumo de grasas saturadas. \\n En pacientes con HAS se recomienda:  \\na. Consumo de pescado por lo menos 2 veces por semana. \\nb. Consumo de frutas y vegetales de 300 a 400 gr al día. \\n Se recomienda adoptar un plan alimenticio (DASH) con alto consumo de frutas, verduras y productos \\nlácteos bajos en grasa, fibra dietética y soluble, granos enteros y proteínas de origen vegetal, así como \\ncon bajo contenido grasas saturadas y colesterol. \\n El plan DASH es rico en magnesio, potasio, calcio, proteínas y fibra, considerar que la interacción de todos \\nestos nutrientes ayuda a reducir la presión arterial. \\n En adultos sanos limitar el consumo de alcohol a 2 copas o menos por día, sin exceder por semana: 14 \\nbebidas  estándar  en  hombres  y  9  bebidas  estándar  en  mujeres.  (Por  ejemplo:  una  bebida  estándar \\n[comercial] equivale a: 13.6 gr o 17.2 mL de etanol o aproximadamente, 44 ml [1.5 oz] de 80° [40%] \\nbebidas preparadas; 355 ml [12 oz] de cerveza a 5%; o 148 ml [5 oz] de vino a 12%). \\n Aconsejar al paciente realizar ejercicio aeróbico moderado al menos 30 min al día, de 5 a 7 días por \\nsemana. \\n Proporcionar  al  paciente  un  programa  de  ejercicios  aérobicos  (caminar,  trotar,  ciclismo,  aeróbico  o \\nnatación). \\n Enfatizar al paciente con HAS, no realizar ejercicios de resistencia isométrica. \\n Promoverse la suspensión del hábito tabáquico, y sugerirse la asistencia a grupos de apoyo, así como a \\nun consejero profesional \\n Se sugiere proporcionar consejo profesional y referir al paciente a grupos de apoyo para el control de los \\nfactores modificables. \\n Considerar la heterogeneidad del paciente adulto mayor antes de recomendarse el consumo y cantidad \\nde sal, al día. \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\nVigilancia y Seguimiento\\n \\n \\n Enfatizar el control de las causas asociadas HAS como son el sobrepeso y la obesidad; la dieta con alto \\ncontenido de sodio y grasas saturadas, así como la falta de actividad física y sedentarismo. \\n El paciente de HAS con RCV bajo y presión arterial controlada (meta alcanzada) puede evaluarse cada 3 \\nmeses, a criterio del médico tratante según la evolución y respuesta clínica. \\n El paciente con un RCV alto o descontrol en sus cifras de presión arterial se sugiere evaluarse cada 2 a 4 \\nsemanas, siendo necesario la individualización de cada caso dependiendo de la respuesta al tratamiento y \\nevolución clínica. \\n Después del inicio del tratamiento antihipertensivo con medicamentos se recomienda citar nuevamente \\nal paciente en intervalos de 2-4  semanas para  valorar respuesta y posibles reacciones adversas  por \\nmedicamentos. \\n Se recomienda individualizar la periodicidad de la determinación de los estudios de laboratorio con base \\nen la presencia de condiciones especiales. Se sugiere solicitar los estudios paraclínicos al menos una vez \\nal año en el paciente sin comorbilidades y cada 4-6 meses en el paciente con comorbilidades o con \\ncondiciones especiales, dependiendo de la evolución clínica y control del DOB.  \\n En  pacientes  hipertensos  con  otras  condiciones  de  alto  riesgo  (uso  de  anticoagulantes  orales, \\nenfermedad vascular cerebral, riñón único, alteraciones de la coagulación, aneurismas, entre otras), se \\nrecomienda control estricto de la presión arterial para alcanzar la meta recomendada de acuerdo a cada \\ncondición asociada en el paciente. \\n Se recomienda realizar una valoración geriátrica integral a todo paciente anciano ≥70 años de edad con \\nHAS, por lo menos una vez al año en atención primaria. \\n \\nDías de Incapacidad\\n \\n \\n El reposo debe ser indicado en casos de hipertensión grave o con repercusión a órgano blanco en tanto se \\nlogra su control con las medidas terapéuticas adecuadas. \\n \\nCriterios de Referencia\\n \\n \\n Ante la sospecha de hipertensión secundaria (renovascular o endócrina) el paciente debe ser referido a \\nsegundo nivel para evaluación completa por el servicio correspondiente. \\n En casos de crisis hipertensiva con o sin lesión a DOB, iniciar las medidas generales de tratamiento y \\nreferir a 2° o 3° nivel para su evaluación integral y control de la hipertensión arterial, según sea el caso. \\n Si  el  paciente  presuntamente  requiere  de  un  cuarto  fármaco  para  el  control  de  la  presión  arterial, \\nconsiderar el envío al médico especialista en el segundo nivel.  \\n Se  recomienda  que  los  pacientes  hipertensos  con  complicaciones  (HAS  de  difícil  control,  evidencia  o \\nsospecha de DOB) se envíen a evaluación por 2º nivel al momento de su detección. \\n El paciente hipertenso puede ser enviado anualmente a valoración oftalmológica, y a medicina interna \\ncon el propósito de detectar y controlar oportunamente la aparición de lesiones a órgano blanco.  \\n El  paciente  hipertenso  controlado  en  situaciones  especiales  (complicaciones  por  HAS  o  diabetes  se \\npropone individualizar el caso para la vigilancia y seguimiento en el primer nivel.  \\n Se sugiere enviarse al paciente para valoración cardiológica, por antecedente, sospecha o presencia de \\ndaño cardiovascular, anualmente.  \\n El paciente hipertenso puede ser enviado a valoración cardiológica, por HAS de difícil control. \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\n \\n \\n \\n \\n \\n \\nCUADRO I. MEDICIÓN DE LA PRESIÓN SANGUÍNEA POR AUSCULTACIÓN \\n \\n Estandarizar el procedimiento tanto como sea posible. \\n Sentar al paciente relajado, tranquilo y en un ambiente adecuado. \\n Con su brazo extendido y apoyado, en línea en medio del esternón. \\n Enrollar correctamente el brazalete y colocar el manómetro.  Debe enrollarse el brazalete hasta la \\nmarca del rango de la circunferencia permitida, estas marcas deben ser vistas el inicio o al empezar a \\nenrollar el brazalete. \\n Palpar el pulso humeral en la fosa antecubital del brazo. \\n Inflar  rápidamente  el  brazalete  a  20  mmHg,  por  arriba  del  punto  en  donde  el  pulso  humeral \\ndesaparece. \\n Desinflar el brazalete y anotar la presión a la cual el pulso re aparece: aproximándose la presión \\nsistólica. \\n Re inflar el brazalete a 20 mmHg. Por arriba de donde desapareció  el pulso humeral \\n Usando una mano, el estetoscopio será colocado sobre la piel en el lugar de la arteria humeral, evitar \\ncolocarlo entre la piel y el brazalete. \\n Desinflar despacio el brazalete a 2 – 3 mm Hg por segundo, escuchando los sonidos de Korotkoff. \\n \\nFASE  I.- El  primer  sonido  es  un  pulso  leve  y  repetido  que  gradualmente  incrementa  en  intensidad  y \\nduración hasta dos latidos de menor intensidad consecutivos: marcando la presión sistólica \\nFASE II.-Un breve  periodo puede seguir cuando los sonidos son débiles, auscultación gap: en algunos \\npacientes los sonidos pueden desaparecer en su totalidad. \\nFASE III.-El retorno de los sonidos nítidos empezarán a ser claros en un corto tiempo. \\nFASE IV.-Los distintos sonidos desaparecen abruptamente iniciando un suave soplido. \\nFASE V.-En el registro que los sonidos desaparecen totalmente, marcan la presión diastólica. \\n \\n Cuando  los  sonidos  desparecen  rápidamente,  desinflar  completamente  el  brazalete  y  repetir  la \\nmedición de la presión. \\n Cuando sea posible tomar lecturas al inicio y al final de la consulta. \\n \\n \\nFuente: NICE, 2006. \\n \\n \\n4. Escalas de Clasificación Clínica\\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\nCUADRO II. DEFINICIÓN Y CLASIFICACIÓN DE LA PRESIÓN ARTERIAL (PA). \\n \\nCATAGORIA SISTOLICA (mm Hg) DIASTOLICA (mm Hg) \\nOptima < 120 <80 \\nNormal 120-129 80-84 \\nNormal alta 130-139 85-89 \\nHipertensión grado 1 140-159 90-99 \\nHipertensión grado 2 160-179 100-109 \\nHipertensión grado 3 > =180 >= 110 \\nHipertensión sistólica aislada > =140 <90 \\nLa hipertensión sistólica aislada debe evaluarse de acuerdo a los grados 1, 2, y 3; basada en la valoración \\nsistólica de los rangos indicados, si la presión diastólica es <90 mm Hg. \\nLos grados 1,2 y 3 corresponden a la calificación leve, moderada y grave respectivamente.  \\n \\nFuente: European Heart Journal, 2013. \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\n \\nCUADRO III. ESTRATIFICACIÓN DEL RIESGO CARDIOVASCULAR (RCV) DE ACUERDO A FACTORES \\nDE RIESGOS Y OTROS PARAMETROS \\nEstimar RCV con base en el número de factores de riesgos que presente la persona, en ausencia de DM, DOB, ERC o \\nEnfermedad vascular establecida.  \\nFACTORES DE RIESGO (*) CRITERIOS PUNTAJE \\nSI=1/ NO=0 \\nSexo Masculino   \\nEdad (años)* Hombre: >55 \\nMujer:> 65 \\n \\nTabaquismo* Positivo  \\nDislipidemia* Colesterol:  > 190 mg/dl  \\nColesterol LDL: 115 mg/dl \\nColesterol HDL:  \\nHombres < 40 mg/dl \\nMujer: < 46 mg/dl \\nTriglicéridos: > 150 mg/dl \\nGlucosa anormal en ayuno* 102-125 mg/dl  \\nPrueba de tolerancia a la glucosa* Anormal  \\nObesidad* IMC > 30 (kg/m\\n2 \\nSC)  \\nCircunferencia abdominal  Hombres: 102 cm \\nMujeres: 88 cm \\n \\nHistoria familiar de ECV temprana* Hombre < 55 años \\nMujer < 65 años \\n \\n*Suma (total) de factores de riesgo (individuales) \\n \\nIdentificar a la persona con RCV MEDIANO - ALTO, independientemente de la presencia de los factores de riesgo(*) \\ncuando presente (datos):  \\na. DIABETES MELLITUS                                                                                                                                                   (si/no) \\nGlucosa plasmática y/o 126 mg/dl en 2 pruebas  \\nHb. Glucosilada y/o >7 % \\nGlucosa plasmática posprandial >198 mg/dl \\nb. DAÑO A ÓRGANO BLANCO ASINTOMÁTICO                                                                                                       (si/no) \\nEn el anciano, presión del pulso > 60 mm Hg  \\nERC con TFG 30-60 ml/min \\nMicroalbuminuria 30-300 mg/24 hrs \\nIdentificar a la persona con RCV ALTO, cuando presente: \\nENFERMEDAD RENAL O ENFERMEDAD VASCULAR ESTABLECIDA                                                                   (si/no) \\na. ERC con TFG < 30 ml/min ; Proteinuria > 300 mg/24 horas  \\nb. Retinopatía etapa avanzada Hemorragia, Exudados, papiledema  \\nc. Cardiovascular Infarto del miocardio, angina de pecho, y otras.  \\nd. Cerebrovascular Infarto,  hemorragia  cerebral, evento  transitorio \\nisquémico.  \\n \\nERC=  Enfermedad  Renal  Crónica,  ECV=  Enfermedad  Cardiovascular,  TFG=  Tasa  de  Filtración  Glomerular, \\nDOB= Daño a Órgano Blanco DM=Diabetes Mellitus.  \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\nNotas: La  calificación  del  RCV  se  obtiene  sumando  los  factores  individuales  y  dependiendo  de  las \\ncomorbilidades asociadas. Cuadro modificado para las unidades de primer nivel.  \\nFuente: ESH-ESC, 2013 \\n \\nCUADRO IV. GRADACIÓN DE RIESGO CARDIOVASCULAR DE ACUERDO A LAS CIFRAS DE PRESIÓN \\nARTERIAL Y LA PRESENCIA DE FACTORES DE RIESGOS Y DOB \\n \\nFactores  de  riesgo \\n(FR), \\nDOB asintomático o \\nenfermedad \\nPresión Arterial (mm Hg) \\nNormal alta \\nPAS 130-139 \\no PAD 85-89 \\nHAS Grado 1 \\nPAS 140-159 \\no PAD 90-99 \\nHAS Grado 2 \\nPAS 160-179 o \\nPAD 100-109 \\nHAS Grado 3 \\nPAS ≥ 180 o \\nPAD ≥ 110 \\nSin  otro  factor  de \\nriesgo \\n Riesgo  \\nBajo \\nRiesgo Moderado Riesgo  \\nAlto \\n1-2 factores de riesgo Riesgo Bajo Riesgo Moderado Riesgo  \\nModerado a Alto \\nRiesgo \\n Alto \\n≥ 3 factores de riesgo Riesgo   bajo   a \\nModerado \\nRiesgo  \\nModerado a Alto \\nRiesgo  \\nAlto \\nRiesgo  \\nAlto \\nDOB, ERC estado 3 o \\ndiabetes \\nRiesgo  \\nModerado a Alto \\nRiesgo  \\nAlto \\nRiesgo  \\nAlto \\nRiesgo Alto a  \\nMuy Alto \\nECV sintomática, ERC \\nestadio   ≥   4   o \\ndiabetes con DOB/FR \\nRiesgo  \\nMuy Alto \\nRiesgo  \\nMuy Alto \\nRiesgo  \\nMuy Alto \\nRiesgo \\n Muy Alto \\n \\nPA=  Presión  arterial; ERC=  enfermedad  renal  crónica;  CV  =  cardiovascular;  ECV  =  enfermedad  cardiovascular;  PAD= \\npresión arterial diastólica; HAS = hipertensión; DOB = daño a órgano blanco; FR = factores de riesgo; PAS = presión \\narterial sistólica. \\nFuente: ESH-ESC, 2013 \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\nCUADRO V. DIETA DASH* \\n \\nAlimento Ración  Descripción de alimentos (ejemplos) \\nCereales y tubérculos 7-8/día Pan de trigo entero, avena, palomitas de maíz. \\nVerduras  4-5/día \\nTomates, papas, zanahorias, judías, guisantes, calabaza, \\nespinaca  \\nFrutas  4-5/día Durazno, plátanos, uvas, naranjas, toronjas, melón.  \\nLácteos (1%)  2-3/día \\nsin grasa (descremada) o baja en grasa, sin grasa o yogurt \\nbajo en grasa, sin grasa o queso bajo en grasa  \\nLeguminosas 2-3/semana Frijoles, habas, lentejas \\nGrasas con proteína 4-5/semana Almendras, cacahuetes, nueces, semillas de girasol \\nGrasas sin proteínas 2-3/ día \\nMargarina blanda, mayonesa baja en grasa, vegetales  \\naceite (oliva, maíz, canola y cártamo)  \\nProductos de origen animal 5/día Carne cocida, pollo, pescado \\nAzucares** 5/semana \\nJarabe de arce, azúcar, jalea, mermelada, caramelos, \\nhelados. \\n \\nCUADRO VI. DISTRIBUCIÓN DE RACIONES RECOMENDADAS EN PACIENTES SIN CONDICIONES \\nESPECIALES DE ACUERDO A LA CANTIDAD DE CALORÍAS REQUERIDAS \\n \\nA. DIETA HIPOSÓDICA DE 1,200 CALORÍAS POR DÍA** \\nGrupo de alimento Ración/día \\nDistribución de raciones \\nDesayuno Comida Cena \\nVerduras 7 2 3 2 \\nFrutas 2 1 1 0 \\nCereales y Tubérculos 5 2 2 1 \\nAlimentos de origen animal 3 1 2 0 \\nLácteos 1 0 0 1 \\nGrasas sin proteína 3 1 1 1 \\nGrasas con Proteína 1 0 1 1 \\nAzúcares** 1 1 0 0 \\n \\nB. DIETA HIPOSÓDICA DE 1,500 CALORÍAS POR DÍA** \\nGrupo de alimento Ración/día \\nDistribución de raciones \\nDesayuno Comida Cena \\nVerduras 8 3 3 2 \\nFrutas 2 1 1 0 \\nCereales y Tubérculos 5 2 2 1 \\nAlimentos de origen animal 4 1 2 1 \\nLeche  2 1 0 1 \\nGrasas sin proteína 4 1 2 1 \\nGrasas con proteína 1 0 0 1 \\nAzúcares** 2 1 1 0 \\n*Fuente: Plan de alimentación DASH disponible en www.nhlbi.nih.gov/health/public/heart/hbp/tablero/new_dash.pdf \\n**Azucares: Distribuir las raciones entre los días de la semana, recomendando un consumo máximo de 5/semana. \\n***Dieta: 50% Carbohidratos, 20% proteínas, 30% lípidos \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\nCUADRO VII. ESPECIFICACIONES DE LA PORCIONES EN LA DIETA, POR CATEGORÍA DE ALIMENTOS \\n \\n \\nVERDURAS \\nAlimento Ración \\nAcelga cocida \\n1/2 taza \\nBrócoli cocido \\n1/2 taza \\nChampiñón cocido \\n1/2 taza \\nEspinaca cocida \\n1/2 taza \\nJitomate \\n1 pieza \\nLechuga   \\n3 tazas \\nNopal cocido   \\n1 taza \\nRábano   \\n2 tazas \\nVerdolaga cocida \\n1/2 taza \\n \\nGRASAS CON PROTEÍNAS \\nAlimento Ración \\nAlmendra  10 piezas \\nNuez  3 piezas \\nCacahuate tostado  14 piezas \\nSemilla de girasol 4 cucharitas \\nPistache  18 piezas \\n \\nLÁCTEOS \\nAlimento Ración \\nHelado con leche  ¾ taza \\nJocoque  ¾ taza \\nLeche descremada  1 taza \\nYogurt light  1 taza \\n \\nGRASAS SIN PROTEÍNA \\nAlimento Ración \\nAceite comestible 1 cucharadita \\nAceite de oliva 1 cucharadita \\nAderezo vinagreta 2 cucharaditas \\nAguacate 1/3 pieza \\nCrema 1 cucharadita \\nMantequilla 1 ½ cucharadita \\nMayonesa ½ cucharadita \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nPRODUCTOS DE ORIGEN ANIMAL \\nAlimento Ración \\nAtún en agua  35 g \\nBistec de res 35 g \\nChambarete  35 g \\nClara de huevo  2 piezas \\nCuete  40 g \\nFalda de res  35 g \\nFilete de pescado  45 g \\nFilete de res 35 g \\nFilete de salmón 30 g \\nHuevo cocido  1 pieza \\nMachaca  12 g \\nMilanesa de res  35 g \\nMolida de pollo  35 g \\nMuslo de pollo 1/3 pieza \\nPechuga de pollo  30 g \\nPierna de pollo  ½ pieza \\nQueso blanco 35 g \\nQueso cottage 3 cucharadas \\nRequesón  3 cucharadas \\nSardina 40 g \\nSirlón  25 g \\nTampiqueña 30 g \\n \\nCEREALES Y TUBÉRCULOS\\n \\nAlimento Ración \\nAmaranto  1/4 taza \\nArroz cocido 1/4 taza \\nAvena cocida  3/4 taza \\nBolillo sin migajón 1/3 pieza \\nEspagueti cocido 1/3 taza \\nFideo  1/2 taza \\nGalletas marías 5 piezas \\nMasa de maíz 45 g \\nPalitos de pan 3 piezas \\nPalomitas natural  3 tazas \\nPan de caja 1 pieza \\nTortilla de maíz  1 pieza \\n \\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n    \\n \\nFRUTAS \\nAlimento Ración \\nCerezas 20 piezas \\nChabacano   4 piezas \\nDurazno 2 piezas \\nFrambuesa 1 taza \\nFresa  17 piezas \\nHigo 3 piezas \\nKiwi 2 piezas \\nLima  3 piezas \\nMamey 1/3 pieza \\nMandarina 2 piezas \\nMango ataulfo 1 pieza \\nManzana  1 pieza \\nMelón  1 taza \\nNaranja   1 piezas \\nPapaya   1 taza \\nPasas  10 piezas \\nPera  ½ pieza \\nPerón 1 pieza \\nPiña 1 taza \\nPlátano  ½ pieza \\nSandia  1 taza \\nToronja  ½ pieza \\nUva roja  15 piezas \\nUva verde 18 piezas \\nZarzamora ¾ taza \\n \\nAZÚCARES \\nAlimento Ración \\nAte  15 g \\nAzúcar  2 cucharaditas \\nCajeta  2 cucharaditas \\nLeche condensada  2 cucharaditas \\nMermelada  2 cucharaditas \\nMiel de abeja 2 cucharaditas \\n \\nLEGUMINOSAS \\nAlimento Ración \\nAlubias, garbanzos, \\nhabas, lentejas \\ncocidas \\n1/2 taza \\nAlverjón 1/2 taza \\nFrijol canario, negro \\ncocido \\n1/2 taza \\nSoya cocida 1/3 taza \\nSoya texturizada \\nseca \\n35 gramos \\n*En caso de no permitir el uso de azúcares, \\nse sugiere utilizar algún edulcorante como \\nsucralosa y acesulfame K. \\n \\n \\nNota: g: gramos \\n \\nFuente: Federación Mexicana de Diabetes, \\nAC.  Disponible  en  URL  (acceso  2  enero, \\n2014): \\nhttp://www.fmdiabetes.org/fmd/pag/nut\\nricion.php?id=MTQ1. \\nReferencias             consultadas: \\nhttp://www.nutriciongrupobimbo.com/upl\\noads/pdf/tablas_equivalencias.pdf \\nSistema   Mexicano   de   Alimentos \\nEquivalentes,     segunda     Edición. \\nhttp://www.fns.org.mx/index.php?IdConte\\nnido=46&IdSubContenido=53 \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n18 \\n \\nGUÍA DE EJERCICIOS PARA EL PACIENTE CON HIPERTENSIÓN ARTERIAL SISTÉMICA \\n \\nEl consenso universal apoya la realización de actividad física como parte de la terapia en \\npacientes hipertensos, se recomienda la actividad física de intensidad moderada en la cual \\neste nivel de intensidad se alcanza con una frecuencia de 60 al 80% de la frecuencia cardiaca \\nmáxima. \\n \\nLa principal guía para la realización de ejercicio aeróbico es la frecuencia cardiaca, (entre el 60 \\nal 80% de la frecuencia cardiaca máxima), la cual puede ser obtenida mediante algún sistema \\nde  monitoreo  o  bien  a  través  de  la  prueba  de  esfuerzo;  en  ausencia  de  lo  anterior  y \\ntratándose de pacientes hipertensos controlados la frecuencia cardiaca máxima (FCM) puede \\nser calculada de la siguiente manera: \\n \\nFrecuencia cardiaca máxima = 220 – edad (en años) \\n \\nEjemplo, si un paciente tiene 55 años de edad tendríamos lo siguiente: 220-55=165, es decir, \\nsu FCM sería 165 latidos por minuto de lo que obtendríamos el 60% (99 latidos por minuto) y \\nel 80% (132 latidos por minuto) \\n \\nDebido al riesgo  de  los  pacientes  hipertensos  de  presentar enfermedad  cardiovascular  es \\nconveniente  realizar  una  prueba  de  esfuerzo  antes  de  iniciar  el  programa  de  ejercicio \\naeróbico, la prueba se recomienda para identificar isquemia, arritmias e isquemia miocárdica \\nasintomática entre otras. \\n \\nLas fases del programa de ejercicio terapéutico para el paciente hipertenso comprenden lo siguiente: \\na) Una fase de calentamiento \\nb) Una fase de ejercicio \\nAeróbico \\nb.Resistencia \\nc) Una fase de enfriamiento \\n \\nDescripción de cada una de las fases \\n \\nFASE DE CALENTAMIENTO: (realizar la toma del pulso en arteria radial a nivel de muñeca al iniciar y \\nfinalizar esta fase). Para el inicio de la actividad física existen diversas posibilidades de acuerdo a las \\ncondiciones del paciente y a las características de su entorno. Si es posible en esta fase, se puede \\nrealizar ejercicio aeróbico pero de baja intensidad como sería caminata o ciclismo por un periodo de 5 a \\n10 minutos, de lo contrario se deberán de realizar ejercicios de calistenia y de estiramiento por el \\nmismo periodo de tiempo y con la siguiente secuencia y número de repeticiones: \\nRealizar \\n10 \\nrepeticion\\nes de cada \\nejercicio \\n1A. Flexo-extensión de cuello. Flexión lateral de cuello hacia la derecha e izquierda \\n2A. Elevación-descenso de hombros. Movimientos circulares de hombros \\n3A. Con brazos extendidos al frente efectuar movimientos circulares \\n4A. Con brazos extendidos al frente efectuar flexo-extensión de codos \\n5A. Flexo-extensión de tronco con brazos extendidos \\n1B. Con manos entrelazadas realizar en forma simultánea flexo-extensión de muñeca. \\n2B. Con los dedos de las manos entrelazados se llevan los brazos extendidos hacia arriba \\ny se hace ligera hiper-extensión de tronco. \\n3B. Colocar la mano en el hombro contrario, la mano libre sujeta el codo flexionado y hace \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n19 \\n \\npresión hacia adentro, realizar en forma alternada. \\n4B. Llevar los brazos hacia atrás sujetando las manos (a la altura de la cintura), y tratar de \\nacercar ambos codos. \\n5B. De pie, apoyado sobre la mano izquierda, flexionar la rodilla derecha hacia atrás y \\nayudándose con la mano derecha sujetar el pie por el empeine acercando el talón al \\nglúteo del mismo lado, al completar las repeticiones se repite del lado contrario. \\n6B. De  pie, se adelanta la  pierna derecha y se flexiona, la pierna izquierda permanece \\nextendida,  se  realiza flexión de tronco  en esta  posición, después de completar las \\nrepeticiones se repite del lado contrario. \\n \\nFASE DE ACTIVIDAD FÍSICA MODERADA: (realizar la toma del pulso en arteria radial a nivel de muñeca \\nal iniciar y finalizar esta fase). \\n \\nTipo – aeróbico. Se recomienda realizar esta actividad en forma diaria. Puede practicarse  algunas de \\nlas siguientes modalidades, ciclismo, caminata (a paso enérgico), natación (pueden intercalarse por \\ndía), por un periodo de 30 a 45 minutos. En caso contrario se deberá efectuar la siguiente secuencia y \\nnúmero de repeticiones \\nRealizar  30 \\nrepeticiones \\nde    cada \\nejercicio \\n \\n1C. Movimientos alternos simulando la marcha \\n2C. Movimientos  alternos  simulando  la  marcha  y  coordinar  con  flexo-extensión  de \\nbrazos. \\n3C. Movimientos alternos simulando la marcha y coordinando con flexo-extensión de \\nhombros con los brazos extendidos. \\n4C. Movimientos alternos simulando la marcha y coordinar con abducción-aducción de \\nbrazos. \\n5C. Movimientos alternos simulando la marcha y coordinando con hiper-extensión de \\nhombros manteniendo los brazos extendidos. \\n6C. Flexión lateral de tronco con elevación lateral del brazo contrario sobre la cabeza, la \\nmano libre se apoya sobre la cintura. Realizar alternadamente. \\n7C. Flexión de tronco y de pierna derecha tratando con la mano izquierda de tocar el pie \\nderecho, el brazo contrario se lleva en extensión, se realiza en forma alterna. \\n8C. Desplazamiento  de  la  pierna  izquierda  por  el  frente  hacia  la  derecha,  la  pierna \\nderecha también se desplaza hacia el mismo lado con torsión de tronco (hacia la \\nderecha) y cruzando el brazo izquierdo por el frente y hacia atrás, se alterna del lado \\ncontrario. \\nTipo – Resistencia. Este tipo de actividad se recomienda llevarlo a cabo de 2 a 3 días por semana \\nempleando una variedad de ejercicios y usando diferente equipo. La intensidad ligera a muy ligera debe \\nusarse para pacientes adultos mayores o en pacientes que llevan una vida sedentaria. Los pacientes \\nhipertensos deben esperar al menos 48 horas entre las sesiones de este tipo de ejercicios. \\nRealizar 2 a \\n4  series  de \\ncada uno de \\nlos \\nejercicios, \\nempleando \\nde  10  a  15 \\nrepeticiones \\nde    cada \\nejercicio \\nEjemplos de los ejercicios que se pueden realizar: \\n1D. Cuclillas \\n2D. Abdominales \\n3D. Apoyo de ambas manos sobre una superficie (pared), los pies separados de la pared \\nla  misma  distancia  que  dan  los  brazos  extendidos,  sin  despegar  los  pies  del  suelo \\nflexionar los codos acercando el tronco a la pared, regresar a la posición de partida e \\niniciar nuevamente \\n4D. Levantar pesos aproximados a 1 kg. Elevando el brazo extendido y alternando con el \\ncontralateral \\n5D. Lanzar pesos aproximados a 1 kg (pueden ser costalitos de arena).  \\nUtilizar bandas elásticas  \\n6D. La práctica de Tai Chi Chua. \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n20 \\n \\nLos ejercicios de resistencia generalmente, en este tipo de programas, están dirigidos a los grandes grupos \\nmusculares. \\nEs  importante  mencionar  que  el  beneficio  que  se  obtiene  con  los  ejercicios  de  resistencia  se  pierde \\nrápidamente con la inactividad sobretodo en individuos adultos mayores. \\n \\nFASE DE ENFRIAMIENTO: (realizar la toma del pulso en arteria radial a nivel de de muñeca al iniciar y \\nfinalizar esta fase). \\nRealizar  10 \\nrepeticiones \\nde    cada \\nejercicio \\n \\nRepetir la serie de los primeros 5 ejercicios (del 1A. al 5A.) \\nRealizar serie de respiraciones profundas con las manos a la cintura, llevando los \\nbrazos hacia atrás durante la inhalación y al frente durante la exhalación. \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n21 \\n \\n \\n \\n \\n \\n \\n \\nFLUJOGRAMAS 1-2. DETECCIÓN, DIAGNÓSTICO Y TRATAMIENTO DE LA HIPERTENSIÓN ARTERIAL \\nSISTÉMICA  \\n \\nDomicilio\\nUrgencias\\n(Atención médica \\ncontinua)\\nPaciente que acude a su primera consulta \\n(primaria/ 1° nivel)\\nVer GPC de HAS en \\nsituaciones especiales\\n¿Presión\\n> 140/90?\\nModificar estilos \\nde vida\\nNo\\nSeguimiento anual por \\nconsulta externa\\n¿Presión \\n> 180/90 o \\nDOB?\\nSi\\nIniciar tratamiento \\nfarmacológico\\nEnviar a especialista \\n(2° Nivel), conforme a \\ncriterios de referencia\\nModificar estilos \\nde vida\\nNo\\nProtocolo \\nestudio \\n2° Consulta \\n(al mes)\\n¿ > 140/90 o \\nBitacora (+)?\\nModificar estilos \\nde vida\\nSeguimiento anual por \\nconsulta externa\\nAtención \\nambulatoria\\nSiNo\\nSi\\n2\\n \\n \\n \\n5. Diagramas de Flujo\\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n22 \\n \\n \\n2\\nDar tratamiento de iniciocon \\nfármacos de primera línea\\n¿Hipertensión \\nArterial\\ncontrolada?\\nCambiar estilos de vida \\n(dieta, rutina de ejercicios)\\nContinuarcon estilo de \\nvida saludable y\\ntratamiento farmacológico \\nde 1 ó 2 línea\\nSeguimiento activo en \\natención primaria a la salud\\nCita a la consulta \\nexterna\\nAjustartratamiento: \\n1.  Incrementar dosis de \\nfármaco de inicio hasta la \\nmáxima tolerada\\n2. Agregar un 2 fármaco \\nNo\\n¿Hipertensión \\nArterial\\ncontrolada?\\nRevaloración semanal\\nNo\\nAjustartratamiento \\nfarmacológico: \\n1.  Incrementar dosis de \\nfármacos previos hasta la \\nmáxima tolerada\\n2. Agregar un 3 fármaco \\n¿Hipertensión \\nArterial\\ncontrolada?\\nNo\\nRevaloración semanal\\nSi\\nSi\\nContinuarcon estilo de \\nvida saludable y\\ntratamiento farmacológico \\nde 2 línea\\nCita a la consulta \\nexterna\\nReferencia a 2 Nivel de \\natención\\nSeguimiento activo en \\natención primaria a la salud\\nSi\\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n23 \\n \\n \\n \\nCUADRO VIII. MEDICAMENTOS PARA EL TRATAMIENTO DE HIPERTENSIÓN ARTERIAL SISTÉMICA, \\nSEGÚN LA CLASE Y PRINCIPIO ACTIVO \\n \\n \\nCLASE FÁRMACO \\nDiuréticos tiazídicos \\nClortalidona \\nHidoroclorotiazida \\nDiuréticos de asa \\nFurosemida \\nBloqueantes de los  receptores de \\naldosterona \\nEspironolactona \\nBeta-Bloqueadores \\nMetoprolol \\nPropanolol \\nIECA  \\n(Inhibodres de la enzima convertidora de \\nangiotensina) \\nCaptopril \\nEnalapril \\nARA II \\n(Antagonsitas de los receptores de \\nangiotensina II) \\nCandesartán \\nLosartán \\nTelmisartán \\nValsartán \\n \\nCalcio antagonistas \\nNo Dihidropiridinicos \\nDiltiazem  \\nVerapamilo \\nCalcio antagonistas \\nDihidropiridinicos \\nNifedipino \\nAmlodipino \\nFelodipino \\nAlfa-\\n1\\n Bloqueadores \\nPrazocina \\nAgonistas centrales alfa-\\n2 \\ny otros \\nfármacos de acción central. \\nMetildopa \\nVasodilatadores  \\nDirectos \\nHidralacina \\nFuente: JNC-8, 2013. \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n24 \\n \\n \\n \\nCUADRO IX.COMBINACIONES DE SEGUNDA LÍNEA PARA LOS RÉGIMES DE LOS TRATAMIENTOS DE \\nINICIO Y MANTENIMIENTO \\n \\n \\nInicio/Mantenimiento \\nDiuréticos \\ntiazidas \\nCa-\\nantagonista \\nIECA ARA II \\nDiuréticos tiazidas \\n CA CA CA \\nCa-antogonista \\nCA  CA CA \\nIECA \\nCA CA  CNR \\nARA II \\nCA CA CNR \\n \\nBeta-bloqueadores \\nCU CU CU \\nCU \\n \\nNota: Verde (CA): combinación aceptable; Amarillo: (CU): combinación útil, con limitaciones; Rojo (CNR): \\ncombinación no recomendable.  \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n25 \\n \\n \\nCUADRO X. TRATAMIENTO FARMACOLÓGICO PARA EL PACIENTES CON HAS CON O SIN \\nCONDICIONES ASOCIADAS. \\nCondición Meta Terapia primera  \\nlínea  \\nTerapia   segunda \\nlínea \\nObservaciones \\nSIN CONDICIONES ESPECIALES \\nHipertensión \\nHipertensión    arterial \\ndiastólica  con  o  sin \\nhipertensión   sistólica \\n>140/90 mm Hg \\n< 140/90  \\nmm Hg \\nDiuréticos de tiazidas,  \\nIECA o ARA II, CaA, BB \\n \\nConsiderar el inicio de la terapia \\ncon  combinaciones  de  fármacos \\nde  primera  línea  si  la  presión \\narterial sistólica es ≥20 mm Hg o \\npresión  arterial  diastólica ≥10 \\nmm Hg de la meta \\nCombinaciones   de \\nfármacos de primera \\nlínea \\nNo se recomienda monoterapia \\ncon  BB en  enfermos ≥60  años \\nde edad. \\n \\n \\nVigilar presencia de hipocalemia \\nHipertensión    arterial \\nsistólica aislada  \\n \\nDiuréticos Tiazidicos, ARA II, CaA Combinaciones   de \\nfármacos de primera \\nlínea \\n \\nCON CONDICIONES ESPECIALES \\nAdulto  mayor  con  HAS \\nsistólica   aislada   (en \\nausencia de insuficiencia \\ncardíaca) \\n \\n> 80 años: \\n<150   mm \\nHg \\nDiuréticos \\nCaA \\n Titular  dosis  de  diurético  y/o \\nCaA \\nNo se recomienda BB \\nDiabetes  mellitus  con \\nmicro     albuminuria, \\nenfermedad     renal, \\ncardiovascular  y  otros \\nfactores de riesgo \\n< 130/80  \\nmm Hg \\nIECA o  \\nARA II \\nCombinación    con \\nCaA  \\nConsiderar  un  diurético  de  Asa \\nen  enfermos  con  nefropatía  y \\nsobrecarga de volumen \\nDiabetes  mellitus  no \\nincluida  en  la  categoría \\nanterior \\nIECA o ARA II \\nCaA \\nDiuréticos tiazidicos \\nCombinación     de \\nIECA+CaA \\n \\nSíndrome metabólico < 140/90  \\nmm Hg \\nIECA o ARA II,  \\nCaA \\n  \\nEnfermedad \\ncardiovascular  \\nCoronariopatía \\n<140/90  \\nmm Hg \\nIECA o ARA II \\n \\nAgregue CaA  Evitar CaA como  nifedipina  y \\ncombinación de IECA con ARA II. \\nAngina estable BB \\nInfarto  del  miocardio \\nreciente \\nBB, IECA  (ARA  II  en  caso  de \\nintolerancia a IECA) \\nAgregue CaA, si el BB \\nestá contraindicado \\nCon  el  uso  de  BB,  vigilar los \\ndatos de falla cardíaca aguda. \\nInsuficiencia cardíaca Diuréticos  (asa  o  ahorrador  de \\npotasio), BB, IECA (ARA II en caso \\nde intolerancia a IECA) \\nIECA  con  hidralazina \\nsi  el  IECA  o  el  ARA \\nestán \\ncontraindicados. \\nTitular dosis de IECA o ARA II \\nHipertrofia   ventricular \\nizquierda \\nIECA o ARA II \\nCaA \\nDiuréticos de Tiazidas \\nCombinaciones   de \\nfármacos de primera \\nlínea \\n \\nInsuficiencia renal 130/80  \\nmm Hg \\nIECA o ARA II   \\nNefropatía  no  diabética \\ncon proteinuria \\n140/90  \\nmm Hg \\nIECA o ARA II, \\nDiuréticos  \\nCombinaciones   de \\nfármacos de primera \\nlínea \\nMonitoreo de la función renal y \\nde los niveles de potasio \\nNota: BB, Beta-Bloqueadores; IECA: Inhibidores de la Enzima Convertidora de Angiotensina; ARA II: \\nAntagonistas de Receptores de Angiotensina II; CaA: Calcio-Antagonista. \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n26 \\n \\n \\nCUADRO XI. \\nMedicamentos mencionados en la guía e indicados en el tratamiento de Hipertensión \\narterial sistémica del Cuadro Básico de IMSS y del Cuadro Básico Sectorial: \\n \\nCLAVE PRINCIPIO \\nACTIVO \\nDOSIS \\nRECOMENDADA \\nPRESENTACIÓN TIEMPO EFECTOS ADVERSOS \\n2301 Hidroclorotiazida 12.5 A 100mg/día Tabletas 25 mg Indefinido Anorexia nausea vómito dolor \\nabdominal  \\nhipokalemia \\n561 Cortalidona 25 a 50 mg/día Tabletas 50 mg Indefinido Hiponatremia \\nHipotasemia \\nHiperglucemia \\nHpercalcemia \\n574 Captopril 25 a 150 mg/día Tabletas 25 mg Indefinido Tos, proteinuria \\nDisgeusia \\nDiarrea  \\n2501 Enalapril 10 a 60 mg Tabletas 10 mg Indefinido Tos, proteinuria \\nDisgeusia \\nDiarrea \\n599 Nifedipino 30 a 60 mg Tabletas 30 mg Indefinido Edema    Rubor    Cefalea \\nTaquicardia \\n596 Verapamil 80 a 480 mg Tabletas 80 mg Indefinido Hipotensión     Bradicardia \\nNaúsea Rubor \\nConstipación Edema \\n530 Clorhidrato     de \\npropranolol \\n20 a 240 mg Tabletas de 10 y \\n40 mg \\nIndefinido Bradicardia,bronco \\nespasmo,constipación \\n572 Tartrato       de \\nmetoprolol \\n50 a 300 mg Tabletas 100 mg Indefinido Bradicardia,hipotensión \\ndiarrea,fatiga \\n573 Clorhidrato     de \\nprazocin \\n1 a 6 mg Tabletas de 1 y 2 \\nmg \\nIndefinido Hipotensión     ortostática \\nmareo síncope taquicardia \\n2520 Losartan potasico 50 a 200 mg Tabletas 50mg Indefinido Vertigo Hipotensión Rash \\n2114 Felodipino 5 a 10 mg Tabletas 5 mg Indefinido Edema    Rubor    Cefalea, \\nTaquicardia \\n4201 Hidralazina 50 a 100 mg Tabletas 10 y 50 \\nmg \\nIndefinido Hipotensión  Cefalea  Lupus \\nCefalea Taquicardia  \\n103 Ácido acetilsalicilico 150 mg/día Tabletas 300 mg  Indefinido Tinnitus   prolongación   de \\ntiempos   de   coagulación \\nhemorragia hepatitis asma \\n4246 Clopidogrel 75 mg /día Tabletas 75 mg Indefinido Neutropenia  trombocitopenia \\ndiarrea dispepsia \\n5105 Esmolol 50  a  100  mcg  / \\nKg/min \\nFco ámpula \\n250mg/ml \\n10ml \\nDosis \\nRespuesta \\nHipotension        naúsea \\nbroncoespasmo  \\n4114 Nitroglicerina 50 mg en 100 cc Frasco   ámpula \\n50 mg  \\nDosis  \\nrespuesta \\nCefalea        Hipotensión \\nTaquicardia \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n27 \\n \\n \\nCUADRO XII. CONTRAINDICACIONES PARA EL USO DE FÁRMACOS ANTIHIPERTENSIVOS. \\n \\nFÁRMACO ABSOLUTAS RELATIVAS \\nDiuréticos (Tiazidas) Gota Síndrome Metabólico \\nIntolerancia a la Glucosa \\nEmbarazo \\nHipercalcemia \\nHipocalcemia \\nIECA Embarazo \\nEdema angioneuóico  \\nHipercalemia \\nEstenosis renal bilateral  \\nMujer en edad fértil \\nARA II Embarazo \\nHipercalemia \\nEstenosis renal bilateral \\nMujer en edad fértil \\nCalcio        antagonistas \\n(Dihidropiridina) \\n Taquiarritmia \\nInsuficiencia cardíaca  \\nCalcio-antagonistas \\n(Verapamilo, diltiacem) \\nBloqueo  de  A–V    (grado  2  o  3,  bloqueo \\ntrifascicular),  \\nFalla grave del ventrículo izquierdo  \\nFalla cardiaca \\n \\nbeta-bloqueadores Asma \\nBloqueo A–V (Grado 2 o 3) \\nSíndrome Metabólico \\nIntolerancia a la Glucosa \\nAtletas y enfermos físicamente activos \\nEPOC  (excepto  para  vasodilatadores, \\nbeta-bloqueadores) \\nAntagonistas  de  receptores \\nde Mineralocorticoides \\nInsuficiencia  aguda  y renal  (TFG  <30 \\nmL/min)  \\nHypercalemia \\n \\n \\nIECA: Inhibidor de Enzima Convertidora de Angiotensina,  \\nARA II: Bloqueadores de Receptores de Angiotensina \\n \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n28 \\n \\n \\nCUADRO XIII. INTERACCIONES FARMACOLOGICAS PARA EL PACIENTE ADULTO \\nJOVEN Y MAYOR \\n \\nClase   de   fármaco \\n/principio activo \\nFármaco interactuante Consecuencia Profilaxis \\nbeta-bloqueadores \\nEfectos: \\n \\nCalcio antagonista, especial \\natención con Nifedipino. \\n \\nRiesgo  de  isquemia \\nmiocárdica. \\nControl de tensión arterial, dosis \\najustada. \\nInteracciones \\nhemodinámicas \\nVerapamilo,  diltiazem.  La \\nmayoría de los anestésicos. \\n \\nRiesgo    de    falla \\ncardiaca, hipotensión. \\n \\nEscrutinio    de    insuficiencia \\ncardiaca, dosis ajustada. \\n \\nInteracciones \\nelectrofisiológicas \\n \\nVerapamilo, diltiazem. \\n \\nBradicardia,   Bloqueo \\ncompleto  de   rama, \\nhipotensión. \\n \\nDescartar  síndrome  de  seno \\nenfermo,  enfermedad  del  nodo \\nAV, Falla de VI. \\n \\n \\nAmiodarona \\n \\nBradicardia, bloqueo de \\nrama. \\n \\nDescartar enfermedad nodal. \\n \\nInteracciones hepáticas: \\n(Carvedilol,     labetalol, \\nmetoprolol,    propanolol, \\nprobablemente timolol). \\nInhibidores del   CYP2D6 \\nhepático;      cimetidina, \\nritonavir, quinidina. \\nEfectos beta-\\nbloqueadores \\nexcesivos \\nEvitar  la  interacción  o  reducir  la \\ndosis de beta-bloqueador. \\n \\nCalcioantagonistas \\nVerapamilo \\n \\nbeta-bloqueadores \\n \\nEfectos inotrópicos \\nnegativos y nodales. \\n \\nEvitar  la  interacción  o  reducir  la \\ndosis de beta bloqueador. \\n \\n \\nIntoxicación digitálica \\n \\nAsistolia,     bloqueo \\ncompleto de rama. \\nEvitar vía intravenosa. \\n \\n \\n \\n \\n \\nDigoxina \\n \\nRiesgo de toxicidad de \\ndigoxina. \\nRedosificar  digoxina y  muestreo \\nsanguíneo. \\n \\n Prazocin     y     otros \\nalfabloqueadores. \\n \\nHipotensión excesiva. \\n \\nVerificación de la tensión arterial \\nen el uso adyuvante. \\n \\n beta-bloqueadores \\n \\n \\nBradicardia \\n \\nVigilancia con electrocardiograma \\ny de la función ventricular. \\n \\nNifedipino \\n \\nPrazocin,    otros    alfa \\nbloqueadores. \\nEl  nifedipino  mejora  la \\npobre función del VI. \\nDisminuye  el  efecto  de  la \\nquinidina. \\nDiuréticos \\nTiazidicos y de Asa \\n \\nAINEs \\n \\nDisminuye  el  efecto \\nanti-hipertensivo. \\n \\nAjustar  la  dosis  del diurético o \\nadicionar otro agente. \\n IECAs, BRAs \\n \\nHipotensión excesiva, \\nuremia prerenal. \\n \\nDisminuir  la  dosis  de  diurético; \\niniciar dosificación baja. \\n \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n29 \\n \\nFuente: adaptada CHEP, 2013\\n \\n \\n \\nCaptopril \\n \\nPerdida  de  la  eficacia \\ndiurética         de \\nfurosemida. \\nCambiar a otro IECA. \\n \\n \\n \\n \\n \\nDiurético de Asa \\n \\nAspirina \\n \\nAsumir  menor  eficacia \\nen la falla cardiaca. \\n \\nSuspender  la  aspirina  al inicio \\nagudo  del  tratamiento  de  falla \\ncardiaca. \\nDiurético   ahorrador   de \\npotasio. \\n \\nIECA, ARA II \\n \\nHipercalemia. \\n \\nMonitorear  potasio  y  reducir  la \\ndosis de IECA. \\nAntagonista  del  receptor \\nde aldosterona. \\nEplerenona \\nIECA Hipercalemia. Monitorear  potasio  y  reducir  o \\neliminar IECA, BRA o el diurético \\nahorrador de potasio. \\n \\nIECA  \\n \\n \\nDiuréticos  excesivos,  raro \\nen hipertensión. \\n \\nRiesgo de falla renal. \\n \\nReducir  la  dosis  de  diurético, \\ncorregir el volumen depletado. \\n \\n Diuréticos  ahorradores  de \\npotasio, espironolactona. \\nHipercalemia \\n \\nEvitar la combinación o usar con \\nprecaución. \\n \\n AINEs Disminuye la TA. Evitarlo en lo posible \\n Aspirina \\n \\nDisminuye  efectos  de \\nla falla cardiaca. \\nDisminuir la dosis. \\n \\n Diurético de Asa \\n \\nDisminuye  el efecto \\ndiurético        de \\nfurosemida. \\nConsiderar un IECA alternativo. \\n \\nCaptopril \\n \\nFármacos \\ninmunosupresores \\nAumenta  el  riesgo  de \\nneutropenia. \\nEvitar  la  combinación,  vigilancia \\nde neutrófilos. \\nARA II \\n \\nExceso  de  diuréticos,  raro \\nen hipertensión. \\nHipotensión  al iniciarel \\ntratamiento,  riesgo  de \\nlesión renal. \\nReducir  la  dosis  de  diurético, \\ncorregir la depleción de volumen. \\n \\nARA II \\nVasodilatadores \\n \\nbeta-bloqueadores \\nmetabolizados en hígado \\n \\nDisminuye        el \\nmetabolismo      de \\nbetabloqueadores y \\naumenta  los  niveles \\nséricos. \\nDisminuir la dosis de metoprolol. \\n \\n Nitratos \\n \\nMenor  tolerancia  a \\nnifedipino,  riesgo  de \\nhipotension excesiva \\nDosificar lentamente. \\n \\nHidralazina Verapamilo \\n \\nSinergia  con  efecto \\nantihipertensivo \\nAjustar dosis. \\n\\nDiagnóstico y Tratamiento de la Hipertensión Arterial en el Primer Nivel de Atención \\n \\n30 \\n \\n \\n \\nDurango 289- 1A Colonia Roma \\nDelegación Cuauhtémoc, 06700 México, DF. \\nPágina Web: www.imss.gob.mx \\n \\nPublicado por Intituto Mexicano del Seguro Social \\n© Copyright IMSS “Derechos Reservados”. Ley Federal de Derecho de Autor \\n \\nEditor General \\nCoordinación Técnica de Excelencia Clínica \\nCoordinación de Unidades Médicas de Alta Especialidad \\n2014 \\n \\nISBN: 978-607-7790-12-9"}'::jsonb, false, 16895, '2026-11-26 05:19:03.524+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '441-11'), 'GER', '{"alarmas": "Referir a segundo nivel en dolor neuropático refractario a tratamiento farmacológico adecuado, sospecha de abuso o adicción a fármacos (conductas aberrantes, escalada rápida de dosis, síntomas de abstinencia), deterioro funcional grave, o comorbilidades psiquiátricas no controladas (depresión, ansiedad severa). Pacientes con dolor complicado por cirugía ortopédica precoz o trauma deben ser referidos a especialistas.", "prevencion": "Orientar al paciente sobre la naturaleza crónica y compleja del dolor neuropático, expectativas realistas del tratamiento. Evitar uso prolongado de benzodiacepinas para problemas de sueño. Identificar y controlar comorbilidades como ansiedad y depresión. Fomentar apoyo psicosocial interdisciplinario para mejor manejo integral y calidad de vida.", "diagnostico": "Diagnóstico clínico basado en historia y examen físico dirigido con evaluación del sistema nervioso sensitivo para detectar alodinia, hiperalgesia y alteraciones sensitivas. Uso de escalas como DN4 y EVA para medir intensidad y características del dolor. Estudios complementarios (conducción nerviosa, electromiografía) pueden apoyar, pero no son excluyentes.", "seguimiento": "Monitoreo periódico con registro de diario del dolor, evaluación de intensidad con EVA y adherencia al tratamiento. Evaluar efectos secundarios y tolerancia de medicamentos. Valoración psicológica cuando discapacidad exceda expectativas, presencia de malestar emocional, conducta adictiva o baja adherencia. Control de parámetros hematológicos y electrolitos en pacientes con carbamazepina u oxcarbazepina durante al menos un año.", "tratamiento": "Primera línea: antidepresivos tricíclicos (amitriptilina 65-100 mg/día, nortriptilina 89 mcg/día) y anticonvulsivantes gabapentina (1800-3600 mg/día) o pregabalina (150-600 mg/día). En neuralgia del trigémino, carbamazepina 200-1200 mg/día o oxcarbazepina 600-1800 mg/día. Opioides (morfinas, oxicodona, tramadol 275 mg/día) en segunda línea o combinados con gabapentina si respuesta parcial. Terapia titulada iniciando con dosis bajas. Tratamientos tópicos como lidocaína tópica para pacientes ancianos con alodinia. Duración según respuesta clínica."}'::jsonb, false, 34313, '2026-11-26 05:25:20.862+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '441-11'), 'GRR', E'{"alarmas": "Signos de abuso o conducta aberrante con fármacos, uso simultáneo de sustancias, escalada rápida de dosis, ansiedad o depresión refractaria, deterioro social, síntomas de abstinencia severos, necesidad de opioides fuertes persistente, fracaso del tratamiento farmacológico que requiere manejo en segundo nivel.", "prevencion": "Informar al paciente sobre manejo adecuado del medicamento y evitar automedicación o compartir fármacos. Promover soporte psicosocial, manejo multidisciplinario, técnicas de relajación y psicoterapia para evitar distorsiones cognitivas y prevenir ideación suicida. Evaluar historia de uso de sustancias y factores sociales o laborales que pueden afectar el tratamiento.", "diagnostico": "El diagnóstico es clínico basado en historia y examen físico detallado con valoración sensitiva, motora y autónoma. Estudios complementarios recomendados incluyen estudios de conducción nerviosa, electromiografía, microneurografía y pruebas autonómicas cardiovasculares para confirmar y caracterizar el dolor neuropático.", "seguimiento": "Uso de diario del dolor que registre frecuencia, intensidad, contexto, medicación y emociones para evaluación continua. Vigilancia periódica para ajuste médico, evaluación de adherencia, síntomas neuropsiquiátricos y posibles conductas de abuso. Integrar terapias de soporte como técnicas de relajación, higiene del sueño y terapia cognitivo-conductual.", "tratamiento": "Neuralgia postherpética: gabapentina, pregabalina o opioides; lidocaína tópica preferida en ancianos con alodinia. Neuralgia del trigémino: carbamazepina 200-1200 mg/día o oxcarbazepina 600-1800 mg/día. Neuropatía diabética dolorosa: pregabalina, amitriptilina o gabapentina como primera línea; tramadol segunda línea. Dolor central: lamotrigina (post-EVC o lesión espinal); canabinoides en esclerosis múltiple si fallan otros tratamientos. Iniciar con dosis mínimas y ajustar según eficacia y efectos adversos.", "texto_completo": "Guía de Referencia Rápida \\n \\n \\n \\n \\nTratamiento farmacológico del dolor \\nneuropático  \\nen mayores de 18 años  \\n \\n \\n \\nGPC \\nGuía de Práctica Clínica \\nCatálogo maestro de guías de práctica clínica: IMSS-441-11 \\n\\n \\nTratamiento farmacológico del dolor neuropático en mayores de 18 años \\n \\n \\n2 \\n \\n \\nGuía de Referencia Rápida\\nGuía de Referencia RápidaGuía de Referencia Rápida\\nGuía de Referencia Rápida \\n \\nCIE-10: Dolor neuropático  \\nGPC  \\nTratamiento farmacológico del dolor neuropático en mayores de 18 años \\nISBN en trámite \\n  \\n \\n \\nDEFINICIÓN\\nDEFINICIÓNDEFINICIÓN\\nDEFINICIÓN \\n  \\n \\n \\n  \\n \\nLa  Sociedad  Internacional para  el  estudio  del  dolor  (IASP)  define  el  dolor  neuropático  como:  “el \\ndolor  iniciado  o  causado  por  una  lesión  primaria  o disfunción  del  sistema  nervioso  central  o \\nperiférico con alto grado de complejidad, definido frecuentemente por presentarse en ausencia de \\ndaño tisular agudo concurrente o progresivo; pudiendo variar su intensidad desde leve hasta severo \\ne incapacitante, que inclusive puede impulsar al que lo padece a tendencias suicidas. Se caracteriza \\npor  ser  disestésico,  quemante,  urente,  paroxístico,  con  déficit  sensorial  y  respuesta  anormal  a \\nestímulos (alodinia e hiperpatía). \\n \\n \\n \\nDIAGNÓSTICO\\nDIAGNÓSTICODIAGNÓSTICO\\nDIAGNÓSTICO \\n  \\n \\n \\n  \\n \\nEl  diagnóstico  del  dolor  neuropático  es  esencialmente  clínico:  las  bases  se  fundamentan  en  la \\nhistoria  clínica  y  en  el  examen  físico  del  paciente.  Los  exámenes  de  laboratorio,  de  imagen  y  de \\nelectrofisiología  confirman  el  diagnóstico  clínico,  pero  los  resultados  negativos  no  excluyen  el \\nmismo. \\n \\nEl médico debe hacer una correcta semiología de las características del dolor (tiempo de evolución, \\ncualidad,  localización,  intensidad,  causa)  y  realizar  un  examen  físico  general,  exploración \\nneurológica  que  incluya  valoración  del  sistema  nervioso  sensitivo  (alodinia,  hiperalgesia, \\npropiocepción  y  percepción  de  estímulos  vibratorios  con  un  diapasón),  valoración  del  sistema \\nnervioso  motor  (fuerza,  tono,  reflejos,  trofismo  muscular,  posiciones  antiálgicas,  movimientos \\nanormales  y  disfunción  de  los  movimientos  activos  y  pasivos)  y  del  sistema  nervioso  autónomo \\n(temperatura, regulación vasomotora, sudoración, reacciones pilomotoras, cambios tróficos y otras \\nanomalías) \\n \\nEn el diagnóstico se pueden utilizar los siguientes exámenes complementarios: \\n• Estudios de conducción nerviosa \\n• Microneurografía:  \\n• Electromiografía \\n• Prueba de Minor \\n• Pruebas autonómicas cardiovasculares. \\nEntre los instrumentos a emplear se pueden citar: \\n• Algómetro \\n\\n \\nTratamiento farmacológico del dolor neuropático en mayores de 18 años \\n \\n \\n3 \\n \\n \\n• Prueba térmica \\n• Filamentos de von Frey \\n• Vibrámetro \\n \\n \\n  \\n \\n \\n  \\n \\n \\n  \\n \\nTRATAMIENTO\\nTRATAMIENTOTRATAMIENTO\\nTRATAMIENTO \\n  \\n \\n \\n  \\n \\nEl  tratamiento  del  dolor  neuropático  requiere  la  participación  de  un  equipo  multidisciplinario \\nque incluya el apoyo psicosocial, mejora de la comunicación y contención del dolor.  \\nLos objetivos del manejo del dolor son reducir o eliminar el dolor en un período corto, mejorar la \\nfunción del paciente y la calidad de vida del mismo. \\n \\nEl tratamiento farmacológico es a base de neuromoduladores coadyuvantes del dolor debido a \\nque  los  analgésicos  no  brindan  mayores  beneficios. El  tratamiento  se  debe  individualizar  de \\nacuerdo al tipo de dolor neuropático, comorbilidades, edad del paciente. En ocasiones se pueden \\nasociar  2  o  más  fármacos  para  lograr  mejor  beneficio.  También  se  debe  de  iniciar  con  dosis \\nmínimas  tolerables  y  aumentar  hasta  obtener  el  efecto  deseado  o  la  aparición  de  efectos \\nadversos \\n \\nNeuralgia posthérpetica\\nNeuralgia posthérpeticaNeuralgia posthérpetica\\nNeuralgia posthérpetica \\n  \\n \\nSe recomienda como primera línea de tratamiento para el manejo de la neuralgia postherpética \\nla gabapentina, pregabalina y los opioides. \\n \\nLa lidocaína tópica ha sido evaluada en pacientes con alodinia en estudios con un tiempo corto \\nde seguimiento no obstante debido a su excelente tolerabilidad su uso puede ser preferido en el \\nanciano, particularmente con alodinia \\n \\nNeuralgia del trigémino\\nNeuralgia del trigéminoNeuralgia del trigémino\\nNeuralgia del trigémino \\n  \\n \\n \\n  \\n \\nLa Carbamazepina y la Oxcarbazepina son los medicamentos de primera línea. \\nSe recomienda una dosis de Carbamazepina de 200 a 1200 mg al día y de Oxcarbazepina 600-\\n1800 mg/d. \\n \\nNeuropatía diabética dolorosa\\nNeuropatía diabética dolorosaNeuropatía diabética dolorosa\\nNeuropatía diabética dolorosa \\n  \\n \\nSe  recomienda  como  primera  línea  de  tratamiento  en el  dolor  central  el  uso  de  pregabalina, \\namitriptilina o gabapentina.   \\n \\nEl tratamadol puede utilizarse como medicamento de segunda línea \\n \\nDolor Central\\nDolor CentralDolor Central\\nDolor Central \\n  \\n \\n \\n  \\n \\nLamotrigina puede ser considerada en dolor central post-EVC o lesión espinal \\n \\nCanabinoides pueden ser utilizados en Esclerosis múltiple si los otros tratamientos fallan. \\n  \\n \\n\\n \\nTratamiento farmacológico del dolor neuropático en mayores de 18 años \\n \\n \\n4 \\n \\n \\nEs importante también explorar: \\n• Historia de uso de sustancias en el paciente y familia \\n• Situación legal o laboral (si existe) relacionada a su padecimiento  \\n• Expectativas del paciente hacia su tratamiento farmacológico \\n• Adherencia del paciente hacia su tratamiento  \\nEn las primeras sesiones de evaluación es importante solicitar el empleo de un diario del dolor, para \\nel seguimiento del paciente cuando se encuentra fuera del consultorio que incluya: \\n• -Frecuencia e intensidad del dolor en diversos contextos y frente a diferentes personas. \\n• -Toma de medicamentos horarios y de rescate. \\n• -Emociones asociadas a la presencia del dolor \\n \\nLas técnicas de relajación, ayudan a reducir la alerta física y mental del paciente cuando está en su \\ncama,  también  se  emplea  higiene  del  sueño    y  terapia  cognitiva  en  el  caso  de  que  el  paciente \\npresente ideas disfuncionales respecto al tiempo de sueño. \\n \\nLa  terapia  cognitivo  conductual  y  la  psicoterapia  interpersonal  han  resultado  efectivas  para  el \\ntratamiento  de  síntomas  depresivos  en  pacientes  con  dolor  neuropático.  Las    intervenciones \\ncognitivo conductuales que buscan reducir las distorsiones de pensamiento de tipo catastrófico son \\nadecuadas para prevenir la ideación suicida  en los pacientes con dolor, este tipo de intervenciones \\ntambién ayudan a reducir el distress. \\n \\nEs  importante  observar  que  el  paciente  no  presente conductas  aberrantes  de  abuso  de  fármacos \\ncomo: \\n• -Vender los medicamentos que se le han prescrito \\n• -Obtener medicamentos de fuentes no medicas \\n• -Uso continuo de alcohol y otras drogas \\n• -Robo de medicamentos  \\n• -Usar las formulaciones orales, por vía nasal o inyección  \\n• -Forzar la prescripción  \\n• -Deterioro funcional  \\n• -Reportar frecuentemente que ha perdido o le han robado la receta  \\n• -Usar dosis no autorizadas \\n• -Buscar la prescripción de la receta con múltiples médicos  \\n• -Pedir que se le prescriba un fármaco en particular \\n• -Buscar fármacos similares al que se le prescribe  \\n• -Usar el fármaco para tratar un síntoma diferente para el cual se prescribió \\n \\nOtros síntomas de alarma que el médico debe considerar son: \\n• -Escalada rápida del medicamento \\n• -Ansiedad y Depresión que no responden a tratamiento \\n• -Deterioro de las actividades sociales \\n• -Que el tratamiento sea exitoso únicamente con un tipo de opioide  \\n• -Síntomas de abstinencia severos cuando se suspende el fármaco \\n \\nEl uso de opioides está contraindicado en pacientes que tienen una adicción establecida, cuando sea \\nnecesario se deberá preferir metadona o buprenorfina. \\n\\n \\nTratamiento farmacológico del dolor neuropático en mayores de 18 años \\n \\n \\n5 \\n \\n \\nALGORITMOS \\nALGORITMOS ALGORITMOS \\nALGORITMOS \\n\\n \\nTratamiento farmacológico del dolor neuropático en mayores de 18 años \\n \\n \\n6 \\n \\n \\nNeuralgia del \\nTrigémino\\nDOLOR MODERADO \\nOPIOIDE DEBIL(TRAMADOL) \\n+PARACETAMOL+AINE+ADYUVANTES\\nTRATAMIENTO DISESTESIATRATAMIENTO ANALGESICO \\nCARBAMAZEPINA\\nó\\nOXCARBACEPINA\\n+\\nAINE+PARACETAMOL\\nDOLOR SEVERO\\nOPIOIDE FUERTE \\n+PARACETAMOL+AINE+ADYUVANTES\\nAlgoritmo 2. Tratamiento del dolor neuropático secundario a Neuralgia del \\nTrigémino \\n¿RESPONDE A \\nTRATAMIENTO?\\nAlta y vigilancia \\nperiódica con \\ndiario del dolor\\nSI\\nNO\\nTratamiento \\nintervencionista en \\nsegundo y tercer nivel de \\natención por médico \\nespecialista en ortopedia, \\nneurología y algología\\n\\n \\nTratamiento farmacológico del dolor neuropático en mayores de 18 años \\n \\n \\n7 \\n \\n \\n\\n \\nTratamiento farmacológico del dolor neuropático en mayores de 18 años \\n \\n \\n8"}'::jsonb, false, 3032, '2026-11-26 05:25:55.033+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '718-18'), 'GER', '{"alarmas": "Glucosa capilar >300 mg/dL con síntomas; hipoglucemia severa o recurrente; signos de insuficiencia renal crónica; cetoacidosis diabética; síntomas de infecciones graves; incapacidad para mantener el tratamiento en el primer nivel; complicaciones agudas o crónicas avanzadas; embarazo.", "prevencion": "Uso del cuestionario FINDRISC para detección temprana; promover dieta saludable (preferente mediterránea); aumentar actividad física a al menos 30 minutos diarios; control individualizado de factores de riesgo (IMC, hipertensión, sedentarismo); evitar consumo de tabaco; educación y empoderamiento del paciente para mantener adherencia y cambios en estilo de vida; seguimiento regular para detectar precozmente diabetes o prediabetes.", "diagnostico": "Tamizaje con cuestionario FINDRISC; riesgo alto si puntaje >9 y glucosa en ayunas >100 mg/dL. Confirmación con HbA1c >6.5% o tolerancia oral a glucosa >200 mg/dL a las 2 horas tras carga de 75 g. No usar HbA1c en condiciones que alteren recambio de glóbulos rojos (embarazo avanzado, hemodiálisis, transfusiones recientes, eritropoyetina, anemia hemolítica).", "seguimiento": "Control trimestral de HbA1c, glucosa preprandial (80-130 mg/dL) y postprandial (<180 mg/dL). Reevaluar riesgo anual con FINDRISC o glucosa. Monitorizar adherencia y eficacia terapéutica. Ajustar tratamiento según metas. Valorar signos de hipoglucemia y complicaciones. Realizar evaluación clínica continua y pruebas de función renal anuales si hay albuminuria.", "tratamiento": "Iniciar metformina 850 mg cada 12 horas junto con cambios en estilo de vida, incluyendo dieta mediterránea y actividad física regular. En HbA1c >8%, agregar inhibidor DPP-4 como primera combinación; si no hay control, considerar sulfonilureas de bajo riesgo (glimepirida, glicazida). Evitar glibenclamida por alto riesgo de hipoglucemia. Inhibidores SGLT-2 solo si DPP-4 no es opción. En terapia dual con falla al control, añadir insulina basal (NPH 10 U o 0.2 U/kg nocturna) en no obesos o agonista GLP-1 si no obesos. Tratar microalbuminuria con IECA o ARA II independientemente de la presión arterial."}'::jsonb, false, 40148, '2026-11-26 05:15:52.883+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
INSERT INTO gpc_cached_content (gpc_id, source_type, content_json, is_stale, tokens_used, processed_at) VALUES ((SELECT id FROM gpc_index WHERE gpc_code = '718-18'), 'GRR', E'{"alarmas": "Hiperglucemia sintomática con glucosa >300 mg/dL, síntomas de descompensación, signos de infección grave, hipoglucemia recurrente, insuficiencia cardiaca o edema con uso de pioglitazona, requerimiento de escalamiento a insulina, pérdida del control glucémico a pesar de tratamiento máximo. Estas situaciones requieren referencia a segundo nivel.", "prevencion": "Promover actividad física diaria ≥30 minutos, dieta mediterránea con incremento de fibra y reducción de grasas saturadas para pacientes con riesgo elevado o diagnóstico reciente. Consejería sobre riesgos de diabetes y beneficios de estilo de vida saludable. Apoyo para modificación de factores de riesgo, control del peso e incorporación de medidas alimenticias y actividad física efectiva. Realizar tamizaje en grupos de riesgo y seguimiento periódico.", "diagnostico": "Utilizar cuestionario FINDRISC para tamizaje en adultos de 40-74 años. Confirmar con HbA1c en pacientes con glucosa en ayuno entre 100-125 mg/dL. Diagnóstico de diabetes si HbA1c ≥6.5%, glucosa en ayuno ≥126 mg/dL o glucosa posprandial a las 2 horas ≥200 mg/dL. En embarazo, hemodiálisis, transfusiones o enfermedades hematológicas no usar HbA1c para diagnóstico.", "seguimiento": "Evaluación clínica y medición de HbA1c trimestralmente. Control de glucosa capilar preprandial objetivo 80-130 mg/dL y postprandial <180 mg/dL. Revisar adherencia a tratamiento y estilos de vida. Reevaluar cada 3 años riesgo en pacientes sanos; en prediabetes, repetir examen anual. Ajustar tratamiento farmacológico y dosis según respuesta glucémica y tolerancia.", "tratamiento": "Iniciar metformina 850 mg hasta tres veces al día por vía oral desde diagnóstico, asociado a cambios intensivos en estilo de vida. Si HbA1c >8%, agregar un segundo fármaco: inhibidor DPP-4 (sitagliptina 100 mg/día) de primera elección, o sulfonilurea de bajo riesgo (glimepirida 2-8 mg/día) si DPP-4 contraindicados o no disponibles. Si HbA1c >9% o glucosa >300 mg/dL con síntomas, comenzar terapia dual o triple farmacológica. Si fracaso a dos o más antidiabéticos, iniciar insulina NPH nocturna 10 U o 0.2 U/kg, ajustando dosis cada 3 días según glucosa capilar en ayuno, incrementando 2-4 U hasta glucosa 80-130 mg/dL.", "texto_completo": "GUÍA DE PRÁCTICA CLÍNICA GPC\\n \\n \\n \\n \\n                                                                                                                   \\n \\n \\nDiagnóstico y Tratamiento \\nFarmacológico de la\\nDIABETES MELLITUS TIPO 2 EN \\nEL \\nPRIMER NIVEL DE ATENCIÓN\\n \\nGuía de Referencia Rápida\\nCatálogo Maestro de Guías de Práctica Clínica: gpc-iMSS-718-18\\nActualización \\n2018 \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de \\nAtención  \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\n \\nDurango 289- 1A Colonia Roma \\nDelegación Cuauhtémoc, 06700 México, DF. \\nPágina Web: www.imss.gob.mx\\n \\n \\nPublicado por Instituto Mexicano del Seguro Social \\n© Copyright Instituto Mexicano del Seguro Social “Derechos Reservados”. Ley Federal de Derecho de Autor \\n \\nEditor General \\nCoordinación Técnica de Excelencia Clínica \\nCoordinación de Unidades Médicas de Alta Especialidad \\n \\nLa  guía  de  referencia  rápida  tiene  como  objetivo  proporcionar  al  usuario  las  recomendaciones  clave  de  la  guía  \\nDiagnóstico  y Tratamiento  Farmacológico  de  la  Diabetes  Mellitus  Tipo  2  en  el  Primer  Nivel  de  Atención, \\nseleccionadas  con  base  a  su  impacto  en  salud  por  el  grupo  desarrollador,  las  cuales  pueden  variar  en  función  de  la  \\nintervención de que se trate, así como del contexto regional o local en el ámbito de su aplicación. \\n \\nPara mayor información, se sugiere consultar la guía en su versión extensa de “Evidencias y Recomendaciones” en el \\nCatálogo Maestro de Guías de Práctica Clínica, la cual puede ser descargada de Internet en:  \\n \\nhttp://imss.gob.mx/profesionales-salud/gpc \\n \\nDebe  ser  citado  como:  Diagnóstico  y Tratamiento  Farmacológico  de  la  Diabetes  Mellitus  Tipo  2  en  el  Primer  \\nNivel  de  Atención.  Guía  de  Rerencia  Rápida:  Guía  de  Práctica  Clínica.  México,  Instituto  Mexicano  del  Seguro  Social;  \\n2018  \\nDisponible en: http://imss.gob.mx/profesionales-salud/gpc \\n \\nISBN en trámite \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n1. Diagramas de Flujo \\nAlgoritmo 1. Identificación y manejo del riesgo en Diabetes Mellitus Tipo 2 \\nIdentificación y manejo de riesgo en Diabetes \\nMellitus Tipo 2\\nScore de riesgo \\nintermedio o bajo \\nScore de alto riesgo\\nConsiderar examen de sangre para personas \\ndel sur de Asia y de China > 25 años y con un \\nIMC >23 kg/m2\\nOfrecer consejería breve \\nrespecto a:\\nLos riesgos de desarrollar \\ndiabetes\\nLos beneficios de un estilo de \\nvida saludable\\nLa modificación de factores de \\nriesgo\\nRealizar un examen de sangre\\nEscoger entre glucosa plasmática en \\nayunas o HbA1c\\nRiesgo Moderado\\nGPA <100 mg/dL o \\nHbA1c < 6%\\nRiesgo Alto\\nGPA 100 a 125 mg/\\ndL o HbA1c 6 a 6.4%\\nDiabetes Tipo 2 probable\\nGPA >126 mg/dL ó HbA1c \\n>6.5%\\nOfrecer consejería \\nbreve para:\\nDiscutir los riesgos de \\ndesarrollar diabetes\\nAyudar a modificar \\nfactores de riesgo \\nindividuales\\nOfrecer servicios de \\napoyo adaptados\\nOfrecer programa \\nintensivo de cambios en \\nestilo de vida para:\\nIncrementar actividad física\\nLograr y mantener pérdida \\nde peso\\nIncrementar fibra en dieta, \\nreducir ingesta de grasa, \\nparticularmente saturadas\\nRealizar examen de \\nsangre si se encuentra \\nasintomático, para \\nconfirmar o rechazar la \\npresencia de diabetes\\nSí se confirma\\nIngresa a algoritmo de \\nmanejo de diabetes\\nNo se confirma\\nOfrecer programa intensivo \\nde cambios en estilo de \\nvida\\nReevaluar peso e IMC y \\nofrecer examen de sangre al \\nmenos una vez al año \\nReevaluar riesgo al \\nmenos cada 3 años\\nReevaluar riesgo al \\nmenos cada 5 años\\n40-74 años\\nUsar herramienta de evaluación del \\nriesgo validada o cuestionario de \\nautoevaluación validado\\n>75 años\\nUsar herramientas de \\nevaluación de riesgos y \\ncuestionarios\\nGrupos de alto riesgo\\nAfrocaribeños, africanos, hispanos/\\nlatinos, personas del sur de Asia, etc.\\nPacientes con condiciones que \\nincrementan el riesgo de padecer DM tipo \\n2.\\nUtilizar herramientas de evaluación de \\nriesgos y cuestionarios.\\n \\n \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\nAlgoritmo 2. Tratamiento Farmacológico de pacientes con Diabetes Mellitus Tipo 2 \\n \\nDx reciente DM tipo 2\\nConsulta nutricional \\nCambio intensivo estilo de vida \\nUso de metformina \\nHbA1c <7.9%\\nHbA1c 8 - 8.5%%\\nHbA1c >9%\\nó\\nGlucosa >300mg/dl y \\nsintomatología\\nTerapia dual\\n- Glibenclamida 5mg máx 15mg/dl dividido \\n2 tomas ó\\n-Pioglitazona 15mg c/24hrs, máximo \\n45mg/día (precaución en ICC/edema) ó\\n-Sitaglipina 100mg c/24hrs (máx)\\nDep. Creatinina 30-40  50mgc/24hrs (máx)\\nMantener monoterapia\\n-Metformina 850mg hasta c/8hrs \\n-Considerar Sitaglipina en caso de \\nintolerancia o contraindicación para \\nmetformina (insuf. Hepatica) \\nDep. Creatinina <30ml, alergia \\nCumple Glicemia \\nrecomendada\\nSeguimiento \\ntrimestral \\nEvaluación \\nclínica \\nInestable\\nEstable \\nHbA1c 8.6 - 8.9%\\nTerapia triple\\n* si el paciente acepta considerar terapia \\ncon  insulina\\n+pioglitazona+sitagliptina \\n-Metformina+glibenclamida+pioglitazona\\n+glibenclamida+sitagliptina\\n+glibenclamida+insulina\\n+pioglitazona+insulina\\nCumple Glicemia \\nrecomendada \\nSe puede ajustar dosis o esquema de tratamiento de acuerdo a requerimientos del paciente \\nNO\\nIniciar Insulina NPH\\nMetformina y dosis inicial:\\nA) Insulina NPH 10UI \\nO\\nB)Insulina NPH 0.2 x peso Kg\\n*Ver anexo para cálculo de dosis inicial, \\nrequerimiento diario y titulación. \\nVer Terapia triple\\nó\\nVer Insulina \\nSI\\nCumple Glicemia \\nrecomendada\\nVer Terapia \\ndoble\\nSI\\nNO\\nNO\\nSI\\nMetas cumplidas\\n-Reforzar cambios en \\netilo de vida \\n-Revisión trimestral  \\nMetas de control:\\nHBa1 <7 %\\nGlucosa capilar preprandial: \\n80-130mg/dl \\nGlucosa capilar postprandial: \\n<180mg/dl \\nMetas no cumplidas\\nRealizar esta lista de \\nverificación para escalar \\nel tratamiento.  \\nLista de verificación\\n1. Valorar bitácora de glucosa capilar\\n2. Búsqueda intencionada de síntomas de hipoglucemia \\n3.  Valorar apego al tratamiento  y cambios en el estilo de vida \\n4. Descartar infecciones agudas \\n  \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\nAlgoritmo 3. Inicio y ajuste de insulina en Diabetes Mellitus Tipo 2 \\n \\nInicio y Ajuste de regimen de Insulina en Diabetes Mellitus Tipo 2\\nIniciar con insulina de acción intermedia por las noches o a la \\nhora de acostarse o insulina de larga duración por las mañanas, \\nSe puede iniciar con 10 U o 0.2 U por kg\\nChecar glucosa en ayuno diario e incrementar dosis, usualmente 2 U cada 3 \\ndíashasta que los niveles en ayuno se encuentren dentro del rango deseado \\n(80 a 130 mg/dL); se puede ir aumentando la dosiscada vez más, por \\nejemplo, 4 U cada 3 días, si la glucosa en ayuno es > 180 mg/dL\\nSi ocurre hipoglucemia, o los niveles de \\nglucosa en ayuno son < 80 mg/dL, se debe \\nreducir la dosis al acostarse 4 U o 10%(la \\nque sea mayor)\\nSi la glucosa en ayuno se encuentra dentro del rango (80 a 130 mg/dL), se debe revisar la \\nglucosa antes del almuerzo, en la cena y al acostarse; dependiendo de los resultados de \\nglucosa, se añadirá una segunda inyección; se puede iniciar con 4 U y añadir 2 U cada 3 \\ndíashasta que la glucosa se encuentre en rango\\nGlucosa pre almuerzo\\nfuera de rango, añadir \\ninsulina de acción \\nrápidaen el desayuno\\nGlucosa pre cenafuera de \\nrango, añadir insulina NPH\\nen el desayuno o insulina de \\nacción rápida en el almuerzo\\nGlucosa antes de \\nacostarsefuera de rango, \\nañadir insulina de acción \\nrápidaen la cena\\n¿A1c >7% después \\nde 3 meses?\\nSI\\n¿A1c >7% \\ndespués de 3 \\nmeses?\\nSI\\nNO\\nContinuar régimen, checar A1c cada 3 \\nmeses\\nReevaluar glucosa antes de las comidas y si está\\nfuera de rango, se puedeañadir otra inyección; si \\nA1c continúa fuera de rango, evaluar niveles \\nposprandiales a las 2 horas y ajustar insulina de \\nacción rápida preprandial\\nNO\\n \\n \\n \\n \\n \\n \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n \\n2. <Intervención en Salud> \\n \\nTAMIZAJE \\n \\nRecomendación Clave \\nGR* \\nSe recomienda utilizar el cuestionario FINDRISC como herramienta de tamizaje para \\nla detección de riesgo de Diabetes, sobre todo en pacientes con múltiples factores de \\nriesgo. \\nB \\nEl  test  FINDRISC  es  una  herramienta  útil  para  detectar  pacientes  con  alto  riesgo  de  \\ndesarrollar  Diabetes,  sobre  todo  en  aquellos  con  un  puntaje  >9  y  una  glucosa  en  \\nayuno > 100 mg/dL. \\nB \\n \\nDIAGNÓSTICO \\n \\nRecomendación Clave \\nGR* \\nSe  recomienda  utilizar  la  HbA1c  para  confirmar  el  diagnóstico  de  Diabetes  Mellitus  \\nen  pacientes  que  dieron  positivo  en  alguna  prueba  de  tamizaje  y  que  presenten  una  \\nglucemia plasmática en ayunas entre 100 y 125 mg/dL. Un valor > 6.5% confirma el \\ndiagnóstico. \\nA \\nSe recomienda usar la curva de tolerancia a la glucosa oral en pacientes con glucemia \\nplasmática  en  ayunas  entre  100  y  125  mg/dL  y  que  muestren  preferencia  por  ésta  \\nprueba. Un valor > 200 mg/dL a las 2 horas de ingerir una carga de 75 g de glucosa \\nconfirma el diagnóstico. \\nA \\nUnicamente  se  deberán  utilizar  criterios  de  glucosa  plasmática  y  no  de  HbA1c  en  \\ncondiciones  que  incrementen  el  recambio  de glóbulos rojos, como el embarazo (en \\nsegundo  y  tercer  trimestre),  hemodiálisis,  transfusiones  recientes,  tratamiento  con  \\neritropoyetina, enfermedad de células falsiformes, etc. \\nD \\n \\nTRATAMIENTO \\n \\nRecomendación Clave \\nGR* \\nSe  recomienda  iniciar  tratamiento  farmacológico  con  Metformina  y  cambios  en  el  \\nestilo  de  vida  en  pacientes  con  DM2  recién  diagnosticada,  aunque  el  valor  inicial  de  \\nHbA1C esté cerca del valor óptimo. \\nFuerte a \\nfavor \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\nSe recomienda mantener un nivel alto de actividad  física  para  disminuír  el  riesgo  de  \\nmortalidad en pacientes adultos con Diabetes Mellitus tipo 2. \\nA \\nSe recomienda que los pacientes adultos con DM 2 recién diagnosticada se apeguen \\na la dieta mediterránea. \\nA \\nSe recomienda iniciar terapia combinada con metformina y otro antidiabético oral en \\npacientes adultos con DM tipo 2 recién diagnosticada y un nivel de HbA1c >8%. \\nA \\nNo se recomienda iniciar terapia combinada con sulfonilureas como la glibenclamida \\npor el riesgo de hipoglicemia; se sugiere considerar primero otros medicamentos. \\nA \\nNo  se  recomienda  iniciar  terapia  combinada  con  inhibidores  SGLT-2  en  pacientes  \\nadultos  con  diagnóstico  reciente  de  DM  tipo  2,  a  pesar  de  que  favorecen  la  pérdida  \\nde peso; únicamente se utilizarán como una alternativa en caso de que no se puedan \\nutilizar inhibidores DPP-4. \\nA \\nEn pacientes con diagnóstico reciente de Diabetes Mellitus tipo 2 que no alcanzan su \\nmeta  terapéutica  o  no  logran  mantenerla  con  metformina  como  monoterapia,  se  \\nrecomienda  como  primer  paso  agregar  un  inhibidor  DPP-4,  por  su  mejor  balance  \\nriesgo-beneficio. \\nFuerte     a     \\nfavor \\nEn pacientes con diabetes mellitus tipo 2 que no alcanzaron su meta terapéutica o no \\nlogran  mantenerla  con  metformina  como  monoterapia,  se  sugiere  agregar  una  \\nsulfonilurea  con    bajo  riesgo  de  hipoglucemia  (glimepirida,  glicazida)  cuando  los  \\ninhibidores DPP-4 O SGLT2  no están disponibles o se encuentran contraindicados. \\nDébil a \\nfavor \\nSe sugiere añadir como tercer fármaco la insulina basal en aquellos pacientes adultos \\ncon DM tipo 2 que no han alcanzado las metas de control de HbA1c o la han perdido \\ny no tienen obesidad. \\nA \\nSe  recomienda  añadir  como  tercer  fármaco  un  agonista  del  receptor  GLP-1  en  \\naquellos  pacientes  con  DM  tipo  2  que  no  logran  alcanzar  la  meta  de  HbA1c  con  \\nterapia combinada (dos fármacos) o la perdieron y no son obesos. \\nA \\nSe recomienda dar tratamiento con  IECA o ARA II en pacientes adultos con DM tipo \\n2   cuando   se   detecte   microlbuminuria   persistente   aunque   todavía   no   tengan   \\nhipertensión arterial. \\nA \\n \\n*Grado de Recomendación \\n \\n \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n3. CUADROS O FIGURAS \\n \\nCuadro 1. Escala FINDRISC \\n \\nLa  escala  FINDRISC  es  un  instrumento  de  cribaje  inicialmente  diseñado  para  valorar  el  riesgo  \\nindividual de desarrollar DM2 en el plazo de 10 años. \\nLas principales variables que se relacionan con el riesgo de desarrollar DM en esta escala son: edad, \\nIMC,   el   perímetro   de   la   cintura,   hipertensión   arterial   con   tratamiento   farmacológico   y   los   \\nantecedentes personales de glucemia elevada. \\n \\nCada respuesta tiene asignada una puntuación, variando la puntuación final entre 0 y 26. \\n \\nEdad Puntos \\nMenos de 45 años 0 puntos \\nEntre 45-54 años 2 puntos \\nEntre 55-64 años 3 puntos \\nMás de 64 años 4 puntos \\n \\nIMC (kg/m2) Puntos \\nMenos de 25 kg/m2    0 puntos \\nEntre 25/30 kg/m2 1 punto \\nMás de 30 kg/m2 3 puntos \\n \\nPerímetro abdominal \\nHombres                  Mujeres                  Puntos                  \\nMenos de 94 cm Menos de 80 cm     0 puntos \\nEntre 94-102 cm Entre 80-88 cm 3 puntos \\nMás de 102 cm Más de 88 cm 4 puntos \\n \\n¿Realiza normalmente al menos 30 minutos diarios de actividad física? \\nSi                                                                                       0                                                                                       puntos                                                                                       \\nNo  2 puntos \\n \\n¿Con qué frecuencia come frutas, verduras y hortalizas? \\nA diario 0 puntos \\nNo a diario 1 puntos \\n \\n¿Le han recetado alguna vez medicamentos contra la Hipertensión arterial? \\nSi                                                                                       2                                                                                       puntos                                                                                       \\nNo  0 puntos \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n¿Le han detectado alguna vez niveles altos de glucosa en sangre? \\nSi                                                                                       5                                                                                       puntos                                                                                       \\nNo  0 puntos \\n \\n¿Ha habido algún diagnóstico de DM en su familia? \\nNo                                                                                     0                                                                                     puntos                                                                                     \\nSí: abuelos, tíos o primos \\nhermanos (pero no padres, \\nhermanos o hijos) \\n3 puntos \\nSí: padres, hermanos o hijos 5 puntos \\n \\nPuntuación total \\n \\n  \\n \\nPuntuación total Riesgo de desarrollar diabetes en \\nlos próximos10 años \\nInterpretación \\nMenos de 7 puntos 1% Nivel de riesgo bajo \\nDe 7 a 11 puntos 4% Nivel de riesgo ligeramente \\nelevado \\nDe 12 a 14 puntos 17% Nivel de riesgo moderado \\nDe 15 a 20 puntos 33% Nivel de riesgo alto \\nMás de 20 puntos 50% Nivel de riesgo muy alto \\n \\nFuente:  Lindström  J,  Tuomilehto  J.  The  diabetes  risk  score:  a  practical  tool  to  predict  type  2  \\ndiabetes risk. Diabetes Care 2003;26(3):725-31. \\n \\nCuadro 2. Criterios para el diagnóstico de Diabetes ADA 2018 \\n \\nGlucosa plasmática en ayuno ≥ 126 mg/dL (7.0 mmol/L) (Ayuno definido como no haber tenido \\ningesta calórica en las últimas 8 horas). \\no \\nGlucosa plasmática a las 2 horas de ≥200 mg/dL (11.1 mmol/L) durante una prueba oral de \\ntolerancia a la glucosa. La prueba deberá ser realizada con una carga de 75 gramos \\nde glucosa disuelta en agua. \\no \\nHemoglobina   glucosilada   (A1C)   ≥   6.5%.   (48   mmol/mol)   Esta   prueba   debe   realizarse   en   \\nlaboratorios certificados de acuerdo a los estándares A1C del DCCT. \\no \\nPaciente con síntomas clásicos de hiperglicemia o crisis hiperglucémica con una \\nglucosa al azar ≥ 200 mg/dL. \\n \\nFuente: American Diabetes Association. Glycemic Targets: Standards of Medical Care in Diabetes-\\n2018. Diabetes Care. 2018 Jan;41(Suppl 1):S55-S64. \\n \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n \\n \\nCuadro 3. Criterios diagnóstico para Pre-Diabetes 2018 ADA 2018 \\n \\nGlucosa en ayuno 100 a 125 mg/dL \\no \\nGlucosa plasmática a las 2 horas 140 a 199 mg/dL duranta una prueba oral de tolerancia a la \\nglucosa. La prueba debe ser realizada con una carga de 75 g de glucosa disuelta en agua \\no \\nHemoglobina glucosilada (A1C) 5.7 a 6.4% \\n \\nFuente: American Diabetes Association. Glycemic Targets: Standards of Medical Care in Diabetes-\\n2018. Diabetes Care. 2018 Jan;41(Suppl 1):S55-S64. \\n \\nCuadro 4. Ventajas y desventajas de las pruebas diagnósticas para diabetes \\n \\nParámetro Ventajas Desventajas \\nGlucosa      oral      en      \\nayuno \\nEstándar establecido Muestra no estable \\n Rápido y fácil Variabilidad alta en el día a día \\nMuestra única Inconveniente (ayuno) \\nPredice complicaciones \\nmicrovasculares \\nRefleja la homestasis de la glucosa en un único \\npunto en el tiempo \\n   \\nPrueba                     de                     \\ntolerancia  oral  a  la  \\nglucosa   con   carga   \\nde       75       g       con       \\nmedición                 de                 \\nglucosa   en   plasma   \\na las 2 horas \\nEstándar establecido Muestra no estable \\n                                             Predice                                             complicaciones                                             \\nmicrovasculares \\nVariabilidad alta en el día a día \\n                                                       Inconveniente                                                       \\nDesagradable \\nCostosa \\n   \\nHemoglobina A1c \\nConveniente (se puede \\nhacer la medición en \\ncualquier momento del \\ndía) \\nCostosa \\n                                                 Una                                                 única                                                 muestra                                                 Engañosa en presencia de algunas \\nenfermedades (Ej. Hemoglobinopatías, \\ndeficiencia de hierro, anemia hemolítica, \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\nenfermedad renal o hepática severas) \\nPredice complicaciones \\nmicrovasculares \\nSe puede ver alterada por edad o raza \\nMejor predictor de \\nenfermedad \\ncardiovascular que la \\nglucosa oral en ayuno o \\nla prueba de tolerancia \\na glucosa oral a las 2 \\nhoras \\nSe requiere un ensayo validado y \\nestandarizado \\nVariabilidad baja en el \\ndía a día \\nNo se debe utilizar para diagnóstico en niños y \\nadolescentes, ni en pacientes con fibrosis \\nquística ni con sospecha de diabetes tipo 1, ni \\nen mujeres embarazadas en el tamizaje de \\nrutina para diabetes gestacional. \\nRefleja la concentración \\nde glucosa a largo plazo\\n \\n \\nFuente: Adaptado de Sacks DB. A1C versus glucose testing: A comparison. Diabetes Care 2011 \\nFeb; 34(2):518–23. \\n \\nCuadro 5. Fármacos insulino secretores: \\n \\nDosis y Potencia de Acción de las Sulfonilureas \\nFármaco Presentación tabletas Dosis diaria (mg) Potencia \\nTolbutamida                                       500                                       1000-2000                                       ++                                       \\nClorpropamida                                   250                                   250-500                                   ++++                                   \\nGlibenclamida                                       5                                       5-20                                       ++++                                       \\nGliclazida                                  80                                  160-240                                  ++                                  \\nGlipizida                                                 5                                                 5-20                                                 +++                                                 \\nGlimepirida 2 y 4 2-8 ++++ \\n \\nDosis de las Meglitinidas \\nFármaco Dosis tableta (mg) Dosis diaria (mg) \\nRepaglinida 0.5 – 1 - 2 1.5 a 12 \\nNateglinida 120 60 a 360 \\n \\nAnálogos del GLP 1 \\nFármaco Presentación inyectable Dosis diaria \\nExenatide 5 - 10 10 c/12 hr \\n \\nInhibidores de la DPP-4 (Gliptinas) \\nFármaco Presentación tabletas (mg) Dosis diaria (mg) \\nSitagliptina                                                                100                                                                100                                                                \\nVildagliptina                                                                50                                                                50-100                                                                \\n\\nDiagnóstico y Tratamiento Farmacológico de la Diabetes Mellitus Tipo 2 en el Primer Nivel de Atención \\n \\n \\n \\n \\nCuadro 6. Fármacos insulino-sensibilizadores: \\n \\nFármaco Presentación tabletas (mg) Dosis diaria (mg) \\nMetformina 500, 850, 1000 500-2550 \\nMetformina acción prolongada 500, 750, 1000 500-2550 \\n \\nCuadro 7. Tiazolidinedionas (glitazonas): \\n \\nFármaco Dosis tabletas (mg) Dosis diaria (mg) \\nRosiglitazona 4 - 8 8 \\nPioglitazona                                                            15-30                                                            45                                                            \\n \\nCuadro  8:  Inhibidores  de  la  absorción  intestinal  de  monosacáridos  (inhibidores  de  alfa  \\nglucosidasas intestinales) \\n \\nFármaco Presentación tabletas (mg) Dosis diaria (mg) \\nAcarbosa 50 y 100 50-300 \\n \\nFuente:  Gobierno  de  Chile.  Ministerio  de  Salud.  Guía  Clínica  Diabetes  Mellitus  Tipo  2.  Serie  Guías  \\nClínicas Minsal. Santiago, Minsal, 2010."}'::jsonb, false, 6619, '2026-11-26 05:16:29.776+00') ON CONFLICT (gpc_id, source_type) DO UPDATE SET content_json = EXCLUDED.content_json, is_stale = false, tokens_used = EXCLUDED.tokens_used, processed_at = EXCLUDED.processed_at;
